enum Role {
  CUSTOMER
  SUPPORT
  BILLING
  ADMIN
  // A limited-access staff member with hand-picked page/tool grants (see
  // StaffGrant) rather than a fixed bundle of areas. Deliberately NOT named
  // "STAFF" — isStaff() in lib/rbac.ts already means SUPPORT|BILLING|ADMIN in
  // ~8 call sites, and a same-named role would silently read as included
  // there when it isn't. EMPLOYEE gets zero admin-area access by default;
  // every area it can reach comes from an explicit StaffGrant row.
  EMPLOYEE
}
enum ServerStatus {
  PENDING
  PROVISIONING
  RUNNING
  STOPPED
  SUSPENDED
  REINSTALLING
  DELETING
  ERROR
}
enum JobStatus {
  QUEUED
  RUNNING
  DONE
  FAILED
}
enum JobType {
  PROVISION
  START
  STOP
  REBOOT
  REINSTALL
  DELETE
  SUSPEND
  UNSUSPEND
  RESIZE
  SNAPSHOT_CREATE
  SNAPSHOT_DELETE
  SNAPSHOT_ROLLBACK
  BACKUP_CREATE
  BACKUP_RESTORE
  SYNC_FORWARDS
  SYNC_FIREWALL
  SYNC_GAME_DNS // keep worker/game-subdomain-sync.ts's syncGameServerDns in sync with the server's actual ip:port
  PASSWORD_RESET
  CLAUDE_BUILD
  GAME_UPDATE
  VOLUME_CREATE
  VOLUME_ATTACH
  VOLUME_DETACH
  VOLUME_DELETE
  GAME_CONFIG
  SSL_ISSUE
  MIGRATE
  WEBSITE_CREATE
  WEBSITE_DELETE
  WEBSITE_TOGGLE
  WEBSITE_SSL
  SITE_PUBLISH
  SITE_UNPUBLISH
  DB_CREATE
  DB_DELETE
  APP_INSTALL
  CRON_SYNC
  SERVICE_ACTION
  DISK_EXPAND
  // Post-deploy dedicated-IP add-on for an already-provisioned server (VPS or
  // game) that didn't have one — lib/dedicated-ip-purchase.ts + worker/index.ts.
  ASSIGN_DEDICATED_IP
  // Game server control panel (worker/game-control.ts).
  GAME_POWER // start / stop / restart the game SERVICE (distinct from VM power)
  GAME_BACKUP // archive the game's world/save dir into a downloadable backup
  GAME_MOD_SYNC // reconcile the server's installed mods (install INSTALLING, remove REMOVING)
}
enum TicketStatus {
  OPEN
  ANSWERED
  CUSTOMER_REPLY
  CLOSED
}
enum TicketPriority {
  LOW
  NORMAL
  HIGH
  URGENT
}
enum DomainStatus {
  PENDING
  ACTIVE
  FAILED
  EXPIRED
  // Inbound transfer states. An ICANN transfer takes 5-7 days and needs the
  // owner to approve an email from the LOSING registrar, so an inbound domain
  // sits here far longer than a registration sits in PENDING — it gets its own
  // state so the UI can tell the customer the truth about what happens next.
  TRANSFER_PENDING
  TRANSFER_FAILED
}
enum ImageCategory {
  PLAIN_OS
  CONTROL_PANEL
  APPLICATION
}
enum BackupTier {
  FREE
  PLUS
  PRO
  PREMIUM
}
enum FirewallDirection {
  INBOUND
}
enum FirewallAction {
  ALLOW
  DENY
}
enum FirewallProtocol {
  TCP
  UDP
  ICMP
  ALL
}
enum ReviewSource {
  INTERNAL
  GOOGLE
  TRUSTPILOT
  HOSTADVICE
}
enum DedicatedIpStatus {
  FREE
  ASSIGNED
  PENDING
  RELEASING
}
enum DedicatedIpPurpose {
  CUSTOMER
  INTERNAL
}
enum NodeStatus {
  ONLINE
  OFFLINE
  MAINTENANCE
}
enum InvoiceStatus {
  OPEN
  PAID
  VOID
  REFUNDED
}
enum CouponKind {
  PERCENT // value = percent 1-100 (discount on order/topup)
  FIXED_CENTS // value = cents off
  CREDIT_CENTS // value = cents of wallet credit granted on redemption
}
enum CouponScope {
  ANY
  TOPUP
  ORDER
}
enum CouponServiceKind {
  ANY
  VPS
  GAME
}
enum HostingNodeStatus {
  ONLINE
  DEGRADED
  OFFLINE
}
enum HostingAccountStatus {
  PENDING // created, waiting for the provisioner
  PROVISIONING
  ACTIVE
  SUSPENDED
  FAILED
  DELETING
}
enum HostingClaimKind {
  PRIMARY
  SUBDOMAIN
  ADDON
}
enum HostingTaskKind {
  PHP_SWITCH
  WORDPRESS_INSTALL
  APP_INSTALL
  BACKUP
  RESTORE
  // Account lifecycle — enacted by the provisioner (inert until ENABLE_SHARED_HOSTING).
  SUSPEND // disable vhost + FPM pool + lock the unix user (reversible)
  UNSUSPEND // reverse a SUSPEND
  TERMINATE // remove vhost/FPM, delete the jailed user + home, drop scoped DBs
  // cPanel-class site management — each queues one node operation (inert until enabled).
  CREATE_SUBDOMAIN // mkdir a docroot + write/enable a <label>.<primary> vhost
  DELETE_SUBDOMAIN // reverse: remove the vhost + docroot
  CREATE_ADDON_DOMAIN // full external domain: own docroot + vhost
  DELETE_ADDON_DOMAIN // reverse: remove the vhost + docroot
  CREATE_CRON // (re)write the jailed user's crontab from its ACTIVE cron rows
  DELETE_CRON // remove a cron row + rewrite the crontab
  // Drop the Adminer DB manager into the account webroot (served by the account's
  // own FPM socket; login is the customer's scoped DB user — no root, no auto-login).
  INSTALL_DBTOOL
  // Create/repair the account-level scoped MySQL user for the proprietary in-portal
  // DB manager (granted on `<username>\_%`.* only). Idempotent. See taskEnsureDbMgr.
  ENSURE_DBMGR
  // Re-apply the account's snapshotted plan limits on the node after a plan upgrade
  // (raise the disk quota via setquota; rewrite the FPM pool). Idempotent.
  APPLY_PLAN_LIMITS
  // Change a scoped MySQL user's password on the node (customer-initiated DB
  // password reset). Runs ALTER USER … IDENTIFIED BY. Idempotent. See taskResetDbPassword.
  RESET_DB_PASSWORD
  // Promote a real domain (an existing ACTIVE addon domain) to the account's
  // primaryDomain: regenerate the primary vhost hosting-<user>.conf with the new
  // domain as server_name, KEEP the old primary hostname as an alias server_name
  // (so the old address keeps working), run `wp search-replace`+`option update`
  // when WordPress is detected in the primary docroot, then flip DB primaryDomain
  // and re-key the hostname claims. Worst-case safe: on any failure the old
  // address keeps serving and primaryDomain is left unchanged. See taskSetPrimaryDomain.
  SET_PRIMARY_DOMAIN
}
