/* ── Isometric server-stack hero illustration. Pure SVG so it themes cleanly and
      needs no asset. Three stacked blades on an iso base with glowing brand edges,
      status LEDs and a soft ground glow — reads clearly as a server. To swap in a
      real render later, replace this element with <img src="…" /> — nothing else
      depends on it. */
function ServerRackArt({ className }: { className?: string }) {
  // Three stacked iso blades; each is a top face + front face + side face.
  const blades = [0, 1, 2];
  return (
    <svg viewBox="0 0 320 300" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden>
      <defs>
        <linearGradient id="hubTop" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#1b2646" />
          <stop offset="1" stopColor="#121a34" />
        </linearGradient>
        <linearGradient id="hubFront" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#131c38" />
          <stop offset="1" stopColor="#0b1226" />
        </linearGradient>
        <linearGradient id="hubSide" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#0d1428" />
          <stop offset="1" stopColor="#080d1c" />
        </linearGradient>
        <linearGradient id="hubEdge" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#8a70fb" />
          <stop offset="1" stopColor="#22d3ee" />
        </linearGradient>
        <radialGradient id="hubGlow" cx="0.5" cy="0.5" r="0.5">
          <stop offset="0" stopColor="#6f47f5" stopOpacity="0.55" />
          <stop offset="1" stopColor="#6f47f5" stopOpacity="0" />
        </radialGradient>
      </defs>

      {/* ground glow */}
      <ellipse cx="160" cy="256" rx="120" ry="30" fill="url(#hubGlow)" />

      {blades.map((b) => {
        // iso projection: each blade sits 46px higher than the last.
        const oy = 190 - b * 46;
        const dx = 120; // half-width along the iso X
        const dz = 60; // depth along iso Y
        const h = 26; // blade thickness (front face)
        const cx = 160;
        // key points of the top rhombus
        const top = `${cx},${oy - dz / 2} ${cx + dx},${oy} ${cx},${oy + dz / 2} ${cx - dx},${oy}`;
        const led = b === 1 ? "#22d3ee" : "#8a70fb";
        return (
          <g key={b}>
            {/* top face */}
            <polygon points={top} fill="url(#hubTop)" stroke="url(#hubEdge)" strokeWidth="1.25" strokeOpacity="0.6" />
            {/* front-left face */}
            <polygon
              points={`${cx - dx},${oy} ${cx},${oy + dz / 2} ${cx},${oy + dz / 2 + h} ${cx - dx},${oy + h}`}
              fill="url(#hubFront)"
            />
            {/* front-right face */}
            <polygon
              points={`${cx},${oy + dz / 2} ${cx + dx},${oy} ${cx + dx},${oy + h} ${cx},${oy + dz / 2 + h}`}
              fill="url(#hubSide)"
            />
            {/* glowing seam along the front bottom edge */}
            <polyline
              points={`${cx - dx},${oy + h} ${cx},${oy + dz / 2 + h} ${cx + dx},${oy + h}`}
              stroke="url(#hubEdge)"
              strokeWidth="1.5"
              strokeOpacity="0.85"
              fill="none"
            />
            {/* drive slots on the left face */}
            {[0, 1, 2].map((s) => (
              <line
                key={s}
                x1={cx - dx + 16 + s * 30}
                y1={oy + 12 + (16 + s * 30) * (dz / 2 / dx)}
                x2={cx - dx + 30 + s * 30}
                y2={oy + 12 + (30 + s * 30) * (dz / 2 / dx)}
                stroke="#2b3a63"
                strokeWidth="3"
                strokeLinecap="round"
              />
            ))}
            {/* status LEDs on the right face */}
            <circle cx={cx + dx - 16} cy={oy + 13} r="3.2" fill={led}>
              <animate attributeName="opacity" values="0.4;1;0.4" dur={`${2 + b * 0.5}s`} repeatCount="indefinite" />
            </circle>
            <circle cx={cx + dx - 16} cy={oy + 21} r="3.2" fill="#22d3ee" opacity="0.5" />
          </g>
        );
      })}
    </svg>
  );
}

export function DeployHub({
  vps,
  hosting,
  game,
  email,
  hostingPromoOn = false,
}: {
  /** null when no active plans/images are configured (VPS deploy unavailable). */
  vps: VpsProps | null;
  hosting: HostingProps;
  /** null when no game families have active tiers. */
  game: GameProps | null;
  email: EmailProps;
  /** The first-month-free promo is RUNNING (offer exists) — drives the marketing
   *  "1st month free" badge on the Shared Hosting tab. The actual $0-vs-full price
   *  at checkout stays gated per-account/IP (hosting.firstMonthFree). */
  hostingPromoOn?: boolean;
}) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const initial = searchParams.get("product");
  const [active, setActive] = useState<DeployProduct>(isProduct(initial) ? initial : "vps");

  const select = useCallback(
    (p: DeployProduct) => {
      setActive(p);
      // Deep-link without a full navigation so the mounted wizard/state is preserved.
      const params = new URLSearchParams(Array.from(searchParams.entries()));
      params.set("product", p);
      router.replace(`/dashboard/deploy?${params.toString()}`, { scroll: false });
    },
    [router, searchParams]
  );

  const activeAccent = ACCENTS[active];

  const wizard = useMemo(() => {
    // Only the ACTIVE product's wizard is ever mounted.
    switch (active) {
      case "vps":
        return vps ? (
          <DeployWizard {...vps} />
        ) : (
          <EmptyState
            title="Deployments are temporarily unavailable"
            sub="No active plans or images are configured. Please check back soon or contact support."
          />
        );
      case "hosting":
        return (
          <div className="space-y-3">
            {/* Display-only promo banner — the charge decision lives in orderHostingAccount.
                Shown only when THIS user is eligible (firstMonthFreeEligible), computed on
                the deploy page exactly as the old hosting page did. */}
            {hosting.firstMonthFree && hosting.plans.length > 0 && (
              <div className="flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-300">
                <span className="flex h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400 animate-pulse-dot" />
                Your first month is free on shared hosting — then the price you sign up at is the price you renew at.
              </div>
            )}
            <HostingDeployWizard {...hosting} />
          </div>
        );
      case "game":
        return game ? (
          <GameDeployWizard {...game} />
        ) : (
          <EmptyState
            title="No game plans available yet"
            sub="Game server plans aren't configured yet. Check back soon, or open a ticket and we'll let you know when they're live."
          />
        );
      case "email":
        // On the deploy page this is an ORDER surface only — the subscription /
        // mailbox management list lives on /dashboard/email (linked in the header).
        return <EmailHosting {...email} showSubscriptions={false} />;
    }
  }, [active, vps, hosting, game, email]);

  return (
    <div className="space-y-6">
      {/* ── Compact hero + product selector in one panel ─────────────────────── */}
      <section className="relative overflow-hidden rounded-3xl border border-white/[0.06] bg-navy-900/60 p-4 sm:p-5">
        <div aria-hidden className="hero-aura pointer-events-none absolute inset-0" />
        {/* Decorative server-stack, confined to the HEADER band (top-right) and faded
            left so it never sits behind the product cards below — keeps the hero clean. */}
        <ServerRackArt className="pointer-events-none absolute right-1 top-1 hidden h-[132px] w-auto opacity-25 [mask-image:linear-gradient(to_left,black_55%,transparent)] lg:block" />

        {/* slim header row */}
        <div className="relative flex flex-wrap items-center justify-between gap-3 px-1">
          <div className="min-w-0">
            <span className="eyebrow-pill mb-2">
              <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Nxeon · Deploy
            </span>
            <h1 className="text-2xl font-black tracking-tight text-white sm:text-[1.7rem]">
              <span className="grad-text">Deploy</span> Your Server
            </h1>
          </div>
          <p className="max-w-xs text-sm leading-relaxed text-slate-400">
            Launch a VPS, shared-hosting site, game server, or business email in minutes.
          </p>
        </div>

        {/* product selector: the four cards ARE the tabs */}
        <div role="tablist" aria-label="Product" className="relative mt-4 grid gap-2.5 sm:grid-cols-2 lg:grid-cols-4">
          {PRODUCTS.map((id) => {
            const a = ACCENTS[id];
            const isActive = active === id;
            return (
              <button
                key={id}
                role="tab"
                aria-selected={isActive}
                onClick={() => select(id)}
                className={`group relative flex items-start gap-3 rounded-2xl border bg-navy-950/50 p-3.5 text-left transition-all ${
                  isActive ? a.activeCard : "border-white/[0.06] hover:border-white/15"
                }`}
              >
                <span className={`inline-flex h-10 w-10 flex-none items-center justify-center rounded-xl bg-gradient-to-br text-white ${a.tile} ${a.tileGlow}`}>
                  <a.Icon className="h-5 w-5" />
                </span>
                <span className="min-w-0">
                  <span className="flex items-center gap-1.5">
                    <span className={`text-sm font-semibold ${isActive ? "text-white" : "text-slate-100"}`}>{a.label}</span>
                    {id === "hosting" && hostingPromoOn ? (
                      <span className="rounded-full border border-emerald-500/40 bg-emerald-500/15 px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide text-emerald-300">
                        1st Month Free
                      </span>
                    ) : (
                      a.badge && (
                        <span className={`rounded-full border px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide ${a.badge.cls}`}>
                          {a.badge.text}
                        </span>
                      )
                    )}
                  </span>
                  <span className="mt-0.5 block text-xs leading-snug text-slate-400">{a.desc}</span>
                  <span className={`mt-1.5 inline-flex items-center gap-1 text-xs font-medium transition-transform group-hover:translate-x-0.5 ${a.text}`}>
                    {isActive ? "Selected" : "Choose"} <span aria-hidden>→</span>
                  </span>
                </span>
              </button>
            );
          })}
        </div>

      </section>

      {/* ── Active product's wizard ──────────────────────────────────────────── */}
      <div>
        {/* No repeated product-name heading here — the product card row above
            (and its "Selected" state) already identifies which wizard is active;
            a second label right above the step indicator was pure redundancy. */}
        {active === "email" && (
          <div className="mb-4 flex justify-end">
            <a
              href="/dashboard/email"
              className="inline-flex items-center gap-1 text-xs font-medium text-blue-300 hover:text-blue-200"
            >
              Manage your email subscriptions →
            </a>
          </div>
        )}
        {wizard}
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { stripeConfigured, createTopUpPaymentSession } from "@/lib/stripe";
import { getSettingInt } from "@/lib/settings";

/** Set by `components/customer/CouponField`; read by `topUp`'s demo gateway only. */
const COUPON_COOKIE = "nxeon_coupon";

export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!stripeConfigured()) {
    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
  }
  const { amount } = await req.json().catch(() => ({}));
  const dollars = Number(amount);
  if (!Number.isFinite(dollars) || dollars > 5000) {
    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
  }
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (Math.round(dollars * 100) < minTopup) {
    return NextResponse.json(
      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
      { status: 400 },
    );
  }

  // A promo code must never be silently dropped at the moment money moves.
  //
  // `CouponField` stores an accepted code in this cookie for an hour, and the ONLY
  // reader is the demo gateway in `topUp`. This route charges the card and
  // `creditCheckoutSession` credits `session.amount_total` verbatim, so a bonus
  // simply cannot be added here — and Stripe's own `discounts` /
  // `allow_promotion_codes` are the wrong instrument for a wallet top-up: they
  // reduce `amount_total`, which reduces the credit by the same cents, leaving the
  // customer exactly where they started. So a cookie surviving into this path
  // (e.g. Stripe was configured after the code was accepted) would mean paying
  // full price with a code the UI said was applied — the audit's finding #8.
  //
  // Refuse, say why, and clear the cookie in the same response so the immediate
  // retry succeeds. Nothing has been charged at this point: no session exists yet.
  const staleCoupon = req.cookies.get(COUPON_COOKIE)?.value?.trim();
  if (staleCoupon) {
    const shown = staleCoupon.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32).toUpperCase();
    const res = NextResponse.json(
      {
        error: `Promo code ${shown || "on this account"} can’t be applied to a card payment. We’ve removed it — press Add funds again to continue without it.`,
