import { NextRequest, NextResponse } from "next/server";
import { stripe, stripeConfigured } from "@/lib/stripe";
import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";
import { releaseReservation } from "@/lib/promo-redemption";
import { releaseOrderCouponReservation } from "@/lib/coupon-redemption";
import type Stripe from "stripe";

export async function POST(req: NextRequest) {
  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
    return NextResponse.json({ error: "not configured" }, { status: 400 });
  }
  const sig = req.headers.get("stripe-signature");
  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
  const raw = await req.text();

  let event;
  try {
    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch {
    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object as { id: string };
    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
    // throw the result away, which meant the webhook credited the wallet and then
    // — by winning the race — caused the success-redirect to see `credited: false`
    // and skip provisioning entirely. The webhook is the reliable signal (the
    // redirect may never happen at all), so it must be able to fulfil on its own.
    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
    // two callers racing is safe: exactly one does the work.
    //
    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
    // event, and the failure is already recorded on the FulfilledSession row and
    // surfaced to the customer.
    try {
      await fulfilCheckoutSession(session.id);
    } catch (e) {
      console.error("[stripe-webhook] fulfil failed", session.id, e);
    }
  }

  // A checkout the customer never completed: Stripe expires it (we cap the payable
  // window at ORDER_CHECKOUT_EXPIRES_MS). RELEASE any first-month-free hold it carried
  // so the customer's one-time offer is returned promptly rather than waiting for the
  // worker sweep. Guarded to RESERVED, so a completed+confirmed grant is never revoked.
  // (If this event type isn't enabled in the Stripe dashboard, the worker sweep is the
  // backstop — the hold's reservedUntil has passed by the time the session expires.)
  if (event.type === "checkout.session.expired") {
    const session = event.data.object as Stripe.Checkout.Session;
    const token = session.metadata?.nxeonPromoReservation;
    if (token) {
      try {
        await releaseReservation(token);
      } catch (e) {
        console.error("[stripe-webhook] release reservation failed", token, e);
      }
    }
    // Same for a checkout-coupon hold — return its per-person slot AND its global-cap
    // slot (timesRedeemed decrement inside releaseOrderCouponReservation). Guarded to
    // RESERVED, so a completed+confirmed CONSUMED redemption is never revoked.
    const couponToken = session.metadata?.nxeonCouponReservation;
    if (couponToken) {
      try {
        await releaseOrderCouponReservation(couponToken);
      } catch (e) {
        console.error("[stripe-webhook] release coupon reservation failed", couponToken, e);
      }
    }
  }

  return NextResponse.json({ received: true });
}

