  /**
   * Paid backup RETENTION tier bought at deploy time. FREE (included) or PLUS
   * (keep 7, priced monthly like the other add-ons). Round-tripped through Stripe
   * metadata, so it stays a tiny string.
   */
  backupTier?: BackupTier;
  /**
   * Set by payAndDeploy from the nx_partner_ref cookie (lib/partner.ts) when the
   * customer arrived via a partner deep link (?ref=kodely). Round-tripped through
   * Stripe metadata like the other optional fields above, then persisted onto the
   * created Server row so worker/index.ts knows whether to notify the partner on
   * provision success — undefined (never the literal string) for a direct order.
   */
  partnerSource?: string;
};

/**
 * The price an order was SOLD at: the total, and the promo rate that produced it.
 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
 *
 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
 * path quoted a total, charged the CARD its share of that total at Stripe, and
 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
 * and lib/promotions.ts always has an active sale that rotates by calendar date,
 * so a rotation between "customer clicked Deploy" and "customer came back from
 * Stripe" re-priced the order AFTER the card had cleared and took the difference
 * out of the wallet with no new consent. With no balance to take it from, the
 * payment was captured and no server was created.
 *
 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
 * Stripe metadata for exactly this reason; the order path was the one that
 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
 * the customer was shown is not recomputed later, it is carried.
 *
 * `promoPercent` and `promoName` travel WITH the total because they are not
 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
 * at (every later proration prices against it), and the promo name is the ledger
 * and invoice text the customer reads. Honouring a 30%-off price while stamping
 * today's 15% would hand every later proration the wrong basis and print a
 * discount on the invoice that does not match the money taken.
 */
export type OrderPrice = {
  /**
   * The NET (pre-tax) total the customer consented to, in cents. Its meaning is
   * unchanged by Finding 1 — every promo/coupon/proration figure is computed against
   * this net. The amount actually CHARGED is `chargeCents + (taxCents ?? 0)`.
   */
  chargeCents: number;
  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
  promoPercent: number;
  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
  promoName: string;
  /**
   * VAT/GST on the net (Finding 1), carried through the card round-trip so the
   * confirm route settles the SAME tax-inclusive total the card leg was split from
   * — never re-derived after the card cleared. Absent on legacy/full-price sessions,
   * in which case the charge path recomputes it from the owner's country (0 by
   * default), which can only ever undertax, the conservative direction.
   */
  taxCents?: number;
  taxRatePercent?: number;
  taxCountry?: string;
};

/**
 * The sold price implied by a quote — the ONE place a quote becomes a price. An
 * optional resolved tax context stamps the VAT the card round-trip must settle.
 */
export function orderPriceOf(
  quote: {
    chargeCents: number;
    promo: { discountPercent: number; name: string };
  },
  tax?: { taxCents: number; ratePercent: number; country: string } | null,
): OrderPrice {
  return {
    chargeCents: quote.chargeCents,
    promoPercent: quote.promo.discountPercent,
    promoName: quote.promo.name,
    ...(tax
      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
      : {}),
  };
}

/**
 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
 * well-formed: a half-parsed price would be worse than no price at all, because
 * the caller's fallback (re-quote) is at least internally consistent.
 */
export function parseOrderPrice(raw: unknown): OrderPrice | null {
  let obj: unknown = raw;
  if (typeof raw === "string") {
    try {
      obj = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== "object") return null;
  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
    obj as Record<string, unknown>;
  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
  if (promoPercent < 0 || promoPercent > 100) return null;
  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
  // malformed tax field) carries none, and the charge path recomputes tax from the
  // owner's country — which undertaxes at worst, never overcharges.
  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
  const tr =
    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
      ? taxRatePercent
      : 0;
  return {
    chargeCents,
    promoPercent,
    promoName: typeof promoName === "string" ? promoName : "",
    taxCents: tc,
    taxRatePercent: tr,
    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
  };
}

/** Extract a plain OrderIntent from a deploy form. */
export function intentFromFormData(formData: FormData): OrderIntent {
  return {
    planId: String(formData.get("planId") ?? ""),
    osTemplateId: String(formData.get("osTemplateId") ?? ""),
    hostname: String(formData.get("hostname") ?? ""),
    nodeId: String(formData.get("nodeId") ?? "") || undefined,
    addonMalware: formData.get("addon_malware") === "1",
    addonBackup: formData.get("addon_backup") === "1",
    addonDocker: formData.get("addon_docker") === "1",
    termMonths: Number(formData.get("termMonths") ?? 1),
    dedicatedIp: formData.get("dedicatedIp") === "1",
    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
    free: formData.get("free") === "1",
    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
    // bought so it drops out of JSON.stringify: the intent is round-tripped
    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
    // createOrderCheckout), and every byte of headroom matters there.
    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
    // Only PLUS is a paid choice; left UNDEFINED for FREE (the included tier) so it
    // drops out of the Stripe-metadata JSON round-trip, like extraDiskGB. orderQuote
    // re-normalizes undefined back to FREE.
    backupTier: normalizeBackupTier(formData.get("backup_tier")) === "PLUS" ? "PLUS" : undefined,
  };
}

/**
 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
 * a node this order would push to/past the CRITICAL capacity threshold when
 * another node has room. Falls back to primary (any node) when every candidate is
 * already critical — the scheduler never REFUSES an order for a capacity warning
 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
 * roomier node when one exists. DB-only so order placement never blocks on a
 * Proxmox round trip.
 */
/** Validate + price an order without placing it. Throws OrderError on any problem. */
export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
  const parsed = orderSchema.safeParse(intent);
  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
  // A ONE-OFF CUSTOM plan (lib/custom-plan.ts createCustomPlan, "build a custom
  // server") is deliberately created `active: false` — every plain
  // `where: { active: true }` catalog/resize-picker/marketing query in this
  // codebase (30+ call sites, none scoped to a single order or customer) must
  // never surface it as a generically pickable tile. But it must still be a
  // valid target for the ONE order that just built it, so `sortOrder` — the
  // existing marker reserved for exactly this row shape — is accepted here as an
  // alternative to `active`. No other code path needs this carve-out: renewals
  // (lib/renewal-charge.ts) never check `active` at all, and the resize-target
  // picker's own `where: { active: true }` query correctly keeps a custom plan
  // out of every OTHER customer's upgrade options with no change needed there.
  const planPurchasable = !!plan?.active || plan?.sortOrder === CUSTOM_PLAN_SORT_ORDER;
  if (!planPurchasable || !os?.active) throw new OrderError("Plan or OS not available.");
  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
    throw new OrderError(
      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
    );
  }
  const term = vpsTerm(Number(intent.termMonths ?? 1));
  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
  const annualPct = await annualDiscountPct();
  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;

  // Extra root disk, priced per GB/month and multiplied over the term exactly
  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
  // promo — the customer pays the same $/GB whichever term they pick, and renews
  // at the same rate). Growth is one-way: this is permanent for the server.
  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
  const extraDiskCents = extraDiskMonthlyCents * term.months;
  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
  }

  // Paid backup RETENTION tier, priced per month and multiplied over the term
  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
  // the same $/mo whichever term or promo, and renews at the same rate through
  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
  const backupTier = normalizeBackupTier(intent.backupTier);
  const backupMonthlyCents =
    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
  const backupCents = backupMonthlyCents * term.months;

  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
  // real renewal price and this discounted value is the real first-term price.
  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
  // (Dedicated IP is billed at full price; the promo only touches the plan.)
  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);

  // LOW intro price → RENEWS at regular. A per-plan `introPriceCents` (set by an
  // admin) makes the FIRST term cheaper and leaves every renewal at the regular
  // `priceCents` — renewal code never reads the intro column, so renewal === regular
  // by construction (lib/renewal-charge.ts). Modelled as a first-term REDUCTION of
  // the regular term total (not a second price), so the regular term stays the one
  // basis renewals bill and proration prices against. `introDiscountCents` is 0 for
  // every plan without an intro price, so the whole VPS flow below is unchanged for
  // them. VPS never carries the first-month-free promo (`firstMonthFreeAppliesTo`),
  // so intro and FMF never stack here.
  const introMonthlyCents = planIntroMonthlyCents(plan);
  const introTermMonths = planIntroTermMonths(plan);
  const introDiscountCents = introFirstTermDiscountCents(
    plan.priceCents,
    introMonthlyCents,
    term.months,
    introTermMonths,
    annualPct,
  );
  // The plan-portion cash the FIRST term is sold at, intro applied. Renewals ignore it.
  const introFirstTermPlanCents = Math.max(0, regularPlanCents - introDiscountCents);
  // The rate this first term is sold at (percent off the regular term total) — stamped
  // on Server.termPromoPercent below via the promo object so proration/refunds price
  // against it exactly like a seasonal promo.
  const introPercent = introSoldPercent(regularPlanCents, introDiscountCents);
  const introRenewalMonthly = plan.priceCents; // what the "then $X/mo" copy quotes
  // When a plan has an intro price we present it THROUGH the same `promo` channel the
  // seasonal-sale plumbing uses (name + percent travel on OrderPrice and stamp
  // termPromoPercent). `firstMonthFree: false` keeps it out of the one-month-free
  // redemption machinery — an intro price has no per-account cap; it is simply this
  // plan's first-term price.
  const promo =
    introDiscountCents > 0
      ? {
          id: "intro-price",
          name: `Intro price — renews at $${(introRenewalMonthly / 100).toFixed(2)}/mo`,
          label: "Intro price",
          discountPercent: introPercent,
          firstMonthFree: false,
        }
      : currentPromo(new Date());
  // The promo is now MANAGED: the owner can switch it off, and every claim is
  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
  // quote shows — and placeOrder charges — the full price, so display === charged
  // on the disabled path. When it is on, the quote shows the first-month-free
  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
  // the credit is actually granted (a lost race there is charged full).
  // `suppressPromo` prices this quote at FULL price even when the promo is on —
  // the card path uses it to re-quote for a customer who has already redeemed
  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
  // false here and planFirstTermCents falls through to the regular term total.
  const promoEnabled =
    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
  // YEARS free. So we subtract one month of the plan's rate from the term total.
  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
  // 36-month term the customer pays the term minus one month. Renewals bill the
  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
  const planFirstTermCents =
    promoEnabled && promo.firstMonthFree
      ? Math.max(0, regularPlanCents - plan.priceCents)
      : regularPlanCents;
  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
  // promo is off. placeOrder adds it back to charge full when the claim is lost.
  const promoCreditCents = regularPlanCents - planFirstTermCents;

  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
  // so the deploy preview can show it; the redemption itself (count + per-user +
  // per-IP guards) is claimed atomically in placeOrder.
  let couponId: string | null = null;
  let couponDiscountCents = 0;
  let couponLabel = "";
  let couponError = "";
  let couponMaxRedemptions: number | null = null;
  let couponFirstTimeOnly = false;
  const code = (intent.couponCode ?? "").trim().toUpperCase();
  if (code) {
    if (!(await getSettingBool("coupons_enabled", true))) {
      couponError = "Promo codes are currently disabled.";
    } else {
      const coupon = await db.coupon.findUnique({ where: { code } });
      if (!coupon) {
        couponError = "That code isn’t valid.";
      } else {
        const verdict = couponOrderDiscountCents(
          {
            kind: coupon.kind,
            value: coupon.value,
            serviceKind: coupon.serviceKind,
            planSlug: coupon.planSlug,
            maxTermMonths: coupon.maxTermMonths,
            active: coupon.active,
            expiresAt: coupon.expiresAt,
            maxRedemptions: coupon.maxRedemptions,
            timesRedeemed: coupon.timesRedeemed,
            minAmountCents: coupon.minAmountCents,
          },
          {
            serviceKind: "VPS",
            planSlug: plan.slug,
            planMonthlyCents: plan.priceCents,
            termMonths: term.months,
            // Coupon discounts the intro-reduced plan portion, so an intro price and a
            // coupon cannot together drive the plan charge below zero, and a percentage
            // coupon is honestly "% off what you actually pay this term".
            planChargeCents: introFirstTermPlanCents,
          },
          new Date(),
        );
        if (verdict.ok) {
          couponId = coupon.id;
          couponDiscountCents = verdict.discountCents;
          couponLabel = verdict.label;
          couponMaxRedemptions = coupon.maxRedemptions;
          couponFirstTimeOnly = coupon.firstTimeOnly;
        } else {
          couponError = verdict.error;
        }
      }
    }
  }

  const chargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
  return {
    plan,
    os,
    term,
    chargeCents,
    // Intro pricing (0 / null on plans without one). `introDiscountCents` is the
    // first-term saving already baked into `chargeCents`; `introFirstTermPlanCents`
    // is the plan-portion cash the first term is sold at; the monthly figures drive
    // the honest "$intro first term, then $regular/mo" copy on the pricing cards.
    introDiscountCents,
    introFirstTermPlanCents,
    introMonthlyCents,
    introTermMonths,
    introRenewalMonthly,
    introPercent,
    // The annual-discount rate this quote was priced at — snapshot onto the Server at
    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
    // nets to zero even if the admin retunes `annual_discount_percent` in between.
    annualPct,
    promo,
    promoCreditCents,
    regularPlanCents,
    extraDiskGB,
    extraDiskMonthlyCents,
    extraDiskCents,
    backupTier,
    backupMonthlyCents,
    backupCents,
    couponId,
    couponDiscountCents,
    couponLabel,
    couponError,
    couponMaxRedemptions,
    couponFirstTimeOnly,
  };
}

/**
 * Place an order: validate, charge the wallet (unless a free admin grant),
 * create the Server + PROVISION job. Returns the new server id. Does NOT
 * redirect. Callers must ensure funds exist (or pass free) — this still
 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
 *
 * `sold` overrides the recomputed price with the one the order was actually SOLD
 * at — the card-paid path passes the figure stamped on the Checkout session
 * BEFORE the card was charged, so the confirm redirect settles the price the
 * customer consented to instead of re-pricing against whatever promo is running
 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
 * quote, which it computed moments ago in the same request. See OrderPrice.
 */
/**
 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
 * any failure so nothing partial survives. Kept separate from the order tx so a
 * wallet order can surface the failure before any money moves, and a card order
 * (already paid) can swallow it without stranding the paid provision.
 *
 * Guards, all enforced here: first-time-only (no prior paid server), the
 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
 * (the two @@unique constraints on CouponRedemption).
 */
async function claimOrderCoupon(opts: {
  couponId: string;
  maxRedemptions: number | null;
  firstTimeOnly: boolean;
  userId: string;
  ipHash: string | null;
  amountCents: number;
}): Promise<void> {
  await db.$transaction(async (tx) => {
    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
    // not stand between them and this coupon on a fresh (wallet) order — and its global
    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
    if (opts.firstTimeOnly) {
      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
    }
    // Atomic conditional increment — the only thing between the last free slot and
    // an over-redemption when two orders race for it.
    const claim = await tx.coupon.updateMany({
      where:

      where:
        opts.maxRedemptions === null
          ? { id: opts.couponId, active: true }
          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
      data: { timesRedeemed: { increment: 1 } },
    });
    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
    try {
      await tx.couponRedemption.create({
        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
      });
    } catch {
      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
      // this person. Throwing rolls back the increment above with it.
      throw new OrderError("You’ve already used this code.");
    }
  });
}

/**
 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
 *
 * The card leg discounts `cardCents` up front and only settles the redemption
 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
 * paid provision is never stranded. Without this pre-check, a customer who has
 * already used a one-per-person code (or isn't first-time) still gets the
 * discounted card charge and the swallow hides it. So before we send them to
 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
 * plain reads; if any fails the caller re-quotes at full price. This is advisory
 * (a race could still lose the atomic claim at settle time — that path stays
 * swallowed by design), but it closes the everyday bypass.
 */
export async function orderCouponClaimable(opts: {
  couponId: string;
  firstTimeOnly: boolean;
  maxRedemptions: number | null;
  userId: string;
  ipHash: string | null;
}): Promise<{ ok: true } | { ok: false; error: string }> {
  if (opts.firstTimeOnly) {
    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
  }
  const byUser = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
  });
  if (byUser) return { ok: false, error: "You’ve already used this code." };
  if (opts.ipHash) {
    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
  }
  if (opts.maxRedemptions !== null) {
    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
  }
  return { ok: true };
}

export async function placeOrder(
  user: User,
  intent: OrderIntent,
  sold?: OrderPrice | null,
  opts?: {
    ipHash?: string | null;
    campaign?: string;
    promoReservationToken?: string | null;
    couponReservationToken?: string | null;
  },
): Promise<string> {
  const quote = await orderQuote(intent);
  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
  // Everything below bills off THESE three, never off `quote.chargeCents` /
  // `promo` directly: when a sold price is present it is the whole truth about
  // what this order costs and what rate it was sold at.
  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
  const promoName = sold?.promoName || promo.name;

  // Managed first-month-free — how this order settles the credit depends on the path:
  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
  //     the double-claim race. No token => this order was sold at FULL price, so there
  //     is nothing to grant. We deliberately do NOT infer the credit from
  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
  //     order), which would record a redemption for a purchase that never got one.
  const walletPromoApplied = !sold && promoCreditCents > 0;
  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
  // Note the intro discount on the billing document (first term only; renews full) —
  // ONLY when this specific order actually earned the credit (real customer report:
  // a full-price $8.88 VPS invoice read "First month free · 100% off first term",
  // because `promo.discountPercent` is a raw, ALWAYS-100 constant — see the comment
  // above — and this used to gate on that instead of on whether the credit was
  // actually granted to THIS order, same signal walletPromoApplied/cardPromoToken
  // already use to decide whether to grant it).
  const promoNote = walletPromoApplied || cardPromoToken ? ` · ${promoName} ${promoPercent}% off first term` : "";
  // The checkout coupon settles the same two ways:
  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
  //     throws and surfaces before any money moves if the last slot just went.
  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
  //     inside the charge tx (never a fresh contended claim — that would double-count the
  //     global cap and collide on the per-person unique). No token => full-price order.
  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;

  const cap = await capacityCheck(plan.id);
  if (!cap.ok) throw new OrderError(cap.reason);

  let nodeId: string | null = null;
  if (intent.nodeId) {
    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
    if (!n) throw new OrderError("Selected location is not available.");
    nodeId = n.id;
  } else {
    const n = await scheduleNode(plan.ramMB);
    nodeId = n?.id ?? null;
  }

  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
  if (!diskCap.ok) throw new OrderError(diskCap.reason);

  const addons = {
    malwareScanner: !!intent.addonMalware,
    dailyBackup: !!intent.addonBackup,
    docker: !!intent.addonDocker,
  };
  const isAdmin = user.role === "ADMIN";
  const freeRequested = !!intent.free && isAdmin;

  // VAT/GST to add to this order (Finding 1). CARD path: settle exactly the tax the
  // card leg was split from, carried on `sold` (never re-quoted after the card
  // cleared). WALLET path: resolve from the owner's billing country now. The RATE is
  // resolved here; the tax cents are recomputed from it inside the charge tx against
  // the amount actually debited, so a promo-lost full-price recompute is taxed on the
  // real net rather than the discounted one. A free admin grant is never taxed.
  let taxRatePercent = 0;
  let taxCountry = "";
  if (!freeRequested) {
    if (sold) {
      taxRatePercent = sold.taxRatePercent ?? 0;
      taxCountry = sold.taxCountry ?? "";
    } else {
      const ctx = await taxContextForUser(user);
      taxRatePercent = ctx.ratePercent;
      taxCountry = ctx.country;
    }
  }
  const orderTaxCents = Math.round((chargeCents * taxRatePercent) / 100);

  if (!freeRequested && user.balanceCents < chargeCents + orderTaxCents) throw new OrderError("Insufficient balance.");

  // Hard monthly spend cap (Finding 3): refuse a new paid order that would push this
  // account past its own cap. No-op unless the customer enabled one. Surfaced as an
  // OrderError so the deploy action shows the message verbatim.
  if (!freeRequested) {
    try {
      await assertSpendCap(user, chargeCents + orderTaxCents);
    } catch (e) {
      if (e instanceof SpendCapError) throw new OrderError(e.message);
      throw e;
    }
  }

  // WALLET path ONLY: claim the coupon atomically BEFORE the order tx, so a wallet order
  // fails cleanly (no money moved) if the last slot just went. A free admin grant never
  // consumes a customer coupon. The CARD path does NOT claim here — it reserved the coupon
  // before checkout and CONFIRMS that hold inside the charge tx below (`cardCouponToken`),
  // which is what closes the concurrent-checkout bypass the read-then-swallow left open.
  if (!freeRequested && !sold && quote.couponId && quote.couponDiscountCents > 0) {
    await claimOrderCoupon({
      couponId: quote.couponId,
      maxRedemptions: quote.couponMaxRedemptions,
      firstTimeOnly: quote.couponFirstTimeOnly,
      userId: user.id,
      ipHash: opts?.ipHash ?? null,
      amountCents: quote.couponDiscountCents,
    });
  }

  const newKey = (intent.sshPublicKey ?? "").trim();
  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);

  let server;
  // Captured from the in-tx invoice.create so the paid ORDER invoice can be emailed
  // (with its PDF) AFTER the transaction commits — a rolled-back order leaves this
  // null and emails nothing. Only paid orders create an invoice (free admin grants
  // skip the `if (!freeRequested)` block below), so this stays null for those.
  let orderInvoice: { id: string; number: number; amountCents: number; description: string } | null = null;
  try {
    server = await db.$transaction(async (tx) => {
      // ATOMIC first-month-free claim, INSIDE the charge tx (mirrors claimOrderCoupon).
      // Contend for the redemption BEFORE debiting so the debit amount matches the
      // outcome. A lost claim never throws — on the wallet path we add the credit
      // back and charge FULL; on the card path the money already settled at the sold
      // price (screened by the pre-checkout guard in actions.ts), so we keep it and
      // record nothing — the same swallow discipline the coupon path uses.
      let debitCents = chargeCents;
      let promoNoteFinal = promoNote;
      let promoClaimId: string | null = null;
      let soldFull = false; // wallet order that lost the claim and paid full price
      if (!freeRequested && cardPromoToken) {
        // CARD/Stripe path: confirm the hold reserved before the card was charged.
        // The card already settled at the sold (discounted) price; confirming just
        // flips the hold to CONSUMED and anchors it. NEVER a second debit here.
        const confirmed = await confirmReservation(tx, cardPromoToken);
        if (confirmed) {
          promoClaimId = confirmed.id;
        } else {
          // The hold is gone (released/swept) but the card already paid the discounted
          // leg. This is unreachable while the hold outlives the payable session, but
          // if it ever happens we must NOT charge more than the customer was shown.
          // Try to record the grant so a later renewal can convert it; if even that
          // loses (the slot is now another order's), keep the discounted charge and
          // log — the same swallow discipline the paid-coupon path uses.
          const fallback = await claimFirstMonthFree(tx, {
            userId: user.id,
            ipHash: opts?.ipHash ?? null,
            serviceType: "VPS",
            campaign: opts?.campaign ?? "",
            chargedCents: chargeCents,
          });
          if (fallback.claimed) promoClaimId = fallback.id;
          else console.error(`[order] first-month-free hold ${cardPromoToken} vanished before confirm for ${user.id}; kept sold price`);
        }
      } else if (!freeRequested && walletPromoApplied) {
        // WALLET path: atomic INSERT inside the charge tx. A lost claim means this
        // account/IP already redeemed — add the credit back and charge FULL price.
        const claim = await claimFirstMonthFree(tx, {
          userId: user.id,
          ipHash: opts?.ipHash ?? null,
          serviceType: "VPS",
          campaign: opts?.campaign ?? "",
          chargedCents: chargeCents,
        });
        if (claim.claimed) {
          promoClaimId = claim.id;
        } else {
          debitCents = chargeCents + promoCreditCents; // full price
          promoNoteFinal = "";
          soldFull = true;
        }
      }
      // CARD/Stripe path: confirm the coupon hold reserved before the card was charged
      // (RESERVED→CONSUMED), inside this tx so the discount's slot commits with the
      // provision. NEVER a fresh claim — that would re-increment the cap and collide on
      // the per-person unique. `sold` already carries the discounted total the customer
      // paid, so no debit changes here.
      if (!freeRequested && cardCouponToken) {
        const confirmed = await confirmOrderCouponReservation(tx, cardCouponToken);
        if (!confirmed) {
          // The hold is gone (released/swept) but the card already settled the discounted
          // leg. Unreachable while the hold outlives the payable session (its reservedUntil
          // is pinned past the Checkout expiry); if it ever happens we keep the discounted
          // charge (never overcharge past what was shown) and log — the same swallow
          // discipline the paid path uses. We do NOT mint a replacement claim (its cap
          // increment could over-redeem).
          console.error(`[order] coupon hold ${cardCouponToken} vanished before confirm for paid order ${user.id}; kept sold price`);
        }
      }
      // The rate this term was actually sold at: 0% off when a wallet order lost the
      // claim and paid full, otherwise the promo/sold percent (100 admin grant).
      const effectivePromoPercent = freeRequested ? 100 : soldFull ? 0 : promoPercent;
      if (!freeRequested) {
        // For a multi-month term (Annual etc.), spell out the effective monthly-
        // equivalent of the PLAN portion on the billing document, derived from the
        // very `regularPlanCents` that was charged (its term discount already baked
        // in) — never a second computation. So an annual line reads "Annual
        // ($8.09/mo)" and the customer can see the yearly commitment AND its real
        // per-month rate. Omitted for the 1-month term, where it would just repeat
        // the monthly price.
        const effMonthlyCents = term.months > 1 ? Math.round(quote.regularPlanCents / term.months) : 0;
        const termLabel =
          term.months > 1 ? `${term.label} ($${(effMonthlyCents / 100).toFixed(2)}/mo)` : term.label;
        // VAT/GST on the NET actually being debited (recomputed from the rate so the
        // promo-lost full-price recompute above is taxed correctly). The wallet debit
        // and the invoice total are both net + tax; the line items sum to the net.
        const orderTaxFinal = Math.round((debitCents * taxRatePercent) / 100);
        const grossDebit = debitCents + orderTaxFinal;
        await debitWallet(tx, user.id, grossDebit);
        await tx.walletTransaction.create({
          data: {
            userId: user.id,
            amountCents: -grossDebit,
            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`,
          },
        });
        // Billing document for the charge — created inside the same debit tx so it
        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
        // Extra disk gets its OWN line so the customer can see exactly what the
        // permanent storage costs; the lines always sum back to debitCents.
        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`;
        // Both add-ons get their OWN line; the base plan line is the remainder, so
        // the lines always sum back to debitCents.
        const planLineCents = debitCents - extraDiskCents - backupCents;
        const createdInvoice = await tx.invoice.create({
          data: invoiceCreateData({
            userId: user.id,
            description: lineDesc,
            status: "PAID",
            taxCents: orderTaxFinal,
            taxRatePercent,
            taxCountry,
            period: { start: new Date(), end: addMonths(new Date(), term.months) },
            lineItems: [
              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
              ...(extraDiskCents > 0
                ? [
                    {
                      description:
                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
                      qty: 1,
                      unitCents: extraDiskCents,
                      amountCents: extraDiskCents,
                    },
                  ]
                : []),
              ...(backupCents > 0
                ? [
                    {
                      description:
                        `${backupTierSpec(backupTier).label} backups (keep ${backupTierSpec(backupTier).keep}) — ${term.label} ` +
                        `($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
                      qty: 1,
                      unitCents: backupCents,
                      amountCents: backupCents,
                    },
                  ]
                : []),
            ],
          }),
        });
        orderInvoice = {
          id: createdInvoice.id,
          number: createdInvoice.number,
          amountCents: createdInvoice.amountCents,
          description: lineDesc,
        };
      }
      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
      }
      const s = await tx.server.create({
        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
        // (regenerated at deploy — identical at runtime then; see lib/promo-redemption.ts).
        data: {
          name: intent.hostname,
          hostname: intent.hostname,
          userId: user.id,
          planId: plan.id,
          osTemplateId: os.id,
          partnerSource: intent.partnerSource ?? null,
          nodeId,
          addons,
          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
          // storage for easy restore") and re-confirms it on the Review step, but
          // `addons.dailyBackup` was write-only: the worker declares the key and
          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
          // the Backups tab. Nothing bridged the two, so EVERY server in the live
          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
          // job was ever enqueued. A customer would discover the safety net they
          // were promised did not exist at the moment they needed it. Bridge it
          // here, at the point of sale. A PAID backup tier (PLUS) implies backups
          // are on regardless of the free "Daily auto-backups" toggle — you cannot
          // sell retention on a schedule that never runs. `backupTier`/`backupKeep`
          // are the columns the retention lever (worker/index.ts backupCreate)
          // reads; keep null on FREE so it falls back to the tier default.
          autoBackup: !!intent.addonBackup || backupTier !== "FREE",
          backupIntervalHours:
            !!intent.addonBackup || backupTier !== "FREE" ? backupTierSpec(backupTier).intervalHours : null,
          backupTier,
          backupKeep: backupTier === "FREE" ? null : backupTierSpec(backupTier).keep,
          termMonths: term.months,
          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
          // later proration prices the plan delta against this number instead of
          // whatever promo happens to be running when the customer clicks resize
          // (lib/proration.ts) — otherwise the customer chooses the rate for each
          // half of a round trip by choosing the date, and pockets the spread.
          // `chargeCents` above is literally promoPriceCents(regular, promo), so
          // this scalar and the cash collected describe the same transaction.
          // A free admin grant recorded as 100: nothing was paid for these months,
          // so nothing may ever prorate out of them.
          //
          // `effectivePromoPercent` — not `promo.discountPercent` — because a
          // card-paid order settles the rate it was SOLD at (see OrderPrice), which
          // may no longer be the promo running now, AND because a wallet order that
          // lost the first-month-free claim paid FULL price (0% off): recording 100
          // there would let a later downgrade prorate out a discount nobody was
          // charged. Recording today's rate against a price collected under a
          // different one is exactly the drift this column exists to prevent.
          termPromoPercent: effectivePromoPercent,
          // The ANNUAL discount rate in force when this term was sold, frozen here so
          // every later proration prices against it and an up-then-down round trip nets
          // to zero even if the admin retunes `annual_discount_percent` in between
          // (Finding 2). Ignored for non-annual terms by `termDiscountPct`; a free admin
          // grant never prorates, so its value is inert. `quote.annualPct` is the very
          // rate `regularPlanCents`/`chargeCents` above were priced at.
          annualDiscountPct: quote.annualPct,
          // The plan-portion cash actually collected for this term, net of promo AND
          // coupon AND the intro discount, EXCLUDING recurring add-ons — the
          // authoritative refund basis (see Server.refundableTermCents).
          // `regularPlanCents` is the full term list; subtract the promo credit ONLY if
          // the claim held (a lost wallet claim paid full, `soldFull`), always subtract
          // the coupon, and always subtract the intro discount (both reduced cash but
          // not `termPromoPercent`; the intro discount is baked into `chargeCents`).
          // Clamped ≥ 0. A free admin grant collected nothing, so 0.
          refundableTermCents: freeRequested
            ? 0
            : Math.max(
                0,
                quote.regularPlanCents -
                  (soldFull ? 0 : promoCreditCents) -
                  quote.couponDiscountCents -
                  quote.introDiscountCents,
              ),
          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
          // born at its full size, with no separate expansion job.
          extraDiskGB,
          wantsDedicatedIp: !!intent.dedicatedIp,
          isFree: freeRequested,
          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
        } as Prisma.ServerUncheckedCreateInput,
      });
      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
      // Anchor the redemption to the created server so the renewal worker can flip
      // `renewed` when this customer bills their second term, and stamp the true
      // first-term charge. Same tx, so it commits (or rolls back) with the order.
      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
      return s;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.order",
      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
    },
  });
  if (!freeRequested) {
    try {
      await maybeRewardReferral(user.id);
    } catch {
      /* non-fatal */
    }
    // Soft monthly-budget alert (Finding 3): fire once when this charge tips spend
    // over the customer's budget. Best-effort — never fails an order.
    await maybeAlertBudget(user.id);
    // KOL/Agency partner commission: if this customer is attached to a partner,
    // accrue commission on the PAID order invoice now (idempotent; the background
    // sweep would otherwise catch it within minutes). Best-effort by design.
    await accrueRecentCommissionsForCustomer(user.id);
  }
  // Deploy-funnel COMPLETION — the authoritative, server-side bottom of the funnel.
  // This is the ONE place a VPS order is definitively created & paid: both the wallet
  // path (lib/actions.ts payAndDeploy) and the card path (lib/fulfil-checkout.ts, run
  // by the Stripe webhook or the success redirect) reach it, so recording here counts
  // every completed VPS deploy exactly once, with a reliable `userId`. The step index
  // orders it at the tail (after Review/Payment); the completion is a terminal event,
  // not a wizard step, so it drives the completed counts rather than rendering a row.
  // Best-effort AND double-guarded: `recordDeployFunnelComplete` already swallows every
  // failure, and the extra catch guarantees analytics can never disturb the money path.
  try {
    await recordDeployFunnelComplete({ product: "vps", step: "Complete", stepIndex: 8, userId: user.id });
  } catch {
    /* never let funnel bookkeeping affect a completed order */
  }
  // Email the paid ORDER invoice with its PDF attached. Best-effort AND post-commit:
  // the money has already moved, so a mail failure must NEVER surface as an order
  // failure. Fires exactly once per order (single commit) and covers BOTH the wallet
  // path (lib/actions.ts) and the card path (lib/fulfil-checkout.ts) because both go
  // through this one placeOrder. This is the invoice DOCUMENT — deliberately
  // `invoiceNew` (subject "Invoice #… — $… due"), not `receipt`, so it does not
  // collide with the separate "Payment received" wallet/card top-up receipt a card
  // order already gets from lib/stripe.ts. Passing `invoiceId` + the `invoice_new`
  // template makes lib/mailer.ts auto-attach the rendered PDF. `orderInvoice` is null
  // for free admin grants (no invoice created), so those email nothing.
  // Read via the declared union — the value is assigned inside the $transaction
  // callback, which TS control-flow analysis does not track, so a direct read would
  // narrow to `null`.
  const invForEmail = orderInvoice as { id: string; number: number; amountCents: number; description: string } | null;
  if (invForEmail) {
    try {
      const { sendMail, emails } = await import("./mailer");
      const branding = await invoiceBranding();
      const tpl = emails.invoiceNew(
        {
          invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
          amount: `$${(invForEmail.amountCents / 100).toFixed(2)}`,
          dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
          description: invForEmail.description,
        },
        true, // the itemised PDF is attached (invoiceId passed below)
      );
      await sendMail({
        to: user.email,
        subject: tpl.subject,
        html: tpl.html,
        template: tpl.template,
        invoiceId: invForEmail.id,
        userId: user.id,
        kind: "invoice",
      });
    } catch {
      /* invoice email is best-effort — a placed order must never fail on mail */
    }
  }
  return server.id;
}

