"use client";

import { useEffect, useRef, useState } from "react";
import { placeHostingOrder, startHostingCardSetup, checkHostingSubdomain } from "@/lib/actions-hosting";
import { finalizeCardSetup } from "@/lib/actions-payment-method";
import { termPriceCents, termDiscountPct, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT, PRODUCT_TERMS, vpsTerm } from "@/lib/billing-terms";
import { extraDiskCentsAt, EXTRA_DISK_STEP_GB, EXTRA_DISK_MAX_ADD_GB, EXTRA_DISK_ONE_WAY_NOTE, EXTRA_DISK_DEFAULT_PER_GB_CENTS } from "@/lib/extra-disk";
import { TermLadder } from "@/components/customer/TermLadder";
import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
import { PaymentStep } from "@/components/customer/PaymentStep";
import { WizardReassuranceCard } from "@/components/customer/WizardReassuranceCard";
import { WizardStickyCart } from "@/components/customer/WizardStickyCart";
import { walletSplit } from "@/lib/wallet-split";
import { recommendHostingPlan } from "@/lib/hosting/recommend";
import { useCurrency } from "@/components/currency/CurrencyContext";
import { convertAndFormat, DEFAULT_CURRENCY } from "@/lib/currency";
import { trackDeployStep, trackDeployError } from "@/lib/deploy-funnel-client";

/* --------------------------------------------------------------- types --- */

export type WizardPlan = {
  id: string;
  name: string;
  priceCents: number;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  mailboxes: number;
  freeMigration: boolean;
  featured: boolean;
  tagline: string;
};

type AppOpt = { slug: string; name: string; needsDb: boolean; blurb?: string; logoPath?: string; logoHex?: string };

// USD formatter — this wizard's 2-decimal style ("$5.00"). Used verbatim for the
// USD display path (byte-for-byte unchanged) and for the "billed in USD" note.
const usd = (c: number) => `$${(c / 100).toFixed(2)}`;

/** sessionStorage key for the in-progress order — survives the Stripe card round-trip. */
const DRAFT_KEY = "nxeon.hosting.deploy.draft.v1";
type Draft = {
  step: number;
  planId: string;
  termMonths: number;
  domainMode: "temp" | "own";
  domain: string;
  /** The chosen free-subdomain label — MUST persist across the card-setup round-trip,
   *  else a customer who typed "testing" gets the auto-derived name after adding a card. */
  subLabel: string;
  extraDiskGB: number;
  appSlug: string;
};

/**
 * The one-month first-month-free credit, computed EXACTLY like the server's
 * `firstMonthCreditCents` (kept inline so this client file never imports the
 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
 * single month. The server recomputes the real debit with the same formula, so
 * displayed === charged.
 */
function firstMonthCredit(fullCents: number, months: number): number {
  if (months <= 1) return fullCents;
  return Math.min(fullCents, Math.round(fullCents / months));
}

function Stepper({ step, steps }: { step: number; steps: string[] }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {steps.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
              i === step
                ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step
                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

/* -------------------------------------------------------------- wizard --- */

export function HostingDeployWizard({
  plans,
  apps,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
  firstMonthFree = false,
  balanceCents,
  hasCard,
  cardLabel,
  stripeReady,
  tempSubdomainBase,
  extraDiskPerGbCents = EXTRA_DISK_DEFAULT_PER_GB_CENTS,
  email,
}: {
  plans: WizardPlan[];
  apps: AppOpt[];
  annualDiscountPct?: number;
  firstMonthFree?: boolean;
  balanceCents: number;
  /** A renewal-capable card is already on file (charged off-session at renewal). */
  hasCard: boolean;
  cardLabel: string | null;
  /** Stripe is configured, so we can capture a card at all. */
  stripeReady: boolean;
  /** Base zone for the free temporary subdomain, e.g. "nxeon.cloud". */
  tempSubdomainBase: string;
  /** Price per extra GB / month (cents) — the same add-on rate VPS uses. */
  extraDiskPerGbCents?: number;
  /** The account's email — PaymentStep's receipt/invoice-email display. */
  email: string;
}) {
  // Steps: Install is only shown when there's an app catalog to pick from.
  const hasApps = apps.length > 0;
  const steps = ["Plan", "Domain", ...(hasApps ? ["Install"] : []), "Add-ons", "Review"];
  const [step, setStep] = useState(0);

  // Deploy-funnel: record reaching each wizard step (de-duped per session).
  useEffect(() => {
    trackDeployStep("hosting", steps[step] ?? String(step), step);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step]);

  // DISPLAY-ONLY price formatter. USD renders byte-for-byte as before; any other
  // selected display currency converts the USD-cents amount for on-screen reference
  // only. Everything sent to placeHostingOrder (and the nxTrack value) stays USD.
  const { currency, rate } = useCurrency();
  const money = (c: number) =>
    currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);

  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
  const [domainMode, setDomainMode] = useState<"temp" | "own">("temp");
  const [domain, setDomain] = useState("");
  // Optional customer-chosen free-subdomain label. Empty => the server auto-derives
  // `<username>.<base>`. When the customer types one we live-check availability so a
  // taken/invalid label is caught before the order (the order re-checks atomically).
  const [subLabel, setSubLabel] = useState("");
  const [subCheck, setSubCheck] = useState<{ status: "idle" | "checking" | "ok" | "bad"; reason?: string }>({ status: "idle" });
  const [extraDiskGB, setExtraDiskGB] = useState(0);
  const [appSlug, setAppSlug] = useState("");

  // A card the customer just saved via the Stripe round-trip flips this true
  // without a page reload, so the Review step stops asking for one.
  const [savedCard, setSavedCard] = useState(hasCard);
  // "Apply my balance" — mirrors the VPS wizard. Default ON when there's a balance to
  // apply; turning it off routes the whole amount due today to a card. The server
  // recomputes the identical split (lib/wallet-split.ts), so displayed === charged.
  const [useWallet, setUseWallet] = useState(balanceCents > 0);
  // Clicking "Change" next to the billing term inside PaymentStep's Order
  // Summary used to jump all the way back to step 0 (Plan) — worse than just
  // "back one step" when Domain/Install/Add-ons sit in between. Reveals the
  // same TermLadder cards inline instead, mirroring DeployWizard's
  // showTermPicker pattern.
  const [showTermPicker, setShowTermPicker] = useState(false);

  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [cardBusy, setCardBusy] = useState(false);
  const [cardNote, setCardNote] = useState("");
  // `addCard`'s setup-mode session (capture a renewal card, no charge) — this is a
  // genuinely different Stripe primitive from a Custom Checkout payment session
  // (mode:setup vs mode:payment, still on the OLD embedded_page ui_mode), so it
  // keeps using the popup StripeCheckoutModal rather than PaymentStep, which is
  // built around confirming a real payable Custom Checkout session.
  const [cardSetupCheckout, setCardSetupCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  // `place()`'s Custom Checkout session (paying the card leg of an order) — feeds
  // the embedded PaymentStep, mirroring VPS/Game/Email.
  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
  const [restoredAfterSetup, setRestoredAfterSetup] = useState(false);

  // ONE idempotency token per wizard mount. A double-click is stopped by `busy`;
  // this token is the server-side guard against a network retry creating a second
  // account (placeHostingOrder → FulfilledSession UNIQUE). A user-driven retry
  // after a failure reuses it safely (the server clears a FAILED marker).
  const idemRef = useRef<string>("");
  if (!idemRef.current) idemRef.current = makeToken();

  const plan = plans.find((p) => p.id === planId) ?? null;
  const curLabel = steps[step];
  const isLast = step === steps.length - 1;

  /* ----- pricing (all DB-fed; the server recomputes the debit identically) -- */
  const planTermCents = plan ? termPriceCents(plan.priceCents, termMonths, annualDiscountPct) : 0;
  // Extra storage add-on: priced per GB/mo over the term, and NEVER discounted by the
  // first-month-free promo (mirrors the server — the credit applies to the plan only).
  const extraTermCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGbCents) * termMonths;
  const fullTermCents = planTermCents + extraTermCents;
  const creditCents = firstMonthFree ? firstMonthCredit(planTermCents, termMonths) : 0;
  const dueTodayCents = Math.max(0, planTermCents - creditCents) + extraTermCents;
  // What the account renews at — the full term price (plan + storage), promo aside.
  const renewalCents = fullTermCents;
  const perMonthCents = Math.round(planTermCents / Math.max(1, termMonths));
  const termWord = termMonths === ANNUAL_TERM_MONTHS ? "year" : termMonths === 1 ? "month" : `${termMonths} mo`;
  // Same rate planTermCents was computed with — shown next to the billing
  // term as a "Save X%" badge (DeployWizard's termDiscountPct pattern).
  const discountPercent = termDiscountPct(termMonths, annualDiscountPct);
  // The sticky cart's price: the FULL per-month total including add-ons
  // (extra storage), not just the bare plan rate — a real regression already
  // happened once this session (a sticky cart that didn't reflect add-ons),
  // so this is computed from fullTermCents (plan + extra disk), never from
  // plan.priceCents alone.
  const stickyCartMonthlyCents = Math.round(fullTermCents / Math.max(1, termMonths));

  // Wallet/card split for the amount due today — identical math to the server
  // (placeHostingOrder → walletSplit), so what's shown here === what's charged.
  const split = walletSplit({ dueCents: dueTodayCents, balanceCents, useWallet });
  const cardCents = split.cardCents;
  const walletApplied = split.walletApplied;

  // Can we bill the renewal? A saved card OR a wallet already holding a renewal's
  // worth OR a card leg on THIS order (the card is saved for renewals via
  // setup_future_usage). Mirrors the server: a card-funded order needs no separate
  // renewal method.
  const renewalMethodOk = savedCard || balanceCents >= renewalCents || cardCents > 0;
  // A card leg is due at Review — PaymentStep mounts instead of the plain
  // fallback, same condition VPS/Game/Email use.
  const showPaymentStep = isLast && cardCents > 0;

  // A Custom Checkout session is priced at the moment it's created. If the
  // customer flips "Apply my balance" AFTER one exists, its stamped amount is
  // stale — drop it so PaymentStep asks for a fresh one. Same guard as the
  // other wizards.
  const prevCardCentsRef = useRef(cardCents);
  useEffect(() => {
    if (checkoutSession && prevCardCentsRef.current !== cardCents) {
      setCheckoutSession(null);
      setStripePhase("idle");
    }
    prevCardCentsRef.current = cardCents;
  }, [cardCents, checkoutSession]);

  /* ----- Stripe card round-trip (draft save + restore) ---------------------- */
  useEffect(() => {
    let sid = "";
    try {
      sid = new URLSearchParams(window.location.search).get("card_setup") ?? "";
    } catch {
      /* no URL access */
    }
    if (!sid) return;
    // Pull our draft back so the customer lands where they left off.
    let d: Draft | null = null;
    try {
      const raw = sessionStorage.getItem(DRAFT_KEY);
      sessionStorage.removeItem(DRAFT_KEY);
      if (raw) d = JSON.parse(raw) as Draft;
    } catch {
      d = null;
    }
    if (d) {
      if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
      if (PRODUCT_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
      if (d.domainMode === "temp" || d.domainMode === "own") setDomainMode(d.domainMode);
      if (typeof d.domain === "string") setDomain(d.domain);
      if (typeof d.subLabel === "string") setSubLabel(d.subLabel);
      if (Number.isFinite(d.extraDiskGB)) setExtraDiskGB(Math.max(0, Math.min(EXTRA_DISK_MAX_ADD_GB, Math.round(d.extraDiskGB))));
      if (apps.some((a) => a.slug === d.appSlug)) setAppSlug(d.appSlug);
    }
    setRestoredAfterSetup(true);
    setStep(steps.length - 1); // land on Review
    if (sid === "canceled") {
      setCardNote("Card setup was cancelled — you weren’t charged. Add a card to enable renewals, or use your wallet.");
      return;
    }
    // Finalise the saved card, then reflect it on the Review step.
    (async () => {
      const res = await finalizeCardSetup(sid);
      if (res.ok) {
        setSavedCard(true);
        setCardNote(`Card saved${res.label ? ` — ${res.label}` : ""}. Your renewals will bill to it.`);
        // Fire-and-forget "card" conversion (→ Meta AddPaymentInfo + the Google Ads
        // card label). Best-effort: a no-op until consent + the pixel load.
        try {
          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("card", {});
        } catch {
          /* ignore */
        }
      } else {
        setCardNote(res.error ?? "We couldn’t save that card. Try again or use your wallet.");
      }
    })();
    // Mount-only restore.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function saveDraft() {
    try {
      const d: Draft = { step, planId, termMonths, domainMode, domain, subLabel, extraDiskGB, appSlug };
      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(d));
    } catch {
      /* storage disabled — the card flow still works, it just won't restore */
    }
  }

  async function addCard() {
    setCardBusy(true);
    setCardNote("");
    saveDraft();
    try {
      const res = await startHostingCardSetup();
      if (res.clientSecret && res.publishableKey) {
        // Open the embedded card modal on THIS page — no redirect to Stripe.
        setCardSetupCheckout({ clientSecret: res.clientSecret, publishableKey: res.publishableKey });
        return;
      }
      setCardNote(res.error ?? "We couldn’t start card setup just now. Please try again.");
    } catch {
      setCardNote("We couldn’t start card setup just now. Please try again.");
    } finally {
      setCardBusy(false);
    }
  }

  /* ----- domain validity (client-side friendliness; server re-validates) ---- */
  const domainTrim = domain.trim().toLowerCase();
  const domainLooksValid = /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(domainTrim);
  const domainBlocker =
    domainMode === "own" && !domainLooksValid
      ? domainTrim.length === 0
        ? "Enter the domain you want to host, or switch to a free temporary subdomain."
        : "Enter a valid domain (e.g. example.com)."
      : null;

  // Live availability check for a chosen free subdomain (debounced). An empty label
  // is allowed — the server auto-derives `<username>.<base>` — so only a typed label
  // that isn't confirmed available blocks the flow.
  const subLabelTrim = subLabel.trim().toLowerCase();
  useEffect(() => {
    if (domainMode !== "temp") {
      setSubCheck({ status: "idle" });
      return;
    }
    const label = subLabel.trim().toLowerCase();
    if (!label) {
      setSubCheck({ status: "idle" });
      return;
    }
    setSubCheck({ status: "checking" });
    let cancelled = false;
    const t = setTimeout(async () => {
      try {
        const r = await checkHostingSubdomain(label);
        if (!cancelled) setSubCheck(r.available ? { status: "ok" } : { status: "bad", reason: r.reason });
      } catch {
        if (!cancelled) setSubCheck({ status: "bad", reason: "Couldn’t check right now — try again." });
      }
    }, 400);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [subLabel, domainMode]);

  const subdomainBlocker =
    domainMode === "temp" && subLabelTrim.length > 0 && subCheck.status !== "ok"
      ? subCheck.status === "checking"
        ? "Checking availability…"
        : subCheck.reason ?? "Pick an available subdomain."
      : null;

  const canContinue = curLabel === "Domain" ? !domainBlocker && !subdomainBlocker : true;
  const canPlace = !!planId && !busy && !domainBlocker && !subdomainBlocker;

  async function place() {
    if (!plan) return;
    setBusy(true);
    setError("");
    setStripePhase("loading");
    // Deploy-funnel: the customer submitted the final Review, so an order (a wallet
    // charge, or the renewal-method gate) is about to be attempted — record REACHED-
    // PAYMENT as a step at the tail (after Review). De-duped per session; completion
    // is now recorded server-side in placeHostingOrder (userId-keyed), so this wizard
    // no longer fires trackDeployComplete.
    trackDeployStep("hosting", "Payment", steps.length);
    try {
      const res = await placeHostingOrder({
        planId,
        domain: domainMode === "own" ? domainTrim : undefined,
        subdomainLabel: domainMode === "temp" && subLabelTrim ? subLabelTrim : undefined,
        extraDiskGB: extraDiskGB || undefined,
        termMonths,
        appSlug: appSlug || undefined,
        idempotencyKey: idemRef.current,
        useWallet,
      });
      // A card leg is due — mount the embedded Stripe checkout. On success Stripe
      // navigates the top window to the confirm route, which credits the card to the

    // navigates the top window to the confirm route, which credits the card to the
    // wallet, places the account (debiting it) and lands the customer on it.
    if ("checkout" in res) {
      setCheckoutSession({ clientSecret: res.checkout.clientSecret, publishableKey: res.checkout.publishableKey });
      setStripePhase("idle");
      return;
    }
    if ("needCard" in res) {
      setCardNote("Add a renewal payment method to continue — a $0 first month still needs a way to bill month two.");
      setStep(steps.length - 1);
      return;
    }
    if ("error" in res) {
      setError(res.error || "Something went wrong. Your wallet was not charged — try again.");
      setStripePhase("error");
      trackDeployError("hosting", "Review", steps.length - 1, "ORDER_ERROR", res.error);
      return;
    }
    // Success — the deploy went through. Completion is recorded AUTHORITATIVELY on
    // the server (placeHostingOrder → recordDeployFunnelComplete), keyed by userId
    // like VPS and game, so it is counted once even if this browser never gets here
    // (and is not double-counted against the server event). No client complete beacon.
    try {
      sessionStorage.removeItem(DRAFT_KEY);
    } catch {
      /* ignore */
    }
    // Fire the "hosting" conversion for a completed hosting signup (→ Meta
    // Subscribe + the Google Ads hosting label). The first-month-free ad funnel
    // optimizes toward THIS event, not Purchase: the order is $0 today (free
    // month) and the real revenue is the renewal, so Purchase would be a $0/late
    // signal. `nxTrack` is the consent-gated global from ConversionTags — a no-op
    // until the visitor consents + the pixel loads.
    try {
      (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.(
        "hosting",
        // Value = the recurring term charge (what they renew at — first month is
        // free, so this is the real subscription value for ROAS, not $0-today).
        { value: renewalCents / 100, currency: "USD", eventId: idemRef.current },
      );
    } catch {
      /* ignore */
    }
    // `?purchase=1` — same marker reportPurchase stamps onto the card-paid path
    // (lib/fulfil-checkout.ts) and the VPS/game wallet-only redirects (lib/actions.ts)
    // — so <ProvisioningOverlay/> knows this landing IS a fresh order, even in
    // SANDBOX mode where the account can already be ACTIVE by the time this page
    // loads. Without it, a wallet-only hosting order showed no post-payment
    // interstitial at all (the bug this wizard's overlay wiring exists to fix).
    window.location.href = `/dashboard/hosting/${res.accountId}?purchase=1`;
    return;
  } catch {
    setError("Something went wrong. Your wallet was not charged — try again.");
    setStripePhase("error");
    trackDeployError("hosting", "Review", steps.length - 1, "EXCEPTION", "place() threw");
  } finally {
    setBusy(false);
  }
}

