// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
// success-redirect route and the webhook. Plain server module (not "use server").
//
// WHY THIS EXISTS (2026-07-25)
// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
// whether `creditCheckoutSession()` returned true. That boolean is true only for
// the caller that won the race to insert the wallet credit — and the webhook
// calls the same function and discards the result. So:
//
//   * Race: the webhook's insert lands first, the confirm request gets P2002,
//     `credited === false`, and the redirect quietly lands on an empty page.
//     $249 charged, $249 credited, no server, no error, no notification.
//   * Deterministic: the customer closes the tab before `success_url` resolves,
//     so the confirm route never runs at all. Same outcome, 100% reproducible.
//
// Stripe's own guidance is explicit that a browser redirect must not be the
// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
// its own marker, not a side effect of crediting — decides the single winner.

import type Stripe from "stripe";
import { db } from "./db";
import {
  classifyCheckoutSession,
  creditCheckoutSession,
  retrieveCheckoutSession,
  isPurchaseLegSession,
  packMetadata,
  STRIPE_METADATA_VALUE_MAX,
  type CheckoutPurpose,
} from "./stripe";
import { saveCardFromPaymentSession } from "./stripe-cards";
import { placeOrder } from "./order";
import { placeGameOrder } from "./game-order";
import { placeHostingCardOrder } from "./actions-hosting";
import { placeEmailCardOrder } from "./actions-email-hosting";
import { placeDomainCardOrder } from "./actions-domains";
import { applyResize } from "./resize";
import { applyDiskExpand } from "./disk-expand";
import { applyDedicatedIpPurchase } from "./dedicated-ip-purchase";
import { recordDeployFunnelError } from "./deploy-funnel";
import { sendMetaConversion } from "./tracking";
import { cookies, headers } from "next/headers";

/**
 * Which rail actually moved the money. Stripe is the only one with a real
 * Checkout Session (so `saveCardFromPaymentSession` and the Stripe-specific
 * ledger label only ever run for it); PayPal and Coinbase Commerce reach this
 * same dispatch through `fulfilExternalPayment` below with a SYNTHETIC
 * session-shaped object carrying the identical nxeon* metadata keys.
 */
export type PaymentProvider = "stripe" | "paypal" | "coinbase";

export type FulfilResult = {
  /** Where the browser should end up. The webhook ignores this. */
  redirect: string;
  /** True when THIS call performed the fulfilment work. */
  fulfilled: boolean;
  kind: "order" | "gameOrder" | "hostOrder" | "emailOrder" | "domainOrder" | "resize" | "diskExpand" | "dedicatedIp" | "topup" | "none";
  error?: string;
};

/**
 * Claim exclusive responsibility for fulfilling `sessionId`.
 * Returns false when another caller already holds the claim — the UNIQUE index,
 * not a read-then-write check, is what makes this safe under concurrency.
 */
async function claim(sessionId: string, kind: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
    throw e;
  }
}

async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
  await db.fulfilledSession
    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
    .catch(() => {});
}

/**
 * Tell the customer their money is safe and someone knows. Called only on a path
 * where the card HAS cleared and fulfilment did not happen, so silence is the one
 * outcome that is never acceptable.
 */
async function notifyStalled(userId: string) {
  await db.notification
    .create({
      data: {
        userId,
        title: "Payment received — we couldn't finish setting up your server",
        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
        href: "/dashboard/billing",
      },
    })
    .catch(() => {});
}

/**
 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
 * call (this only runs where `fulfilled === true`, so no double count under the
 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
 * READ-ONLY on money: it reports the amount, it never changes a charge.
 */
async function reportPurchase(
  redirect: string,
  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
  email?: string,
  userId?: string,
  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
  prod?: string,
): Promise<string> {
  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
  const currency = (session.currency ?? "usd").toUpperCase();
  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
  // Wrapped so the webhook path (no browser request scope) simply sends without them.
  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
  try {
    const [ck, h] = await Promise.all([cookies(), headers()]);
    fbc = ck.get("_fbc")?.value || undefined;
    fbp = ck.get("_fbp")?.value || undefined;
    userAgent = h.get("user-agent") ?? undefined;
    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
  } catch {
    /* no request scope (webhook) — send without cookie/UA signals */
  }
  const { eventId } = await sendMetaConversion({
    eventName: "Purchase",
    email,
    value,
    currency,
    sourceUrl: redirect,
    fbc,
    fbp,
    userAgent,
    clientIp,
    externalId: userId,
  });
  // SERVER-SIDE Google Ads offline conversion for the paid order, using the captured
  // gclid — reliable where the browser gtag is not. Best-effort + idempotent (deduped
  // on the Stripe session id). Fires the product-specific action (vps/hosting/game/…)
  // AND a generic "purchase". Inert until the Ads API creds are configured.
  if (userId) {
    try {
      const { recordAdsConversion } = await import("./google-ads");
      const valueCents = Math.round(value * 100);
      if (prod) await recordAdsConversion({ kind: prod, userId, dedupeKey: `${prod}:${session.id}`, valueCents, currency });
      await recordAdsConversion({ kind: "purchase", userId, dedupeKey: `purchase:${session.id}`, valueCents, currency });
    } catch {
      /* tracking is best-effort — the order is already fulfilled */
    }
  }
  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
}

/**
 * Credit the wallet and fulfil whatever the session was for, exactly once.
 * Safe to call repeatedly and concurrently from the redirect and the webhook.
 *
 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
 * defect found on 2026-07-27: this function used to ask three helpers for the
 * session, each of which swallowed every error into `null`, so a transient Stripe
 * failure was indistinguishable from "no purchase metadata" and fell through to
 * the top-up branch below reporting `fulfilled: true`. A real order then had its
 * card charged with no server, no FulfilledSession row and no notification — and
 * because the webhook returns 200 either way, Stripe never retried it. A throw
 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
 */
export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
  // ONE retrieve, one view of the session, shared by the credit and the routing.
  const session = await retrieveCheckoutSession(sessionId);
  const purpose = classifyCheckoutSession(session);
  return runFulfilment(session, purpose, base, "stripe");
}

/**
 * The actual dispatch, factored out of `fulfilCheckoutSession` so
 * `fulfilExternalPayment` (PayPal / Coinbase Commerce, below) can drive the exact
 * same claim/credit/provision/settle/notify logic from a SYNTHETIC session-shaped
 * object instead of a real Stripe retrieve. Nothing in this function's body
 * changed from the original `fulfilCheckoutSession` other than: (a) `sessionId` is
 * now read off `session.id` instead of being a separate parameter, and (b) the two
 * spots that are genuinely Stripe-only — crediting the wallet, and recording the
 * card for renewals — are gated on `provider === "stripe"`. Every claim/settle/
 * notify/provisioning line is untouched.
 */
async function runFulfilment(
  session: Stripe.Checkout.Session,
  purpose: CheckoutPurpose,
  base: string,
  provider: PaymentProvider,
): Promise<FulfilResult> {
  const sessionId = session.id;

  // Nothing was paid (an abandoned session id, or one replayed before capture).
  // Never claim fulfilment for money that has not arrived.
  if (purpose.kind === "unpaid") {
    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
  }

  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
  // transaction). We deliberately IGNORE its return value now — it reports who
  // won the credit race, which is not the same question as "has this been
  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
  // race: the money has not reached the wallet, so nothing below may spend it.
  //
  // `creditCheckoutSession` itself is Stripe-specific (it types its argument as a
  // real `Stripe.Checkout.Session`); PayPal/Coinbase route through
  // `creditExternalPayment` instead, which writes the identical
  // WalletTransaction/User.balanceCents/notification shape but with an honest
  // ledger label (never "Stripe payment" for money PayPal or Coinbase moved) and
  // no invoice branch, since every external-payment kind reaching this function is
  // a purchase leg, never a bare top-up — see that function's doc comment.
  if (provider === "stripe") {
    await creditCheckoutSession(session);
  } else {
    await creditExternalPayment(session, provider);
  }

  // Purchase metadata is present but cannot be trusted. Retrying will never fix
  // it, so claim the session and record the failure exactly like a failed order:
  // reconcilable, and the customer is told. What it must NEVER become is a silent
  // wallet top-up, which is precisely what the old `null` fall-through produced.
  if (purpose.kind === "unreadable") {
    if (await claim(sessionId, "unreadable")) {
      await settle(sessionId, "FAILED", purpose.detail);
      if (purpose.userId) await notifyStalled(purpose.userId);
    }
    return {
      redirect: `${base}/dashboard/billing?paid=1`,
      fulfilled: false,
      kind: "none",
      error: purpose.detail,
    };
  }

  const order = purpose.kind === "order" ? purpose : null;
  if (order) {
    if (!(await claim(sessionId, "order"))) {
      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
    }
    try {
      const user = await db.user.findUnique({ where: { id: order.userId } });
      if (!user) throw new Error("user not found for paid order");
      // Settle the price stamped on the session BEFORE the card was charged — never
      // a fresh quote taken now. The customer has already paid the card leg of that
      // exact total; re-pricing here and taking the difference out of the wallet is
      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
      // the resize and disk-expand branches below, which have always passed the
      // amount through metadata for this reason.
      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
      // per-IP cap can't be enforced here — the per-account unique still holds, and
      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
      // the card was charged, so the double-claim race is closed regardless. Fulfilment
      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
      // fresh claim. `campaign` rides in via metadata so attribution survives the card
      // round-trip even in the webhook (no cookies).
      const serverId = await placeOrder(user, order.intent, order.sold, {
        ipHash: null,
        campaign: order.campaign,
        promoReservationToken: order.promoReservationToken,
        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
        // token rather than contending for a fresh claim — no double-claim, no over-charge.
        couponReservationToken: order.couponReservationToken,
      });
      await settle(sessionId, "DONE", serverId);
      // Record the card this order was paid with (the session set
      // setup_future_usage) so the renewal sweep can auto-charge it next cycle.
      // Guarded: the money moved and the server exists — card recording must never
      // turn a completed fulfilment into a failure.
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, order.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "vps");
      return { redirect, fulfilled: true, kind: "order" };
    } catch (e) {
      // Payment is captured and the funds are in the wallet — record the failure
      // so it is reconcilable rather than invisible, and tell the customer.
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(order.userId);
      // Deploy-funnel: the card CLEARED but the order couldn't be placed — the one
      // payment-tail failure only visible server-side (the browser has left the
      // wizard, or this is the webhook). Recording it on the Payment step lets the
      // admin funnel tell "paid, then failed" from a plain abandon. Best-effort +
      // guarded so it never re-enters the money path we're unwinding.
      try {
        await recordDeployFunnelError({ product: "vps", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: order.userId });
      } catch {
        /* analytics must never disturb fulfilment */
      }
      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
    }
  }

  // Game-server order — the game analogue of the `order` branch above. Same claim /
  // settle / notify discipline; the card leg was credited to the wallet by
  // `creditCheckoutSession` above, then `placeGameOrder` debits the SOLD total back
  // out — never a fresh quote taken now (the H2 re-pricing incident). Game carries
  // no promo/coupon hold, so there is nothing to confirm and no per-IP concern here.
  const gameOrder = purpose.kind === "gameOrder" ? purpose : null;
  if (gameOrder) {
    if (!(await claim(sessionId, "gameOrder"))) {
      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "gameOrder" };
    }
    try {
      const user = await db.user.findUnique({ where: { id: gameOrder.userId } });
      if (!user) throw new Error("user not found for paid game order");
      const serverId = await placeGameOrder(user, gameOrder.intent, gameOrder.sold);
      await settle(sessionId, "DONE", serverId);
      // Save the card for off-session renewals (same guard as the order branch).
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, gameOrder.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "game");
      return { redirect, fulfilled: true, kind: "gameOrder" };
    } catch (e) {
      // Payment is captured and the funds are in the wallet — record the failure so
      // it is reconcilable rather than invisible, and tell the customer.
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(gameOrder.userId);
      // Deploy-funnel: card cleared but the game order couldn't be placed — the same
      // server-only payment-tail failure as the VPS branch above. Best-effort + guarded.
      try {
        await recordDeployFunnelError({ product: "game", step: "Payment", stepIndex: 4, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: gameOrder.userId });
      } catch {
        /* analytics must never disturb fulfilment */
      }
      return { redirect: `${base}/dashboard/games?paid=1`, fulfilled: false, kind: "gameOrder", error: msg };
    }
  }

  // Shared-hosting order funded by card — the hosting analogue of the `order` branch.
  // The card leg was credited to the wallet by `creditCheckoutSession` above; then
  // `placeHostingCardOrder` re-verifies this same session server-side and runs the
  // audited wallet placement (`placeHostingOrderCore`), which DEBITS the wallet and
  // claims its own `hostorder:<key>` marker — so a webhook + redirect can't place two
  // accounts even before the FulfilledSession claim below. Same claim/settle/notify
  // discipline; card save is best-effort so it can never fail a completed order.
  const hostOrder = purpose.kind === "hostOrder" ? purpose : null;
  if (hostOrder) {
    if (!(await claim(sessionId, "hostOrder"))) {
      return { redirect: `${base}/dashboard/hosting`, fulfilled: false, kind: "hostOrder" };
    }
    try {
      const res = await placeHostingCardOrder(sessionId);
      if ("skip" in res) throw new Error("session did not classify as a hosting order");
      if (!("accountId" in res) || !res.accountId) {
        throw new Error(("error" in res && res.error) || "hosting order failed");
      }
      await settle(sessionId, "DONE", res.accountId);
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, hostOrder.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      // Same `?purchase=1` stamp the VPS/game branches get via reportPurchase —
      // this was previously missing here, so a card-paid hosting order landed on
      // the account page with NO signal to <ProvisioningOverlay/> that a purchase
      // just completed (the SANDBOX-instant-complete case would then never show a
      // success card at all). See also the wallet-only path in
      // HostingDeployWizard.tsx's place(), which had the identical gap.
      const hostUser = await db.user.findUnique({ where: { id: hostOrder.userId } });
      const redirect = await reportPurchase(`${base}/dashboard/hosting/${res.accountId}`, session, hostUser?.email, hostOrder.userId, "hosting");
      return { redirect, fulfilled: true, kind: "hostOrder" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(hostOrder.userId);
      try {
        await recordDeployFunnelError({ product: "hosting", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: hostOrder.userId });
      } catch {
        /* analytics must never disturb fulfilment */
      }
      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "hostOrder", error: msg };
    }
  }

  // Business-email order funded by card — the email analogue of the branch above. The

  // Business-email order funded by card — the email analogue of the branch above. The
  // card leg was credited to the wallet; `placeEmailCardOrder` re-verifies the session
  // and runs `orderEmailHostingCore`, which DEBITS the wallet and creates the
  // subscription (its domain dupe guard is the placement idempotency).
  const emailOrder = purpose.kind === "emailOrder" ? purpose : null;
  if (emailOrder) {
    if (!(await claim(sessionId, "emailOrder"))) {
      return { redirect: `${base}/dashboard/email`, fulfilled: false, kind: "emailOrder" };
    }
    try {
      const res = await placeEmailCardOrder(sessionId);
      if ("skip" in res) throw new Error("session did not classify as an email order");
      if (res.error || !res.ok) throw new Error(res.error || "email order failed");
      await settle(sessionId, "DONE");
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, emailOrder.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      return { redirect: `${base}/dashboard/email?paid=1`, fulfilled: true, kind: "emailOrder" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(emailOrder.userId);
      return { redirect: `${base}/dashboard/email?paid=1`, fulfilled: false, kind: "emailOrder", error: msg };
    }
  }

  // Domain registration funded by card — the domain analogue of the branches
  // above. `placeDomainCardOrder` re-verifies the session itself and runs the
  // exact same `registerDomainCore` the wallet path uses (lib/actions-domains.ts),
  // against the FROZEN price + contact stashed in `DomainOrderIntent` at
  // checkout-session-creation time — never a fresh registrar re-quote here.
  // Its three outcomes ("active"/"recovered" from registerDomainCore's own
  // registered-verdict, "refunded", "needs-review") all still count as this
  // Stripe session being resolved — the card cleared and the money's fate is
  // decided either way — so all three claim + settle, and only "active" is
  // `fulfilled: true` with the success redirect.
  const domainOrder = purpose.kind === "domainOrder" ? purpose : null;
  if (domainOrder) {
    if (!(await claim(sessionId, "domainOrder"))) {
      return { redirect: `${base}/dashboard/domains`, fulfilled: false, kind: "domainOrder" };
    }
    try {
      const res = await placeDomainCardOrder(sessionId);
      if ("skip" in res) throw new Error("session did not classify as a domain order");
      if ("error" in res) throw new Error(res.error);
      if (res.kind === "active") {
        await settle(sessionId, "DONE", res.domainId);
        if (provider === "stripe") {
          try {
            await saveCardFromPaymentSession(session, domainOrder.userId);
          } catch {
            /* best-effort: fulfilment already succeeded */
          }
        }
        const domainUser = await db.user.findUnique({ where: { id: domainOrder.userId } });
        const redirect = await reportPurchase(
          `${base}/dashboard/domains/${res.domainId}?new=1`,
          session,
          domainUser?.email,
          domainOrder.userId,
          "domain",
        );
        return { redirect, fulfilled: true, kind: "domainOrder" };
      }
      // "refunded" (registrar confirmed not-registered, wallet refunded) or
      // "needs-review" (registrar status unconfirmed, flagged, never auto-
      // refunded) — the card cleared but this specific registration did not
      // complete. registerDomainCore already wrote its own domain-specific
      // notification/audit trail for both; settle + notifyStalled here matches
      // every other captured-but-unfulfilled branch in this file so the
      // Stripe-side bookkeeping (FulfilledSession) is reconcilable too.
      await settle(sessionId, "FAILED", res.message);
      await notifyStalled(domainOrder.userId);
      return {
        redirect: `${base}/dashboard/domains/${res.domainId}?paid=1`,
        fulfilled: false,
        kind: "domainOrder",
        error: res.message,
      };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(domainOrder.userId);
      return { redirect: `${base}/dashboard/domains?paid=1`, fulfilled: false, kind: "domainOrder", error: msg };
    }
  }

  const resize = purpose.kind === "resize" ? purpose : null;
  if (resize) {
    const back = `${base}/dashboard/servers/${resize.serverId}`;
    if (!(await claim(sessionId, "resize"))) {
      return { redirect: back, fulfilled: false, kind: "resize" };
    }
    try {
      await applyResize({
        serverId: resize.serverId,
        planId: resize.planId,
        actorUserId: resize.userId,
        chargeCents: resize.chargeCents,
      });
      await settle(sessionId, "DONE", resize.serverId);
      // `createResizeCheckout` now also sets setup_future_usage (this can be a
      // customer's first-ever card charge — e.g. an order the wallet or a 100%-off
      // promo fully covered), so record it here too. Best-effort: the upgrade
      // already succeeded.
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, resize.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      return { redirect: back, fulfilled: true, kind: "resize" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(resize.userId);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
    }
  }

  const expand = purpose.kind === "diskExpand" ? purpose : null;
  if (expand) {
    const back = `${base}/dashboard/servers/${expand.serverId}`;
    if (!(await claim(sessionId, "diskExpand"))) {
      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
    }
    try {
      await applyDiskExpand({
        serverId: expand.serverId,
        addGB: expand.addGB,
        actorUserId: expand.userId,
        chargeCents: expand.chargeCents,
      });
      await settle(sessionId, "DONE", expand.serverId);
      // Same reasoning as the resize branch above: `createDiskExpandCheckout` now
      // sets setup_future_usage too, and this can be a customer's first-ever card
      // charge. Best-effort: the expansion already succeeded.
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, expand.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(expand.userId);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
    }
  }

  const dedicatedIp = purpose.kind === "dedicatedIp" ? purpose : null;
  if (dedicatedIp) {
    const back = `${base}/dashboard/servers/${dedicatedIp.serverId}`;
    if (!(await claim(sessionId, "dedicatedIp"))) {
      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "dedicatedIp" };
    }
    try {
      await applyDedicatedIpPurchase({
        serverId: dedicatedIp.serverId,
        actorUserId: dedicatedIp.userId,
        chargeCents: dedicatedIp.chargeCents,
      });
      await settle(sessionId, "DONE", dedicatedIp.serverId);
      // Same reasoning as the resize/diskExpand branches above: this can be a
      // customer's first-ever card charge.
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, dedicatedIp.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "dedicatedIp" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(dedicatedIp.userId);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "dedicatedIp", error: msg };
    }
  }

  // Plain wallet top-up: crediting above is the whole job. Reached ONLY when the
  // session genuinely carried no purchase metadata — never because we failed to
  // read it (that throws) and never because we failed to parse it ("unreadable").
  //
  // The top-up session also set setup_future_usage, so record the card here too —
  // a customer who only ever tops up their wallet still ends up with a chargeable
  // card on file for renewals. Best-effort; the credit above already happened.
  if (provider === "stripe" && purpose.kind === "topup" && purpose.userId) {
    try {
      await saveCardFromPaymentSession(session, purpose.userId);
    } catch {
      /* best-effort: the wallet was already credited */
    }
  }
  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
}

/* ------------------------------------------------------------------ *
 * PayPal / Coinbase Commerce — the SAME dispatch, a synthetic session
 * ------------------------------------------------------------------ */

/**
 * Credit the wallet for a paid PayPal/Coinbase Commerce session — the non-Stripe
 * analogue of `creditCheckoutSession` (lib/stripe.ts). Deliberately a SEPARATE,
 * smaller function rather than a call into that one, for two reasons:
 *
 *  1. Honesty of the ledger. `creditCheckoutSession` hard-codes the wallet-
 *     transaction description as `Stripe payment (${session.id})`. Reusing it for
 *     PayPal/Coinbase would label a customer's PayPal or crypto payment as a
 *     "Stripe payment" in their own billing history AND in the admin refund
 *     tool's ledger search (`lib/actions-admin-billing.ts`'s `description:
 *     {contains: "Stripe payment (cs_"}` — that regex's `cs_` prefix requirement
 *     means a synthetic `paypal:`/`coinbase:` id would never match it anyway, so
 *     nothing is UNSAFE, but the label would still be a plain false statement.
 *  2. Every external-payment session reaching this function was created by our
 *     own `lib/actions-payment-providers.ts` order/charge-creation actions, which
 *     never create one without purchase metadata (order/gameOrder/hostOrder/
 *     emailOrder) — there is no "top up your wallet with PayPal/crypto" product.
 *     So unlike `creditCheckoutSession`, there is no top-up invoice branch here;
 *     `isPurchaseLegSession` is asserted rather than branched on, and a session
 *     that somehow fails it is refused loudly rather than silently treated as a
 *     top-up (exactly the "unrecognised metadata → top-up" bug `packMetadata`'s
 *     doc comment and the `unreadable` classification exist to end — the failure
 *     mode this function must never reintroduce from a different code path).
 *
 * Idempotent the same way: UNIQUE(stripeSessionId) on `WalletTransaction`, so a
 * client-driven capture racing the provider's webhook is safe — P2002 means
 * someone else already credited this exact session id.
 */
async function creditExternalPayment(
  session: Stripe.Checkout.Session,
  provider: Exclude<PaymentProvider, "stripe">,
): Promise<boolean> {
  const userId = session.metadata?.nxeonUserId;
  const cents = session.amount_total ?? 0;
  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;

  if (!isPurchaseLegSession(session.metadata)) {
    throw new Error(
      `${provider} payment ${session.id} carries no recognised purchase metadata — refusing to treat unrecognised money as a top-up`,
    );
  }

  const label = provider === "paypal" ? "PayPal" : "Coinbase Commerce";
  try {
    await db.$transaction([
      db.walletTransaction.create({
        data: {
          userId,
          amountCents: cents,
          description: `${label} payment (${session.id})`,
          stripeSessionId: session.id,
        },
      }),
      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
      db.notification.create({
        data: {
          userId,
          title: `Payment of $${(cents / 100).toFixed(2)} received`,
          href: "/dashboard/billing",
        },
      }),
    ]);
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
    throw e;
  }
  // Best-effort side effects, same as creditCheckoutSession — never allowed to
  // turn a completed credit into a reported failure.
  try {
    const { maybeRewardReferral } = await import("./actions-growth");
    await maybeRewardReferral(userId);
  } catch {
    /* best-effort */
  }
  // No generic "Payment received" receipt here: every session this function
  // credits is a purchase leg (see this function's doc comment — there is no
  // "top up with PayPal/crypto" product), so the order this money is funding
  // sends its own specific, itemised invoice_new email moments later. Sending
  // both meant a generic, invoice-less "your Nxeon order" receipt landed right
  // before the real invoice on every PayPal/Coinbase purchase — the exact
  // "this email is weak" duplication already removed from the Stripe path in
  // creditCheckoutSession.
  return true;
}

export type ExternalPaymentInput = {
  provider: Exclude<PaymentProvider, "stripe">;
  /** PayPal's order id, or Coinbase Commerce's charge code — the provider's own reference. */
  externalId: string;
  /** The `PendingExternalPayment` row id created when the order/charge was opened
   *  (lib/actions-payment-providers.ts) — the ONE place the full order metadata lives. */
  pendingId: string;
  base?: string;
};

/**
 * Fulfil a PAID PayPal order or Coinbase Commerce charge through the EXACT SAME
 * `runFulfilment` dispatch Stripe's `fulfilCheckoutSession` uses — the seam this
 * whole module exists to provide. Builds a SYNTHETIC `Stripe.Checkout.Session`-
 * shaped object from the `PendingExternalPayment` row (same nxeon* metadata keys,
 * `payment_status: "paid"`, the row's own server-computed `amountCents`) and hands
 * it to `runFulfilment` with `provider` set so the two Stripe-only steps above are
 * skipped. There is exactly ONE dispatch function in this codebase; this is how a
 * second payment rail reaches it without a second copy of the claim/settle/
 * provision/notify logic.
 *
 * Callers: the PayPal capture server action (client-driven, like Stripe's confirm
 * redirect) AND the PayPal webhook (the reliable backstop) — the SAME
 * confirm/webhook race Stripe already runs safely, because the claim below is the
 * same `FulfilledSession` UNIQUE(stripeSessionId) index, just keyed
 * `"paypal:<orderId>"` instead of a Stripe session id. Coinbase Commerce has no
 * client-driven capture step (crypto confirmation only ever arrives by webhook),
 * so its webhook is the only caller — still idempotent on its own if Coinbase ever
 * redelivers the event.
 *
 * THROWS if the `PendingExternalPayment` row cannot be found or its stored
 * metadata is not valid JSON — the same "throw rather than silently misclassify"
 * discipline `retrieveCheckoutSession` and `fulfilCheckoutSession` already apply
 * to a Stripe read failure. A row that cannot be trusted must never fall through
 * to the top-up branch.
 */
export async function fulfilExternalPayment(input: ExternalPaymentInput): Promise<FulfilResult> {
  const row = await db.pendingExternalPayment.findUnique({ where: { id: input.pendingId } });
  if (!row) {
    throw new Error(`No PendingExternalPayment row for id ${input.pendingId} (${input.provider} ${input.externalId})`);
  }
  if (row.provider !== input.provider) {
    throw new Error(
      `PendingExternalPayment ${input.pendingId} provider mismatch: expected ${input.provider}, stored ${row.provider}`,
    );
  }

  let metadata: Record<string, string>;
  try {
    const parsed = JSON.parse(row.metadata);
    if (!parsed || typeof parsed !== "object") throw new Error("not an object");
    metadata = parsed as Record<string, string>;
  } catch {
    throw new Error(`PendingExternalPayment ${input.pendingId} metadata is not readable JSON`);
  }

  // The provider-qualified id IS the FulfilledSession/WalletTransaction claim key —
  // "paypal:5O190127TN364715T" can never collide with a real Stripe `cs_...` id or
  // with the other provider's charge codes.
  const sessionId = `${input.provider}:${input.externalId}`;
  const synthetic = {
    id: sessionId,
    metadata,
    payment_status: "paid",
    amount_total: row.amountCents,
    currency: row.currency,
    customer: null,
    payment_intent: null,
  } as unknown as Stripe.Checkout.Session;

  const purpose = classifyCheckoutSession(synthetic);

  try {
    const result = await runFulfilment(synthetic, purpose, input.base ?? "", input.provider);
    await db.pendingExternalPayment
      .update({ where: { id: row.id }, data: { status: "PAID", providerRef: input.externalId } })
      .catch(() => {});
    return result;
  } catch (e) {
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
    throw e;
  }
}

// Re-exported so callers building a PendingExternalPayment row's `metadata`
// column can reuse the SAME 500-char-per-value refuse-don't-truncate guard
// Stripe metadata uses, instead of a second copy of that safety property.
export { packMetadata as packExternalPaymentMetadata, STRIPE_METADATA_VALUE_MAX };

// Shared game-server order core — the ONE audited debit path for game servers,
// used by the wallet flow (lib/actions-gameplans.ts payAndDeployGame /
// orderGameServer) AND the Stripe confirm/webhook fulfilment (lib/fulfil-checkout.ts)
// so a card-paid game order provisions through the SAME machinery a VPS order does.
// Plain server module (NOT "use server") — no secrets, callable from actions,
// server components and the worker/webhook alike.
//
// This is the game analogue of lib/order.ts (orderQuote / placeOrder). It was
// factored OUT of the original `orderGameServer` so the card path and the wallet
// path settle through one function instead of two copies that could drift.
//
// MONEY RULES (audited):
//   - Prices are strictly DB-fed: `gamePlan.priceCents` is the ONLY source, priced
//     through the SAME `termPriceCents` formula the deploy wizard shows and the
//     renewal sweep bills (displayed === charged === renewed).
//   - Game bills FULL from month 1. There is NO first-month-free on game (that promo
//     is Shared-Web-Hosting-only); no $0 path, no coupon, no VAT change here.
//   - The wallet is the single debit; `debitWallet` refuses to overdraw.
//   - `sold` (card path) carries the price the order was SOLD at, stamped BEFORE the
//     card cleared, so fulfilment never re-prices after the money moved (the H2
//     incident guarded on lib/order.ts OrderPrice).
import { Prisma } from "@prisma/client";
import type { User } from "@prisma/client";
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { addMonths, normalizeProductTerm, termPriceCents, vpsTerm } from "./billing-terms";
import { annualDiscountPct } from "./annual-discount";
import { capacityCheck } from "./capacity";
import { scheduleNode } from "./node-capacity";
import { CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";
import { GAME_FAMILIES, type GameFamily } from "./games";
import { schemaFor, isValidVariant, validateConfig } from "./game-config";
import { recordDeployFunnelComplete } from "./deploy-funnel";
import { getSettingBool, getSettingInt } from "./settings";
import { invoiceCreateData, invoiceBranding, formatInvoiceNumber } from "./invoices";
import { validateSubdomainFormat, isSubdomainAvailable } from "./game-subdomain";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";

export class GameOrderError extends Error {}

/**
 * Feature + capacity gate shared by every game order entry point: the game-servers
 * feature can be switched off platform-wide (flag), and game servers are Server rows
 * too so they count toward the per-user cap. Returns a customer-facing error to
 * surface, or null to proceed.
 *
 * Lives in this PLAIN module (not lib/actions-gameplans.ts, which is `"use
 * server"`) rather than being exported from there, even though it is only ever
 * called with an already-authenticated `user` — a function that takes an
 * arbitrary `User`-shaped argument and does no session check of its own is
 * exactly what test/auth-lockouts.test.ts's "HAZARD" suite exists to catch the
 * moment it is exported from a Server Actions file: every export of such a file
 * is a public network endpoint, and this one would let a stranger probe any
 * userId's server count with no authentication at all. `lib/actions-gameplans.ts`
 * (payAndDeployGame, orderGameServer) and lib/actions-payment-providers.ts
 * (PayPal/Coinbase game-order creation) both call this AFTER their own
 * `requireUser()` — the guard the network-facing wrapper is responsible for.
 */
export async function gameOrderGate(user: User): Promise<string | null> {
  if (!(await getSettingBool("feature_game_servers", true))) {
    return "Game servers aren't available right now.";
  }
  const cap = await getSettingInt("max_servers_per_user", 10);
  if (cap > 0) {
    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
    if (owned >= cap) {
      return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.`;
    }
  }
  return null;
}

/** Extract a GameOrderIntent from a deploy form — shared by the wallet/card wizard
 *  action (lib/actions-gameplans.ts) and the PayPal/Coinbase order-creation actions
 *  (lib/actions-payment-providers.ts), so both parse the SAME form shape. Pure —
 *  lives in this plain module for the same "don't export a non-guarding helper from
 *  a Server Actions file" reason `gameOrderGate` above documents. */
export function gameIntentFromFormData(formData: FormData): GameOrderIntent {
  let config: Record<string, unknown> | null = null;
  const rawConfig = formData.get("config");
  if (typeof rawConfig === "string" && rawConfig.trim() !== "") {
    try {
      const parsed = JSON.parse(rawConfig);
      if (parsed && typeof parsed === "object") config = parsed as Record<string, unknown>;
    } catch {
      // A malformed config blob is dropped, not trusted — `gameOrderQuote` then
      // fills defaults. It can never widen the charge (game is a flat term price).
      config = null;
    }
  }
  return {
    gamePlanId: String(formData.get("gamePlanId") ?? ""),
    termMonths: Number(formData.get("termMonths") ?? 1),
    serverName: String(formData.get("serverName") ?? "").trim() || undefined,
    hostname: String(formData.get("hostname") ?? "").trim() || undefined,
    variant: String(formData.get("variant") ?? "").trim() || undefined,
    subdomain: String(formData.get("subdomain") ?? "").trim().toLowerCase() || undefined,
    dedicatedIp: formData.get("dedicatedIp") === "1",
    config,
  };
}

/** Hostname rules mirror the VPS order path (lib/order.ts orderSchema). */
const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;

/** Short random suffix so auto-generated hostnames don't collide. */
export function randSuffix(n = 6): string {
  return Math.random().toString(36).slice(2, 2 + n);
}

/**
 * The customer's full game-order intent — the tier, the billing term and the
 * per-game setup captured by the wizard. `config` holds the raw gameplay values
 * (validated against the family schema in `gameOrderQuote`); `variant` is the
 * server type/loader.
 */
export type GameOrderIntent = {
  gamePlanId: string;
  /** 1 (Monthly) or 12 (Annual) — normalised through normalizeProductTerm. */
  termMonths: number;
  /** Optional customer-facing nickname → Server.label. */
  serverName?: string;
  /** DNS-safe hostname → Server.name/hostname. Blank => auto-generated. */
  hostname?: string;
  /** Game type/loader id (e.g. "paper", "carbon"); validated per family. */
  variant?: string;
  /** Minecraft only: `<subdomain>.play.nxeon.cloud` — see lib/game-subdomain.ts. Required for minecraft orders. */
  subdomain?: string;
  /** Whether the customer opted for a dedicated IPv4 (paid addon). */
  dedicatedIp?: boolean;
  /** Raw gameplay settings; validated + coerced against the family schema. */
  config?: Record<string, unknown> | null;
};

/**
 * The price a game order was SOLD at, stamped onto the Stripe session BEFORE the
 * card was charged and read back at fulfilment. Game has no promo/coupon/tax, so
 * this is just the net charge — a deliberately tiny shape (compare lib/order.ts
 * OrderPrice, which must also carry promo + VAT).
 */
export type GameOrderPrice = { chargeCents: number };

/** Parse a sold game price back off Stripe metadata; null unless well-formed. */
export function parseGameOrderPrice(raw: unknown): GameOrderPrice | null {
  let obj: unknown = raw;
  if (typeof raw === "string") {
    try {
      obj = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== "object") return null;
  const { chargeCents } = obj as Record<string, unknown>;
  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
  return { chargeCents };
}

export type GameOrderQuote = {
  gamePlanId: string;
  gameFamily: string;
  planName: string;
  basePlanId: string;
  /** The base plan's RAM — fed to scheduleNode() to pick a node, same as VPS orders. */
  ramMB: number;
  osTemplateId: string;
  /** Normalised term (1 or 12). */
  term: number;
  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
  annualPct: number;
  /** DB-fed per-month base (priceCents / termMonths). */
  monthlyCents: number;
  /** The net charge for the whole term — displayed === charged === renewed. */
  chargeCents: number;
  hostname: string;
  label: string | null;
  variant: string;
  /** Minecraft only: the validated, available `<subdomain>.play.nxeon.cloud` label. Null for every other family. */
  subdomain: string | null;
  /** Whether the customer opted for a dedicated IPv4. */
  dedicatedIp: boolean;
  /** The dedicated-IP surcharge included in `chargeCents` (0 when not opted in). */
  ipCents: number;
  /** Clean, fully-populated gameplay values ready to persist (may be empty). */
  values: Record<string, string | number | boolean>;
};

/**
 * Validate + price a game order without placing it. Throws GameOrderError on any
 * problem. Pure of side effects beyond reads. The price is the whole truth about
 * what this order costs; the caller (wallet split, review step, checkout stamp)
 * quotes from THIS so what the customer sees is what settles.
 */
export async function gameOrderQuote(intent: GameOrderIntent): Promise<GameOrderQuote> {
  const term = normalizeProductTerm(intent.termMonths);

  const gp = await db.gamePlan.findUnique({
    where: { id: intent.gamePlanId },
    include: { basePlan: true },
  });
  // A ONE-OFF CUSTOM game tier (lib/custom-plan.ts createCustomGamePlan, "build a
  // custom server") and its backing base Plan are both deliberately created
  // `active: false` — see the matching comment on lib/order.ts orderQuote's own
  // gate for why (30+ untouched `where: { active: true }` catalog queries across
  // this codebase must never surface either row generically). `sortOrder` is the
  // marker reserved for exactly this row shape, accepted here as an alternative.
  if (!gp || (!gp.active && gp.sortOrder !== CUSTOM_PLAN_SORT_ORDER)) {
    throw new GameOrderError("That game plan isn't available.");
  }
  if (!gp.basePlan?.active && gp.basePlan?.sortOrder !== CUSTOM_PLAN_SORT_ORDER) {
    throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
  }
  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
    throw new GameOrderError("Unknown game family.");
  }

  // Resolve the game image: the tier's own OsTemplate, else any active image for
  // this family. A game server can't provision without an image.
  let osTemplateId = gp.osTemplateId;
  if (osTemplateId) {
    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
    if (!os?.active) osTemplateId = null;
  }
  if (!osTemplateId) {
    const os = await db.osTemplate.findFirst({
      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
      orderBy: { sortOrder: "asc" },
    });
    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
    osTemplateId = os.id;
  }

  // Hostname: validate a provided one strictly, else auto-generate a safe one.
  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
  let hostname = rawHost;
  if (hostname === "") {
    hostname = `${gp.gameFamily}-${randSuffix()}`;
  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
    throw new GameOrderError(
      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
    );
  }

  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;

  // Per-game setup: variant + gameplay settings, validated against the family
  // schema. Families without a customization schema (e.g. Terraria) carry no
  // variant and no gameplay values — the wizard shows only identity fields for them.
  const schema = schemaFor(gp.gameFamily);
  let variant = "";
  let values: Record<string, string | number | boolean> = {};
  if (schema) {
    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
    if (!isValidVariant(gp.gameFamily, variant)) {
      throw new GameOrderError("Choose a valid server type for this game.");
    }
    const res = validateConfig(gp.gameFamily, intent.config ?? {});
    if (!res.ok) throw new GameOrderError(res.error);
    values = res.values;
  }

  }

  // Minecraft-only: a customer-chosen `<subdomain>.play.nxeon.cloud`, required at
  // checkout (see lib/game-subdomain.ts — the free tier's own name rules, shared
  // so the two products can never disagree on what's valid or taken). Every other
  // family has no SRV-record connect story, so this stays null for them.
  let subdomain: string | null = null;
  if (gp.gameFamily === "minecraft") {
    const sub = (intent.subdomain ?? "").trim().toLowerCase();
    if (!sub) throw new GameOrderError("Pick a subdomain for your server — this is how players will connect.");
    const formatError = validateSubdomainFormat(sub);
    if (formatError) throw new GameOrderError(formatError);
    if (!(await isSubdomainAvailable(sub))) throw new GameOrderError("That subdomain is taken — try another.");
    subdomain = sub;
  }

  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
  // divisor keeps the maths correct if a multi-month base plan is ever configured.
  const annualPct = await annualDiscountPct();
  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
  const wantIp = !!intent.dedicatedIp;
  const ipCents = wantIp ? (await dedicatedIpMonthlyCents()) * term : 0;
  const chargeCents = termPriceCents(monthlyCents, term, annualPct) + ipCents;

  return {
    gamePlanId: gp.id,
    gameFamily: gp.gameFamily,
    planName: gp.name,
    basePlanId: gp.basePlanId,
    ramMB: gp.basePlan.ramMB,
    osTemplateId,
    term,
    annualPct,
    monthlyCents,
    chargeCents,
    hostname,
    label,
    variant,
    subdomain,
    dedicatedIp: wantIp,
    ipCents,
    values,
  };
}

/**
 * Place a game order: re-validate + price, capacity-check, then atomically debit
 * the wallet and create the Server (sized by the tier's base VPS plan, running the
 * game image, with the customer's variant + gameplay settings) plus a PROVISION
 * job. Returns the new server id. Does NOT redirect.
 *
 * `sold` (card path) overrides the recomputed price with the one the order was
 * SOLD at — the card-paid path passes the figure stamped on the Checkout session
 * BEFORE the card was charged, so the confirm/webhook fulfilment settles the price
 * the customer consented to instead of re-pricing against a rate that changed in
 * between. The wallet path omits it and pays the fresh quote it computed moments
 * ago. This mirrors `sold` in lib/order.ts placeOrder.
 *
 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
 * path is gated by the balance check in the action). This still enforces the
 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
 */
export async function placeGameOrder(
  user: User,
  intent: GameOrderIntent,
  sold?: GameOrderPrice | null,
): Promise<string> {
  const quote = await gameOrderQuote(intent);

  // Bill off the SOLD price when present (never re-priced after the card cleared),
  // else the fresh quote. Game has no promo/coupon, so this scalar is the whole
  // truth about what this order costs.
  const chargeCents = sold?.chargeCents ?? quote.chargeCents;

  // Oversell guard — the VPS order path enforces this; game orders must too, or a
  // game server could commit host RAM past capacity.
  const capacity = await capacityCheck(quote.basePlanId);
  if (!capacity.ok) {
    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
  }

  // Pick a node the same way a VPS order does — without this, every game
  // server's `nodeId` stays null and `worker/index.ts`'s `nodeFor()` fallback
  // (`server.node ?? primary node`) pins EVERY game server onto the primary
  // node forever, regardless of its actual load. Confirmed live: every game
  // server in production had nodeId: null and primary sat at 84% real RAM /
  // 200% committed CPU while other nodes were comparatively idle.
  const node = await scheduleNode(quote.ramMB);

  // Balance gate BEFORE the tx so we fail cleanly (no money moved). On the card
  // path the wallet was credited the card leg first, so this holds.
  if (user.balanceCents < chargeCents) {
    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
  }

  const effMonthly = quote.term > 1 ? Math.round(chargeCents / quote.term) : 0;
  const termLabel =
    quote.term > 1 ? `${vpsTerm(quote.term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(quote.term).label;

  // Line-item description shared by the wallet-transaction memo and the invoice —
  // mirrors lib/order.ts's VPS line ("<plan> VPS (<hostname>) — <term>"), the
  // pattern lib/actions-hosting.ts and lib/actions-email-hosting.ts also follow.
  const invDesc = `${quote.planName} Game Server (${quote.hostname}) — ${termLabel}`;

  let server;
  // Captured from the in-tx invoice.create so the paid ORDER invoice can be emailed
  // (with its PDF) AFTER the transaction commits — a rolled-back order leaves this
  // null and emails nothing. Mirrors `orderInvoice` in lib/order.ts placeOrder.
  let orderInvoice: { id: string; number: number; amountCents: number } | null = null;
  try {
    server = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
        },
      });
      // Billing document for the charge — created inside the same debit tx so it
      // shares the transaction's atomicity (a rolled-back charge leaves no invoice),
      // exactly like lib/order.ts's VPS invoice and worker/billing.ts's renewal
      // invoice. Game has no promo/coupon/tax (see GameOrderPrice), so this is a
      // single line for the full charge.
      const createdInvoice = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: invDesc,
          status: "PAID",
          taxCents: 0,
          taxRatePercent: 0,
          taxCountry: null,
          period: { start: new Date(), end: addMonths(new Date(), quote.term) },
          lineItems: [{ description: invDesc, qty: 1, unitCents: chargeCents, amountCents: chargeCents }],
        }),
      });
      orderInvoice = {
        id: createdInvoice.id,
        number: createdInvoice.number,
        amountCents: createdInvoice.amountCents,
      };
      const s = await tx.server.create({
        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
        // on Server until regenerated at deploy (see lib/order.ts's Server create).
        data: {
          name: quote.hostname,
          hostname: quote.hostname,
          label: quote.label,
          userId: user.id,
          planId: quote.basePlanId,
          gamePlanId: quote.gamePlanId,
          osTemplateId: quote.osTemplateId,
          // The customer's per-game setup, applied at the point of sale — the worker
          // renders these into the game's own config at provision (worker/game-config).
          gameVariant: quote.variant || null,
          subdomain: quote.subdomain,
          gameConfig: Object.keys(quote.values).length > 0 ? quote.values : Prisma.JsonNull,
          // The chosen term rides the Server row (Monthly / Annual); renewalCharge's
          // game branch renews monthlyCents × termMonths × (1 − annual).
          termMonths: quote.term,
          // No seasonal promo on game — this term was sold at 0% off, so any future
          // proration prices against full price.
          termPromoPercent: 0,
          // The annual rate frozen at sale, so the renewal bills the SAME price the
          // order charged even if the admin retunes annual_discount_percent later.
          annualDiscountPct: quote.annualPct,
          nodeId: node?.id ?? null,
          wantsDedicatedIp: quote.dedicatedIp,
          expiresAt: addMonths(new Date(), quote.term),
        } as Prisma.ServerUncheckedCreateInput,
      });
      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
      return s;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      throw new GameOrderError("Insufficient balance. Top up your wallet first.");
    }
    // Narrow race: another order claimed the same subdomain between the
    // isSubdomainAvailable check above and this insert (or the free tier just
    // claimed the same name in the other table's own concurrent request).
    if ((e as { code?: string })?.code === "P2002") {
      throw new GameOrderError("That subdomain was just taken — go back and pick another.");
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "gameserver.order",
      detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"}`,
    },
  });
  // Deploy-funnel COMPLETION — the game analogue of lib/order.ts placeOrder. The ONE
  // place a game order is created & paid, reached by BOTH the wallet path
  // (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts webhook /
  // redirect), so every completed game deploy is counted once with a reliable userId.
  // Terminal event (drives the completed counts, not a wizard-step row); best-effort
  // and double-guarded so it can never disturb the money path.
  try {
    await recordDeployFunnelComplete({ product: "game", step: "Complete", stepIndex: 5, userId: user.id });
  } catch {
    /* never let funnel bookkeeping affect a completed order */
  }
  // Email the paid ORDER invoice with its PDF attached. Best-effort AND post-commit:
  // the money has already moved, so a mail failure must NEVER surface as an order
  // failure. Fires exactly once per order (single commit) and covers BOTH the wallet
  // path (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts)
  // because both go through this one placeGameOrder — mirrors lib/order.ts placeOrder
  // and lib/actions-email-hosting.ts orderEmailHostingCore. Read via the declared
  // union — the value is assigned inside the $transaction callback, which TS
  // control-flow analysis does not track, so a direct read would narrow to `null`.
  const invForEmail = orderInvoice as { id: string; number: number; amountCents: number } | null;
  if (invForEmail) {
    try {
      const { sendMail, emails } = await import("./mailer");
      const branding = await invoiceBranding();
      const tpl = emails.invoiceNew(
        {
          invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
          amount: `$${(invForEmail.amountCents / 100).toFixed(2)}`,
          dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
          description: invDesc,
        },
        true, // the itemised PDF is attached (invoiceId passed below)
      );
      await sendMail({
        to: user.email,
        subject: tpl.subject,
        html: tpl.html,
        template: tpl.template,
        invoiceId: invForEmail.id,
        userId: user.id,
        kind: "invoice",
      });
    } catch {
      /* invoice email is best-effort — a placed order must never fail on mail */
    }
  }
  return server.id;
}

import { convertAndFormat, DEFAULT_CURRENCY } from "@/lib/currency";
import { trackDeployStep, trackDeployError } from "@/lib/deploy-funnel-client";

type Plan = {
  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
  bandwidthTB: number; priceCents: number; storageTier: string;
};
type Image = {
  id: string; slug: string; name: string; category: string; family: string;
  version: string; logo: string; minRamMB: number; minDiskGB: number;
  licenseRequired: boolean; featured: boolean;
};
type NodeOpt = { id: string; name: string; publicIp: string };

// USD formatter — this wizard's long-standing 2-decimal style ("$5.00"). Used
// verbatim for the USD display path (so USD renders byte-for-byte unchanged) and
// for the "billed in USD" reference note. `money()` (defined per-render inside the
// component, currency-aware) is what the UI actually calls.
const usd = (c: number) => `$${(c / 100).toFixed(2)}`;

/** sessionStorage key for the in-progress order — see the restore effect below. */
const DRAFT_KEY = "nxeon.deploy.draft.v1";
type Draft = {
  step: number;
  planId: string;
  nodeId: string;
  imageId: string;
  tab: string;
  addons: { malware: boolean; backup: boolean; docker: boolean };
  dedicatedIp: boolean;
  extraDiskGB: number;
  hostname: string;
  pubKey: string;
  termMonths: number;
  useWallet: boolean;
  /** A confirmed custom plan, carried through the Stripe cancel round-trip since
   *  it's never in the server-fetched `plans` prop (see the `customPlan` state
   *  doc comment above). Null when the customer picked a premade plan. */
  customPlan: Plan | null;
};

/**
 * APPLICATION-category images with one of these families are split into the
 * Games tab instead of Applications. Sourced from lib/games.ts's GAME_FAMILIES
 * — the single canonical list of all game families (19, not just the original
 * 6) — rather than a local copy-pasted set. A local copy here previously only
 * knew about minecraft/valheim/rust/palworld/cs2/terraria, so every game added
 * since (ARK, Satisfactory, Project Zomboid, 7 Days to Die, V Rising,
 * Enshrouded, Factorio, Garry's Mod, Conan Exiles, Unturned, The Forest, Sons
 * of the Forest, Minecraft Bedrock) silently fell through into Applications,
 * duplicating what the Games tab (and the dedicated Game Server product) already
 * list properly. Importing the shared list keeps this in sync by construction.
 */
const GAME_FAMILIES = new Set<string>(GAME_FAMILY_LIST);

/** Install-step tabs. Games are peeled out of Applications into their own tab. */
const TABS = [
  { key: "os", label: "Operating Systems", match: (i: Image) => i.category === "PLAIN_OS" },
  { key: "panels", label: "Control Panels", match: (i: Image) => i.category === "CONTROL_PANEL" },
  { key: "apps", label: "Applications", match: (i: Image) => i.category === "APPLICATION" && !GAME_FAMILIES.has(i.family) },
  { key: "games", label: "Games", match: (i: Image) => i.category === "APPLICATION" && GAME_FAMILIES.has(i.family) },
] as const;

const OS_FAMILY_NAMES: Record<string, string> = {
  ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
  fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", kali: "Kali Linux", opensuse: "openSUSE",
};
/**
 * Human name for an image on the confirmation screen.
 *
 * Catalogue rows carry the version in BOTH `name` ("Ubuntu 20.04") and `version`
 * ("20.04"), so appending unconditionally printed "Ubuntu 20.04 20.04" — on the
 * last screen before the customer pays. Only append a version the name does not
 * already end with.
 */
function imageLabel(img: Image) {
  const version = img.version?.trim();
  if (!version) return img.name;
  return img.name.trim().endsWith(version) ? img.name : `${img.name} ${version}`;
}

/** Clean family display name (no version) for the OS family cards. */
function osFamilyName(img: Image) {
  return OS_FAMILY_NAMES[img.family] ?? img.name.replace(/\s+\d.*$/, "").trim() ?? img.family;
}

/**
 * A short, collision-avoiding suffix (3–4 lowercase base36 chars) for the default
 * hostname. Browser runtime, display-only — `Math.random` is fine here. The regex
 * strip + `padEnd` guarantee the result is [a-z0-9] and at least 3 chars, so the
 * hostname built from it always satisfies `hostnameValid`.
 */
function randHostSuffix() {
  return Math.random().toString(36).replace(/[^a-z0-9]/g, "").slice(0, 4).padEnd(3, "0");
}
/**
 * A friendly, always-valid default hostname derived from the chosen image family
 * plus `suffix` — e.g. "ubuntu-0k4f", "debian-9c1". Lowercase, starts with a
 * letter/digit, contains no leading/trailing hyphen, so it passes `hostnameValid`
 * out of the box and a first-timer never has to invent a name to move on.
 */
function defaultHostnameFor(image: Image | undefined, suffix: string) {
  const base = (image?.family ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 24);
  const stem = base.length >= 2 ? base : "nxeon";
  return `${stem}-${suffix}`;
}

function Stepper({ step, steps }: { step: number; steps: string[] }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {steps.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

export function DeployWizard({
  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
  extraDiskPriceCentsPerGb = 0,
  backupPlusPriceCents = 0,
  defaultPlanId, defaultTermMonths,
  promoPercent = 0, promoLabel,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
  taxRatePercent = 0, taxCountry = "",
  email = "",
  paypalReady = false, paypalClientId = "",
  coinbaseReady = false,
  customPlanFloor, customPlanCeiling, customPlanRates,
}: {
  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
  /**
   * Price per GB per month for extra ROOT DISK (admin setting
   * `extra_disk_gb_price_cents`). Priced over the term exactly like the dedicated
   * IP add-on, so the maths here matches lib/order.ts orderQuote byte-for-byte.
   * 0 hides the upsell entirely.
   */
  extraDiskPriceCentsPerGb?: number;
  /**
   * Monthly price of the Plus backup-retention tier (admin setting
   * `backup_plus_price_cents`). Priced over the term like the other add-ons so this
   * matches lib/order.ts orderQuote byte-for-byte.
   */
  backupPlusPriceCents?: number;
  /**
   * Plan pre-selected on step 1, from the `default_plan_slug` admin setting.
   *
   * An **id**, not the slug the setting stores: this component's `Plan` type carries no
   * slug, so matching here would mean widening the payload or matching on `name`. The
   * page resolves slug → id against the very array it passes down, so any id arriving
   * here is guaranteed to be in `plans`; a stale slug (plan renamed, or deactivated)
   * arrives as `undefined` and the wizard falls back to the first plan rather than
   * opening with nothing selected and no price on the Review step.
   */
  defaultPlanId?: string;
  /**
   * Billing term pre-selected on the Review step, in MONTHS, from `default_term`.
   *
   * Guaranteed by `defaultTermMonths()` to be one of `VPS_TERMS`. That guarantee is
   * load-bearing: the term buttons below are rendered straight from `VPS_TERMS` and
   * highlight on `termMonths === t.months`, so an unlisted value (the old setting's
   * "quarterly", say) would render a Review step with no term highlighted while the
   * hidden `termMonths` field still posted it — and `vpsTerm()` silently falls back to
   * monthly, so the customer would be charged for a term nothing on screen showed.
   */
  defaultTermMonths?: number;
  /** Active intro-promo discount (%) on the FIRST term — matches what payAndDeploy charges. */
  promoPercent?: number; promoLabel?: string;
  /**
   * The admin ANNUAL discount (`annual_discount_percent`), resolved server-side and
   * passed in so the Annual term card's price, savings and `−X%` badge are the REAL
   * configured rate — the same one lib/order.ts charges and renewalCharge renews at.
   * Threaded into `renewalQuote` below so displayed === charged === renewed. Only
   * affects the 12-month card; every other term keeps its fixed rate.
   */
  annualDiscountPct?: number;
  /**
   * Destination VAT/GST rate (%) for THIS customer's billing country (Finding 1),
   * resolved server-side (lib/tax.ts taxContextForUser). 0 (the default, and the case
   * for any customer with no billing country on file) adds no tax and leaves the total
   * exactly as before. When > 0 the summary shows a tax line and `dueCents` is made
   * tax-inclusive, so what is shown here === what payAndDeploy charges.
   */
  taxRatePercent?: number;
  taxCountry?: string;
  /** The account's own email — shown read-only on the embedded Payment step
   *  ("your invoice will be sent to this email"). Not editable there: Stripe's
   *  customer record and every receipt/invoice this platform sends already use
   *  the account email, so an editable copy here would silently do nothing,
   *  which is worse than not offering it. */
  email?: string;
  /** `paypalConfigured()` / `coinbaseConfigured()` (lib/paypal.ts,
   *  lib/coinbase-commerce.ts) — plain env-var reads, resolved server-side and
   *  passed down so the embedded Payment step shows/hides those rows without
   *  ever rendering a broken option when the owner hasn't set up the account yet. */
  paypalReady?: boolean;
  paypalClientId?: string;
  coinbaseReady?: boolean;
  /**
   * The "build a custom server" builder's floor/ceiling/rates — resolved
   * server-side (lib/custom-plan.ts customPlanFloor/customPlanCeiling/customPlanRates)
   * so the sliders can price a live preview with zero round trips, using the exact
   * same pure formula (lib/custom-plan-pricing.ts) the server re-validates against
   * at confirm time. Undefined only if the catalog has no active premade plan at
   * all (shouldn't happen), in which case the entry point is hidden.
   */
  customPlanFloor?: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number; bandwidthTB: number };
  customPlanCeiling?: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
  customPlanRates?: { perVcpuCents: number; perRamGbCents: number; perDiskGbCents: number };
}) {
  const [state, action, pending] = useActionState(
    payAndDeploy,
    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
  );
  // The embedded Stripe session to mount in a modal on THIS page (no redirect),
  // set only on an explicit Deploy submit (see submittedRef below).
  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  // DISPLAY-ONLY price formatter. In USD it renders exactly as before (byte-for-byte
  // — the 2-decimal `usd()` style); any other selected display currency converts the
  // USD-cents amount for on-screen reference only. Every value posted to payAndDeploy
  // stays USD cents (the hidden fields carry selections, not money). See the
  // display/charge boundary note in lib/currency.ts.
  const { currency, rate } = useCurrency();
  const money = (c: number) =>
    currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);
  // Apply the first-term promo to any regular price, mirroring promoPriceCents()
  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
  const hasPromo = promoPercent > 0;
  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
  const submittedRef = useRef(false);
  // "loading"/"error" ONLY track the embedded Payment step's own session
  // request (see requestStripeSession below) — real React state, not a ref, so
  // the UI reflects "preparing payment" the instant the request is made rather
  // than a render or two later once `pending` catches up. "ready" is never
  // stored here: `checkoutSession` being non-null already means ready.
  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
  useEffect(() => {
    if (submittedRef.current) {
      submittedRef.current = false;
      if (state?.checkout) {
        // The "vps" conversion is fired at FULFILMENT (PurchaseTracker, with the
        // real charged value + transaction_id) — NOT here at checkout-start,
        // which would count customers who abandon at the payment step.
        setCheckoutSession(state.checkout);
      } else {
        setCheckoutSession(null);
        if (state?.error) setStripePhase("error");
      }
    }
    // `dueCents` is derived state read only inside the fire-and-forget tracking call;
    // resolving the request depends only on `state`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state]);
  // The form itself, so the embedded Payment step (PaymentStep) can request a
  // Stripe session the SAME way the old "Deploy" button did — a real
  // `requestSubmit()` through the exact same `<form action={action}>` — without
  // duplicating payAndDeploy's promo/coupon/tax pricing logic in a second place.
  const formRef = useRef<HTMLFormElement>(null);
  const requestStripeSession = useCallback(() => {
    setStripePhase("loading");
    submittedRef.current = true;
    formRef.current?.requestSubmit();
  }, []);
  const multiNode = nodes.length > 1;
  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
  const [step, setStep] = useState(0);
  // Inline term-change reveal on the Payment step's Order Summary — clicking
  // "Change" there used to jump all the way back to step 0 (Plan), losing the
  // customer's place on the last step of the wizard. Toggling this instead
  // reveals the same TermLadder cards right above the payment form.
  const [showTermPicker, setShowTermPicker] = useState(false);

  // Deploy-funnel: record reaching each wizard step (de-duped per session in the
  // helper) so the admin funnel shows how far people get. Delayed a few seconds
  // rather than firing on mount — an instant bounce (e.g. a curious click on the

// rather than firing on mount — an instant bounce (e.g. a curious click on the
// generic "Deploy" nav link, which lands here by default with no ?product=)
// was inflating the Plan-step numerator with visits that never actually looked
// at pricing. Cleared if the step changes again or the wizard unmounts before
// the delay elapses, so only a genuine few-second view counts.
useEffect(() => {
  const t = window.setTimeout(() => {
    trackDeployStep("vps", steps[step] ?? String(step), step);
  }, 3000);
  return () => window.clearTimeout(t);
  // steps content is stable; fire on step change only.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [step]);

// Deploy-funnel: when payAndDeploy returns an error, record it against the
// current step so a BUG/provision failure is distinguishable from abandonment.
useEffect(() => {
  if (state?.error) trackDeployError("vps", steps[step] ?? "Review", step, "ORDER_ERROR", state.error);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [state?.error]);

const [planId, setPlanId] = useState(defaultPlanId ?? plans[0]?.id ?? "");
// A confirmed custom plan (see the "Build a custom server" panel below) is a
// REAL Plan row (lib/custom-plan.ts createCustomPlan) but never appears in the
// `plans` prop — it's created inactive so it can never pollute the catalog any
// other customer sees. Holding it here lets the rest of this component keep
// reading a single `plan` object (see the derivation below) exactly as it did
// before this feature existed.
const [customPlan, setCustomPlan] = useState<Plan | null>(null);
const [customBuilderOpen, setCustomBuilderOpen] = useState(false);
// Slider state, initialised lazily to the floor (Max) the first time the panel
// opens — see the `openCustomBuilder` handler below.
const [customSpec, setCustomSpec] = useState<CustomPlanSpec | null>(null);
const [customCapacity, setCustomCapacity] = useState<{ ok: boolean; reason?: string } | null>(null);
const [customChecking, setCustomChecking] = useState(false);
const [customConfirming, setCustomConfirming] = useState(false);
const [customError, setCustomError] = useState("");
const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
const [imageId, setImageId] = useState(images.find((i) => i.category === "PLAIN_OS")?.id ?? images[0]?.id ?? "");
const [tab, setTab] = useState<string>("os");
const [modalFamily, setModalFamily] = useState<string | null>(null);
const [q, setQ] = useState("");
const [addons, setAddons] = useState({ malware: false, backup: false, docker: false });
const [dedicatedIp, setDedicatedIp] = useState(false);
// Backup RETENTION tier: "FREE" (keep 2, included) or "PLUS" (keep 7, paid).
const [backupTier, setBackupTier] = useState<"FREE" | "PLUS">("FREE");
// Extra ROOT DISK bought up front. One-way: this space can never be removed
// later, which the Add-ons card and the Review step both state before payment.
const [extraDiskGB, setExtraDiskGB] = useState(0);
const [hostname, setHostname] = useState("");
// Stable per-mount suffix so the prefilled default hostname doesn't churn on
// every render, and two servers ordered back-to-back don't collide.
const [hostSuffix] = useState(() => randHostSuffix());
// Flips true the instant the customer edits the hostname (or a cancelled-checkout
// draft is restored), after which the auto-prefill effect never touches it again.
const hostnameTouchedRef = useRef(false);
const [pubKey, setPubKey] = useState("");
const [free, setFree] = useState(false);
const [termMonths, setTermMonths] = useState(defaultTermMonths ?? VPS_TERMS[0].months);
// Apply the wallet balance by default whenever there's something to apply.
const [useWallet, setUseWallet] = useState(balanceCents > 0);
// Checkout promo code. `couponApplied` holds the server-verified discount so the
// displayed total matches what placeOrder charges; it is cleared whenever the
// selection changes (a "Starter only" code stops applying if they switch plans).
const [couponInput, setCouponInput] = useState("");
const [couponApplied, setCouponApplied] = useState<{ code: string; label: string; discountCents: number } | null>(null);
const [couponMsg, setCouponMsg] = useState("");
const [couponBusy, setCouponBusy] = useState(false);
// Set when we come back from a cancelled Stripe Checkout, so the banner can
// say what happened instead of leaving the customer on a silently reset form.
const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);

/**
 * Keep the customer's choices alive across the Stripe round-trip.
 *
 * Cancelling on Stripe's page hard-navigates back to
 * `/dashboard/deploy?canceled=1`, which remounts this component from scratch:
 * plan, image, add-ons, disk slider, hostname and term all gone. `?canceled=1`
 * was read by nothing, so there was no explanation either — the customer just
 * found an empty wizard and had to guess whether they had been charged.
 *
 * sessionStorage is per-tab and survives that navigation where `useState`
 * cannot. The draft is written on every change and read back ONLY on a
 * `?canceled=1` return, then deleted — a draft that reappeared on some later
 * visit would be its own surprise.
 *
 * No root password is drafted or submitted: provisioning always generates one
 * server-side and shows it on the server page. There is no field to preserve.
 */
useEffect(() => {
  let canceled = false;
  try {
    canceled = new URLSearchParams(window.location.search).get("canceled") === "1";
  } catch {
    /* no URL access — fall through as a normal mount */
  }
  if (!canceled) return;
  let d: Draft | null = null;
  try {
    const raw = sessionStorage.getItem(DRAFT_KEY);
    sessionStorage.removeItem(DRAFT_KEY);
    if (raw) d = JSON.parse(raw) as Draft;
  } catch {
    d = null;
  }
  setRestoredAfterCancel(true);
  if (!d) return;
  // Every id is re-checked against the props actually rendered: a plan can be
  // deactivated or an image retired while the customer is on Stripe's page, and
  // selecting an id that is no longer in the list would show a blank Review
  // step with no price on it.
  if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
  else if (d.customPlan && d.customPlan.id === d.planId) {
    // Not in `plans` (custom rows are inactive by design) — restore the object
    // itself, which the draft carried whole for exactly this reason.
    setCustomPlan(d.customPlan);
    setPlanId(d.customPlan.id);
  }
  if (nodes.some((n) => n.id === d.nodeId)) setNodeId(d.nodeId);
  if (images.some((i) => i.id === d.imageId)) setImageId(d.imageId);
  if (TABS.some((t) => t.key === d.tab)) setTab(d.tab);
  if (d.addons) setAddons({ malware: !!d.addons.malware, backup: !!d.addons.backup, docker: !!d.addons.docker });
  setDedicatedIp(!!d.dedicatedIp);
  if (Number.isFinite(d.extraDiskGB)) setExtraDiskGB(d.extraDiskGB);
  if (typeof d.hostname === "string" && d.hostname) {
    // A restored draft is the customer's own choice — treat it as touched so the
    // auto-prefill effect below never overwrites it.
    setHostname(d.hostname);
    hostnameTouchedRef.current = true;
  }
  if (typeof d.pubKey === "string") setPubKey(d.pubKey);
  if (VPS_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
  setUseWallet(!!d.useWallet && balanceCents > 0);
  if (Number.isInteger(d.step) && d.step >= 0 && d.step < steps.length) setStep(d.step);
  // Mount-only: this restores a one-shot draft and must never re-run.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

useEffect(() => {
  try {
    const draft: Draft = {
      step, planId, nodeId, imageId, tab, addons, dedicatedIp,
      extraDiskGB, hostname, pubKey, termMonths, useWallet, customPlan,
    };
    sessionStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
  } catch {
    /* storage disabled or full — the wizard still works, it just cannot
       survive the Stripe round-trip. Never break the order over this. */
  }
}, [step, planId, nodeId, imageId, tab, addons, dedicatedIp, extraDiskGB, hostname, pubKey, termMonths, useWallet, customPlan]);

// Prefer the confirmed custom plan when it's the one selected — it is never in
// `plans` (created inactive; see the `customPlan` state doc comment above).
const plan = (customPlan && customPlan.id === planId ? customPlan : undefined) ?? plans.find((p) => p.id === planId);
const image = images.find((i) => i.id === imageId);

/**
 * Custom-server builder — "Need something bigger? Build a custom server" below
 * the plan grid. Only rendered when the server resolved a floor (the current
 * Max plan); the live price is the EXACT pure formula lib/custom-plan.ts
 * re-validates server-side (lib/custom-plan-pricing.ts), so what the sliders
 * show as they move is never a guess. The capacity check, however, genuinely
 * requires the server (it reads committed RAM/disk across every live server),
 * so it's re-run — debounced — on every spec change and is the ONLY thing here
 * that round-trips.
 */
const openCustomBuilder = () => {
  if (!customPlanFloor) return;
  setCustomSpec((cur) => cur ?? { cpuCores: customPlanFloor.cpuCores, ramMB: customPlanFloor.ramMB, diskGB: customPlanFloor.diskGB });
  setCustomError("");
  setCustomBuilderOpen(true);
};
const customPreviewPrice =
  customSpec && customPlanFloor && customPlanRates
    ? computeCustomPlanPriceCents(customSpec, customPlanFloor, customPlanRates)
    : 0;
const customSpecValid =
  customSpec && customPlanFloor && customPlanCeiling
    ? validateCustomPlanSpec(customSpec, customPlanFloor, customPlanCeiling)
    : null;
useEffect(() => {
  if (!customBuilderOpen || !customSpec || !customSpecValid?.ok) {
    setCustomCapacity(null);
    return;
  }
  let cancelled = false;
  setCustomChecking(true);
  const t = setTimeout(async () => {
    try {
      const res = await quoteCustomPlanAction(customSpec);
      if (cancelled) return;
      if (!res.ok) setCustomCapacity({ ok: false, reason: res.error });
      else setCustomCapacity({ ok: !!res.capacityOk, reason: res.capacityReason });
    } catch {
      if (!cancelled) setCustomCapacity({ ok: false, reason: "Couldn't check capacity — try again." });
    } finally {
      if (!cancelled) setCustomChecking(false);
    }
