  return () => {
    cancelled = true;
    clearTimeout(t);
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [customBuilderOpen, customSpec?.cpuCores, customSpec?.ramMB, customSpec?.diskGB]);

async function confirmCustomBuilder() {
  if (!customSpec) return;
  setCustomError("");
  setCustomConfirming(true);
  try {
    const res = await confirmCustomPlanAction(customSpec);
    if (!res.ok || !res.plan) {
      setCustomError(res.error ?? "Couldn't set up that custom server.");
      return;
    }
    setCustomPlan(res.plan);
    setPlanId(res.plan.id);
    setCustomBuilderOpen(false);
  } finally {
    setCustomConfirming(false);
  }
}

/**
 * Prefill a friendly, always-valid hostname so the Access step never dead-ends a
 * first-timer on a disabled Continue button (the exact spot a real shopper
 * abandoned). It tracks the chosen image family until the customer edits the
 * field; the first keystroke flips `hostnameTouchedRef` and this effect stops
 * touching it, so a hand-typed name is never clobbered. Runs after the
 * cancelled-checkout restore effect above, which also sets the ref, so a restored
 * draft wins. `accessBlocker` is therefore null by default and the wizard flows.
 */
useEffect(() => {
  if (hostnameTouchedRef.current) return;
  setHostname(defaultHostnameFor(image, hostSuffix));
  // Intentionally keyed on image/suffix only; the ref guard (not a dep) protects
  // manual edits. setHostname is stable.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [image, hostSuffix]);

const activeTab = TABS.find((t) => t.key === tab) ?? TABS[0];

// Images in the active tab, filtered by search.
const tabImages = useMemo(() => {
  const needle = q.trim().toLowerCase();
  return images.filter(
    (i) => activeTab.match(i) && (needle === "" || (i.name + " " + i.version).toLowerCase().includes(needle)),
  );
}, [images, activeTab, q]);

// OS tab: group images into one card per family (each with its versions).
const osFamilies = useMemo<FamilyGroup[]>(() => {
  const map = new Map<string, FamilyGroup>();
  for (const i of tabImages) {
    const g = map.get(i.family) ?? { family: i.family, name: osFamilyName(i), logo: i.logo, versions: [] };
    g.versions.push(i);
    map.set(i.family, g);
  }
  for (const g of map.values()) g.versions.sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }));
  return [...map.values()];
}, [tabImages]);

const openFamily = (g: FamilyGroup) => {
  if (g.versions.length === 1) setImageId(g.versions[0].id);
  else setModalFamily(g.family);
};
const modalGroup = modalFamily ? osFamilies.find((g) => g.family === modalFamily) : undefined;

const hostnameValid = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(hostname) && hostname.length >= 3;
const planMeetsImage = !!plan && !!image && plan.ramMB >= image.minRamMB && plan.diskGB >= image.minDiskGB;
const ipMonthly = dedicatedIp ? dedicatedIpPriceCents ?? 0 : 0;
// Extra root disk: per-GB/month × GB, then × the term — priced exactly like the
// dedicated IP (no term discount, no promo), matching lib/order.ts orderQuote.
const extraDiskOffered = (extraDiskPriceCentsPerGb ?? 0) > 0;
const extraDiskMonthly = extraDiskCentsAt(extraDiskGB, extraDiskPriceCentsPerGb ?? 0);
const totalDiskGB = plan ? effectiveDiskGB(plan.diskGB, extraDiskGB) : 0;
// Paid backup retention: Plus is a flat monthly add-on (no term discount, no
// promo), priced over the term exactly like extra disk / dedicated IP.
const backupUpsellOffered = (backupPlusPriceCents ?? 0) > 0;
const backupMonthly = backupTier === "PLUS" ? backupPlusPriceCents ?? 0 : 0;

/**
 * What a term costs at the REGULAR rate — i.e. what a renewal of it will bill.
 * ONE definition, shared with the "Renew now" button on the server page and with
 * the action that charges it: `lib/renewal-quote.ts`.
 *
 * REAL INCIDENT (2026-07-26 rehearsal, H1): the term cards derived this
 * themselves and then printed the PROMO first-term total against the words
 * "billed every 1 yr" — "$67.96 billed every 1 yr" on a term that renews at
 * $97.09. `currentPromo()` never returns null (lib/promotions.ts always has an

 * $97.09. `currentPromo()` never returns null (lib/promotions.ts always has an
 * active sale), so the recurring figure on those cards was wrong on 100% of
 * orders. Renewals bill the regular price with no promo — promos are first-term
 * introductory offers — and they DO bill the add-ons, so this is the whole
 * basket at the regular rate, exactly as worker/billing.ts will charge it.
 */
// `gamePlan: null` is correct and not an oversight: this wizard sells plain VPS
// plans. Game servers are ordered through their own flow (lib/actions-gameplans.ts)
// at a flat all-in price and never reach these term cards.
const regularTermCents = (months: number) =>
  plan
    ? renewalQuote(
        {
          termMonths: months,
          extraDiskGB: extraDiskGB,
          plan: { name: plan.name, priceCents: plan.priceCents },
          gamePlan: null,
          dedicatedIp: dedicatedIp ? {} : null,
          backupTier: "FREE",
        },
        {
          ipMonthlyCents: dedicatedIpPriceCents ?? 0,
          extraDiskPerGbCents: extraDiskPriceCentsPerGb ?? 0,
          // The backup add-on is priced separately via addonTermCentsFor below,
          // so the plan term card prices FREE here to avoid double-counting.
          backupPlusCents: 0,
          // The Annual card prices against the LIVE admin discount, so what the
          // card shows for the 12-month term is exactly what checkout charges and
          // the renewal sweep bills.
          annualDiscountPct,
        },
      ).totalCents
    : 0;
/**
 * Effective per-month price of ANY plan at a given term — the plan's term total
 * (no add-ons) divided by the months. Priced through the SAME renewalQuote formula
 * checkout and the renewal sweep use, so the "/mo" shown on the Plan step === what is
 * charged. Used to make the Plan-step cards reflect the term the customer picks, so a
 * longer commitment visibly lowers the monthly number right where they choose the plan.
 */
const planMonthlyAtTerm = (planPriceCents: number, months: number) =>
  Math.round(
    renewalQuote(
      {
        termMonths: months,
        extraDiskGB: 0,
        plan: { name: "", priceCents: planPriceCents },
        gamePlan: null,
        dedicatedIp: null,
        backupTier: "FREE",
      },
      { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct },
    ).netCents / Math.max(1, months),
  );
/** Add-on portion of a term. Never promo-discounted, in the wizard or in checkout. */
const addonTermCentsFor = (months: number) => (ipMonthly + extraDiskMonthly + backupMonthly) * months;
/**
 * What the FIRST term costs — the promo applied to the plan portion only, then
 * the add-ons back at full price. Composed exactly as lib/order.ts orderQuote
 * composes `chargeCents`, and the plan portion is the regular total MINUS the
 * add-ons rather than a second derivation of the term price.
 */
const firstTermCents = (months: number) => {
  if (!plan) return 0;
  const addons = addonTermCentsFor(months);
  return promoCents(regularTermCents(months) - addons) + addons;
};

// Discount rate for the CURRENTLY selected term — hoisted to component scope
// (was previously computed only inside the Review step's now-conditionally-
// hidden billing-term summary) so the PaymentStep summary can show the same
// "Save X%" figure next to its own billing-term line.
const termDiscountPct = termMonths === ANNUAL_TERM_MONTHS ? annualDiscountPct : vpsTerm(termMonths).discountPct;

// A verified coupon discounts the first-term total. Clamped so it can never
// push the charge below zero. The server re-validates + claims at deploy.
const couponDiscount = couponApplied?.discountCents ?? 0;
// Net (pre-tax) charge, then VAT/GST on top (Finding 1). `dueCents` is the
// tax-INCLUSIVE total the wallet split and the Deploy button quote from, so the
// number shown === what payAndDeploy charges. Tax is 0 unless the customer has a
// billing country on file.
const netDueCents = free ? 0 : Math.max(0, firstTermCents(termMonths) - couponDiscount);
const taxCents = Math.round((netDueCents * taxRatePercent) / 100);
const dueCents = netDueCents + taxCents;
const regularDueCents = free ? 0 : regularTermCents(termMonths);

// A verified discount is only valid for the exact selection it was checked
// against — a "Starter only, 1 month" code stops applying the moment the
// customer switches plan or term. Drop it so the total can never show a
// discount the server would refuse.
useEffect(() => {
  setCouponApplied(null);
  setCouponMsg("");
}, [planId, termMonths, dedicatedIp, extraDiskGB]);

async function applyCoupon() {
  const code = couponInput.trim().toUpperCase();
  if (!code || !planId || !imageId) return;
  setCouponBusy(true);
  setCouponMsg("");
  try {
    const res = await previewOrderCoupon({ planId, osTemplateId: imageId, termMonths, dedicatedIp, extraDiskGB, couponCode: code });
    if (res.ok && res.discountCents) {
      setCouponApplied({ code, label: res.label ?? "Discount", discountCents: res.discountCents });
      setCouponMsg("");
    } else {
      setCouponApplied(null);
      setCouponMsg(res.error ?? "That code didn’t apply.");
    }
  } catch {
    setCouponApplied(null);
    setCouponMsg("Couldn’t check that code. Try again.");
  } finally {
    setCouponBusy(false);
  }
