// (payAndDeploy stamps the exact cardCents/quote it just computed onto the
// session — see lib/actions.ts). If the customer changes the wallet toggle or
// applies a coupon AFTER that session exists, its stamped amount is stale:
// drop it and let PaymentStep ask for a fresh one, rather than let them
// confirm a payment for the wrong total. The `checkoutSession` GUARD (not just
// a bare cardCents effect) means this never fires before a session exists in
// the first place, and `requestStripeSession` is what re-arms the request.
const prevCardCentsForStripeRef = useRef(cardCents);
useEffect(() => {
  if (checkoutSession && prevCardCentsForStripeRef.current !== cardCents) {
    setCheckoutSession(null);
    setStripePhase("idle");
  }
  prevCardCentsForStripeRef.current = cardCents;
}, [cardCents, checkoutSession]);

/**
 * Why the primary button is disabled, in words, on the step that can fix it.
 *
 * `canDeploy` folds four conditions into one silent boolean. The rehearsal hit
 * the consequence: skip the hostname — it sits between two fields explicitly
 * marked "optional" and carried no required marker — walk all the way to
 * Review, and the Deploy button is greyed out with nothing anywhere on the page
 * saying why, four steps from the cause.
 *
 * Two halves to the fix. Continue is now gated on the Access step, so you
 * cannot leave it in a state that dead-ends later; and both buttons name the
 * blocker AND the step that clears it.
 */
const accessBlocker = hostnameValid
  ? null
  : hostname.length === 0
    ? "Enter a hostname to continue — it is the name your server answers to, and we cannot create it without one."
    : "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.";
const installBlocker =
  !image
    ? "Choose an operating system, control panel or app to continue."
    : !planMeetsImage
      ? `${image.name} needs at least ${image.minRamMB / 1024} GB RAM and ${image.minDiskGB} GB disk. Go back to the Plan step and pick a larger plan.`
      : null;
const deployBlocker = !plan
  ? "Go back to the Plan step and choose a plan."
  : !image
    ? "Go back to the Install step and choose what to install."
    : !planMeetsImage
      ? installBlocker
      : accessBlocker
        ? `${accessBlocker} Use ← Back to return to the Access step.`
        : null;
const primaryBlocker = isLast
  ? deployBlocker
