    ? accessBlocker
    : curLabel === "Install"
      ? installBlocker
      : null;
// The embedded Payment step only ever replaces the button row for a genuinely
// deployable, card-funded order — never while something else still blocks the
// order (a missing hostname, an image too big for the plan), and never for a
// free/wallet-covered order, which has no payment method to choose.
const showPaymentStep = isLast && !free && !primaryBlocker && cardCents > 0;

return (
  <>
  <form
    ref={formRef}
    action={action}
    // The whole wizard is one form, so a stray Enter in a text field (e.g. the
    // hostname input) would implicitly submit it — deploying immediately with
    // the default term and skipping the Review step. Block implicit submission
    // everywhere except the final Review step; Enter still works in textareas
    // (the SSH-key field). Deploy only ever happens via the explicit button.
    onKeyDown={(e) => {
      if (e.key === "Enter" && (e.target as HTMLElement).tagName !== "TEXTAREA") {
