      */}
      {restoredAfterCancel && (
        <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">
          <span className="font-semibold text-white">Checkout cancelled — you weren&apos;t charged.</span>{" "}
          Your plan, image, add-ons, hostname and billing term are exactly as you left them.
        </div>
      )}

      {/*
        Reassurance framing (de-intimidation): everything on every step already has
        a sensible default, so a non-technical shopper can reach Deploy without
        typing anything. Says so up front, on-theme, once. Not shown on Review —
        real feedback was that "keep clicking Continue" reads as noise once the
        customer has actually arrived at the last step with nothing left to click
        through.
      */}
      {curLabel !== "Review" && (
        <p className="mb-5 rounded-lg border border-brand-400/20 bg-brand-500/[0.06] px-3 py-2 text-xs text-slate-300">

                  monthlyCents={plan.priceCents}
                  annualDiscountPct={annualDiscountPct}
                  value={termMonths}
                  onChange={(m) => {
