                  terms={VPS_TERMS}
                />
              </div>
            )}
            <PaymentStep
              email={email}
              onBack={() => setStep((s) => Math.max(0, s - 1))}
              stripe={
                checkoutSession
                  ? { status: "ready", clientSecret: checkoutSession.clientSecret, publishableKey: checkoutSession.publishableKey }
