                    ? { status: "loading" }
                    : stripePhase === "error"
                      ? { status: "error", message: state?.error || "We couldn't prepare card payment. Please try again." }
                      : { status: "idle" }
              }
              onRequestStripeSession={requestStripeSession}
              paypal={paypalReady ? { ready: true, clientId: paypalClientId } : null}
              createPayPalOrder={() => createOrderPayPalOrder(new FormData(formRef.current ?? undefined))}
              capturePayPalOrder={(orderId, pendingId) => captureExternalPayPalOrder(orderId, pendingId)}
              coinbaseReady={coinbaseReady}
              createCoinbaseCharge={() => createOrderCoinbaseCharge(new FormData(formRef.current ?? undefined))}
              summary={{
                lines: [
                  {
                    icon: (
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" className="h-5 w-5">
                        <rect x="3" y="4" width="18" height="7" rx="1.5" />
                        <rect x="3" y="13" width="18" height="7" rx="1.5" />
                        <path d="M7 7.5h.01M7 16.5h.01" />
