                  { k: "Add-ons", v: [addons.malware && "Malware scanner", addons.backup && "Daily backups", addons.docker && "Docker", dedicatedIp && "Dedicated IPv4"].filter(Boolean).join(", ") || "None" },
                  ...(backupTier === "PLUS" ? [{ k: "Backup retention", v: `Plus (keep 7) · ${money(backupMonthly)}/mo` }] : []),
                  ...(extraDiskGB > 0 ? [{ k: "Extra disk", v: `+${extraDiskGB} GB · ${money(extraDiskMonthly)}/mo` }] : []),
                  { k: "Hostname", v: hostname || "—" },
                ],
                billingTermLabel: VPS_TERMS.find((t) => t.months === termMonths)?.label ?? `${termMonths} month${termMonths === 1 ? "" : "s"}`,
                discountPercent: termDiscountPct,
                onChangeTerm: () => setShowTermPicker((v) => !v),
                promoExplainer: hasPromo ? (
                  <>
                    {promoLabel ? `${promoLabel}: ` : "First month free: "}first term free — you pay {money(dueCents)} today,
                    then {money(regularDueCents)} {termMonths === 1 ? "every month" : `every ${vpsTerm(termMonths).short}`} when
