                    {couponApplied && <p className="mt-1 text-xs text-emerald-300">✓ {couponApplied.label} applied</p>}
                    {couponMsg && <p className="mt-1 text-xs text-amber-300">{couponMsg}</p>}
                  </div>
                ),
                walletToggleSlot: balanceCents > 0 && (
                  <div className="flex items-center justify-between">
                    <label className="flex items-center gap-2 text-slate-300">
                      <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
                      Apply my balance ({money(balanceCents)})
                    </label>
                    <dt className="text-slate-500">{useWallet ? "applied" : "off"}</dt>
                  </div>
                ),
              }}
              // Real, admin-confirmed policy (30 days for VPS) — see the
              // HONESTY note on this prop in PaymentStep.tsx. Wizard-only for
              // now, not yet propagated to marketing pages.
              moneyBackDays={30}
            />
          </div>
        ) : (
          <div className="mt-6 flex items-center justify-between">
            <button type="button" className="btn-ghost" disabled={step === 0} onClick={() => setStep((s) => Math.max(0, s - 1))}>← Back</button>
            {/*
              The `key` on each branch is load-bearing, not decoration. Without it
              these two buttons occupy the same position in the tree and React
              reuses ONE DOM node for both — so advancing to the last step mutated
              the live Continue button into the Deploy button, dropping
              `type="button"` and turning it into a submit control while the click
              was still being processed. That charged customers four steps early.
              Distinct keys force a real unmount/mount, and both branches now state
              their `type` explicitly rather than relying on the HTML default.

              Only rendered when the sticky cart above ISN'T already showing its
              own Continue/Deploy button (i.e. `plan && !free`) — otherwise the
              customer saw two buttons doing the exact same thing (real user
              report). The sticky cart's button and this one call the identical
              handlers, so whichever one renders is the single source of truth.
            */}
            {!(plan && !free) && (!isLast ? (
              // Gated on the CURRENT step, not just Install. Leaving Access with an
              // empty hostname used to be allowed, and the customer only discovered
              // it four steps later on a Deploy button that would not light up.
              <button
                key="wizard-continue"
                type="button"
                className="btn-deploy"
                disabled={!!primaryBlocker}
                aria-describedby={primaryBlocker ? "wizard-blocker" : undefined}
                onClick={() => setStep((s) => s + 1)}
              >
                Continue <span className="dep-arrow">→</span>
              </button>
            ) : (
              <button
                key="wizard-deploy"
                type="submit"
                className="btn-deploy px-6"
                disabled={pending || !canDeploy}
                aria-describedby={deployBlocker ? "wizard-blocker" : undefined}
                onClick={() => { submittedRef.current = true; }}
              >
                {pending
                  ? "Deploying…"
                  : free
                    ? "Deploy free"
                    : cardCents > 0
                      ? `Deploy — ${money(cardCents)} on card`
                      : "Deploy — paid from wallet"}
              </button>
            ))}
          </div>
        )}
      </div>
    </form>
    <WizardReassuranceCard className="mt-6" moneyBackDays={30} moneyBackCaption="Try any plan risk-free" />
    </>
  );
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
  return (
