const stripeCache = new Map<string, Promise<StripeJs | null>>();
/** Exported so components/customer/AddFundsPaymentModal.tsx shares the SAME
 *  cached Stripe.js instance/appearance rather than re-deriving them — the
 *  wallet top-up's Custom Checkout must look and behave identically to this
 *  Payment step, not merely similarly. */
export function stripeFor(pk: string): Promise<StripeJs | null> {
  let p = stripeCache.get(pk);
  if (!p) {
    p = loadStripe(pk);
    stripeCache.set(pk, p);
  }
  return p;
}

/**
 * Shared appearance so the Payment Element reads as part of THIS page, not a
 * visiting Stripe widget — dark surfaces matching the wizard's card chrome.
 *
 * `fontFamily: "inherit"` looked like it would pick up the page's own Geist
 * typeface, but Elements render inside a cross-origin js.stripe.com iframe —
 * "inherit" resolves against THAT document, which has no ancestor font-family
 * of its own, so it fell through to the browser default serif (a real bug: it
 * rendered as a dated Times New Roman look, not Geist). `STRIPE_FONTS` loads
 * the actual typeface into the iframe via Stripe's documented `cssSrc` option
 * (the one way to add a custom font — same-origin @font-face rules on the
 * parent page are invisible to the iframe), and `fontFamily` below names it.
 */
export const STRIPE_FONTS = [{ cssSrc: "https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&display=swap" }];
export const STRIPE_APPEARANCE = {
  theme: "night" as const,
  variables: {
    colorPrimary: "#7c5cff",
    colorBackground: "#0b0f1f",
    colorText: "#e2e8f0",
    colorDanger: "#f87171",
    fontFamily: "'Geist', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif",
    borderRadius: "10px",
    spacingUnit: "4px",
  },
  rules: {
    ".Input": { border: "1px solid rgba(255,255,255,0.09)", boxShadow: "none" },
    ".Input:focus": { border: "1px solid rgba(124,92,255,0.6)", boxShadow: "0 0 0 1px rgba(124,92,255,0.4)" },
    ".Label": { color: "#94a3b8" },
  },
};

/** Renders inside `<CheckoutElementsProvider>` — the only place `useCheckout()` is valid. */
function CardAndWalletsBlock({
  selected,
  onSelectCard,
  saveCard,
  onToggleSaveCard,
  totalDueCents,
  saveCardExplainer,
}: {
  selected: Method;

  selected: Method;
  onSelectCard: () => void;
  saveCard: boolean;
  onToggleSaveCard: (v: boolean) => void;
  totalDueCents: number;
  saveCardExplainer: React.ReactNode;
}) {
  // useCheckoutElements() (not the deprecated useCheckout()) returns a
  // discriminated union — {type:"loading"} while the Elements SDK is still
  // initializing, {type:"error"} if it failed, {type:"success", checkout}
  // once ready. `checkoutActions` is that inner `checkout` object, undefined
  // until "success" — every confirm() call below is guarded on it existing,
  // so a click during the loading window can't throw.
  const checkoutState = useCheckoutElements();
  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [expressPayAvailable, setExpressPayAvailable] = useState(false);

  async function payWithCard() {
    if (!checkoutActions) return;
    setError(null);
    setConfirming(true);
    try {
      const result = await checkoutActions.confirm({ savePaymentMethod: saveCard });
      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another payment method.");
      // On success Stripe navigates the browser to the session's return_url
      // (/api/stripe/confirm) — the SAME route that fulfils every other Stripe
      // payment on this platform. Nothing else to do here.
    } catch {
      setError("Something went wrong confirming your payment. Please try again.");
    } finally {
      setConfirming(false);
    }
  }

  return (
    <>
      <MethodRow
        id="card"
        selected={selected === "card"}
        onSelect={onSelectCard}
        icon={<CardIcon />}
        title="Credit / Debit Card"
        subtitle="Visa, Mastercard, American Express and more"
      >
        <div className="space-y-4">
          <div>
            <label className="mb-1.5 flex items-center gap-1.5 text-xs font-medium text-slate-400">
              <LockIcon /> Card details
            </label>
            <div className="rounded-lg border border-white/[0.08] bg-white/[0.02] p-3">
              <PaymentElement
                options={{
                  layout: "tabs",
                  fields: { billingDetails: { name: "never" } },
                  paymentMethodOrder: ["card"],
                }}
              />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-xs font-medium text-slate-400">Cardholder name</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Name on card"
              className="w-full rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:border-brand-400/50 focus:outline-none"
            />
          </div>
          <label className="flex items-start gap-2.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
            <input type="checkbox" checked={saveCard} disabled className="mt-0.5 h-3.5 w-3.5 accent-brand-500" onChange={(e) => onToggleSaveCard(e.target.checked)} />
            <span className="text-xs text-slate-400">
              <span className="font-medium text-slate-300">Save card for faster checkout</span>
              <br />
              {saveCardExplainer}
            </span>
          </label>
          {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}
          <button
            type="button"
            onClick={payWithCard}
            disabled={confirming || !checkoutActions?.canConfirm}
            className="btn-deploy w-full py-3 text-sm"
          >
            <LockIcon className="h-4 w-4" />
            {confirming ? "Processing…" : `Pay Securely ${money(totalDueCents)}`}
            {!confirming && <span className="dep-arrow">→</span>}
          </button>
        </div>
      </MethodRow>

      {/*
        ONE ExpressCheckoutElement, always mounted, showing whichever wallets
        the browser/device actually supports (Stripe renders them side by
        side itself). This used to be TWO separate elements — one per wallet,
        each shown only when its own MethodRow was the "selected" radio
        option — which looked static (nothing to click until you clicked the
        row first) and, worse, having both mount at once (needed to fix the
        static look) throws Stripe's own "cannot create multiple instances of
        the Express Checkout Element" error. A single instance covering both
        wallets is Stripe's actual supported shape for this. Hidden entirely
        (via onReady's availablePaymentMethods) when NEITHER wallet is
        available on this browser/device/card.
      */}
      {/* Always mounted (never conditionally unmounted) so onReady gets a
          chance to fire at all — only its VISIBILITY is gated on the result,
          via a CSS class rather than removing it from the tree. */}
      <div className={expressPayAvailable ? "rounded-xl border border-white/[0.07] bg-white/[0.02] p-4" : "hidden"}>
          <p className="mb-3 text-xs font-medium text-slate-400">Express checkout</p>
          <ExpressCheckoutElement
            options={{
              // The /checkout subpath's ExpressCheckoutElementOptions requires
              // every key present (unlike the main package's), even though
              // Stripe treats undefined the same as omitted for each of these.
              buttonHeight: undefined,
              buttonTheme: undefined,
              buttonType: undefined,
              layout: undefined,
              paymentMethodOrder: undefined,
              paymentMethods: { googlePay: "auto", applePay: "auto", link: "never", paypal: "never", amazonPay: "never" },
            }}
            onReady={(e) =>
              setExpressPayAvailable(!!(e.availablePaymentMethods?.googlePay || e.availablePaymentMethods?.applePay))
            }
            // The Custom Checkout version of this element does not expose
            // onClick (Stripe's SDK owns opening the OS payment sheet
            // entirely).
            onConfirm={async (event) => {
              if (!checkoutActions) return;
              setError(null);
              const result = await checkoutActions.confirm({ expressCheckoutConfirmEvent: event });
              if (result.type === "error") setError(result.error.message ?? "Payment failed.");
            }}
          />
      </div>
    </>
  );
}

