const DEFAULT_SAVE_CARD_EXPLAINER =
  "Nxeon plans renew automatically, so your card is always saved securely with Stripe for your next billing cycle — this isn't optional for a subscription product, which is why the box is checked.";

export function PaymentStep(props: PaymentStepProps) {
  const { summary, stripe, onRequestStripeSession, paypal, coinbaseReady } = props;
  const [method, setMethod] = useState<Method>("card");
  const [saveCard, setSaveCard] = useState(true);
  const email = props.email;
  const [payPalPendingId, setPayPalPendingId] = useState<string | null>(null);
  const [payPalError, setPayPalError] = useState<string | null>(null);
  const [coinbaseBusy, setCoinbaseBusy] = useState(false);
  const [coinbaseError, setCoinbaseError] = useState<string | null>(null);
  // Ask for a Stripe session as soon as this step is visible, so Card/Google
  // Pay/Apple Pay are ready to accept input immediately (matching the mockup)
  // instead of only appearing after a click. `stripe.status` is entirely
  // PARENT-controlled: the wizard flips it away from "idle" the instant it acts
