import { db } from "./db";
import { sendMail } from "./mailer";
import { emails } from "./email-templates";
import { appUrl } from "./email-render";
import { GAME_DISPLAY, GAME_PORT, type GameFamily } from "./games";

/**
 * Deployment-confirmation email helper.
 *
 * Sends the "your server is ready" email once a server is provisioned and
 * reachable, from BOTH the provision success path (worker) and the admin
 * "reconcile from Proxmox" recovery. It is deliberately:
 *
 *  - TRANSACTIONAL: sent with the CRITICAL `provision_ready` kind so a customer
 *    preference can never suppress it (see lib/prefs.ts).
 *  - DEDUPED via `EmailLog`: `EmailLog` has no `serverId` column and we add no
 *    schema, so the dedupe keys on the template tag + the customer + the
 *    server-unique dashboard path that the rendered HTML always contains. Only
 *    a prior SENT row blocks a resend, so a failed attempt can still be retried
 *    on the next reconcile/provision.
 *  - BEST-EFFORT: it runs on the provision money-path, so it swallows every
 *    error and NEVER throws into the caller.
 */

const DEPLOY_TEMPLATE = "server_deployed";

type DeployedServer = {
  id: string;
  hostname: string;
  sshPort: number | null;
  userId: string;
  gamePlanId?: string | null;
  plan?: { name?: string | null } | null;
  node?: { publicIp?: string | null } | null;
  osTemplate?: { family?: string | null } | null;
  portForwards?: { publicPort: number; guestPort: number }[];
  dedicatedIp?: { address: string } | null;
};

type DeployedUser = { email?: string | null } | null | undefined;

export async function sendServerDeployedEmail(
  server: DeployedServer,
  user: DeployedUser
): Promise<void> {
  try {
    const email = user?.email;
    if (!email) return;

    const dashboardUrl = `${appUrl()}/dashboard/servers/${server.id}`;

    // Per-server dedupe (see file header). The dashboard path is server-unique
    // and survives EmailLog redaction (only secret query params are stripped).
    const already = await db.emailLog.findFirst({
      where: {
        template: DEPLOY_TEMPLATE,
        userId: server.userId,
        status: "SENT",
        html: { contains: `/dashboard/servers/${server.id}` },
      },
      select: { id: true },
    });
    if (already) return;

    // ALWAYS the node's public IP + forwarded ssh port — never the internal
    // 10.20.x.x address, which is unreachable from outside the host.
    const host = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
    const sshEndpoint = server.sshPort ? `${host}:${server.sshPort}` : host;

    const isGame = !!server.gamePlanId;
    const family = server.osTemplate?.family as GameFamily | undefined;
    const gameEntry = family && family in GAME_DISPLAY ? GAME_DISPLAY[family] : null;
    const gamePort = family && (GAME_PORT as Record<string, { port: number }>)[family];

    let gameConnect: string | undefined;
    if (isGame && gamePort) {
      const dedIp = server.dedicatedIp ?? await db.dedicatedIp.findFirst({ where: { serverId: server.id }, select: { address: true } });
      if (dedIp) {
        gameConnect = `${dedIp.address}:${gamePort.port}`;
      } else {
        const fwds = server.portForwards ?? await db.portForward.findMany({ where: { serverId: server.id }, select: { publicPort: true, guestPort: true } });
        const fwd = fwds.find((f) => f.guestPort === gamePort.port);
        if (fwd) gameConnect = `${host}:${fwd.publicPort}`;
      }
    }

    const tpl = emails.serverDeployed({
      hostname: server.hostname,
      planName: server.plan?.name ?? "Nxeon",
      sshEndpoint,
      dashboardUrl,
      gameLabel: isGame && gameEntry ? gameEntry.name : undefined,
      gameConnect,
    });

    await sendMail({
      to: email,
      subject: tpl.subject,
      html: tpl.html,
      // Records EmailLog.template = "server_deployed" — the dedupe key above.
      template: tpl.template,
      userId: server.userId,
      // CRITICAL kind → non-suppressible transactional delivery.
      kind: "provision_ready",
    });
  } catch (e) {
    console.error("[server-deployed-email] send failed (non-fatal)", e);
  }
}

// Client-side deploy-funnel beacons. Dependency-free (no server imports) so it is
// safe to pull into the customer wizard client components. Fires fire-and-forget
// POSTs to /api/track/deploy-step; never throws, never blocks the wizard.

export type DeployProduct = "vps" | "game" | "hosting" | "email";

/** Read the per-tab session id the VisitTracker maintains, so a funnel event can
 *  be tied to the same session as the pageviews. */
function sessionId(): string | null {
  try {
    return window.sessionStorage.getItem("nx_sid");
  } catch {
    return null;
  }
}

function send(payload: Record<string, unknown>): void {
  try {
    const body = JSON.stringify({ ...payload, sessionId: sessionId() });
    if (typeof navigator !== "undefined" && navigator.sendBeacon) {
      navigator.sendBeacon("/api/track/deploy-step", new Blob([body], { type: "application/json" }));
    } else {
      fetch("/api/track/deploy-step", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
        keepalive: true,
      }).catch(() => {});
    }
  } catch {
    /* best-effort */
  }
}

/**
 * Record that the user REACHED a wizard step. De-duped per tab-session so a
 * component re-render / strict-mode double-mount doesn't count a step twice — the
 * funnel measures distinct sessions reaching each step.
 */
export function trackDeployStep(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfstep:${product}:${stepIndex}:${step}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* storage disabled — still emit, just without cross-render dedupe */
  }
  send({ product, step, stepIndex, type: "step" });
}

/**
 * Record that a wizard step FAILED (a validation error, or an API/provision call
 * that returned/raised an error). NOT de-duped — every real failure is a signal.
 */
export function trackDeployError(
  product: DeployProduct,
  step: string,
  stepIndex: number,
  errorCode: string,
  errorMessage?: string,
): void {
  if (typeof window === "undefined") return;
  send({ product, step, stepIndex, type: "error", errorCode, errorMessage: errorMessage ?? null });
}

/** Record that the deploy SUCCEEDED (bottom of the funnel). De-duped per session. */
export function trackDeployComplete(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfdone:${product}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* ignore */
  }
  send({ product, step, stepIndex, type: "complete" });
}
