  for (const f of schema.fields) out[f.key] = f.default;
  return out;
}

/**
 * A proper multi-step game-server deploy wizard — the game analogue of the VPS
 * DeployWizard. Steps: Game → Plan & term → Server settings → Review & checkout.
 *
 * TRUTH BY CONSTRUCTION: every price is derived from the tier's real DB price
 * (`priceCents`) run through `termPriceCents` with the SAME live `annualDiscountPct`
 * the server charges and renews at, and the wallet/card split is the same
 * `walletSplit` math the action charges. So what the customer sees === what
 * `payAndDeployGame` charges. Game bills FULL from month 1 — no first-month-free.
 */
export function GameDeployWizard({
  games,
  tiers,
  balanceCents,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
  schemas,
  stripeConfigured,
  email,
  dedicatedIpAvailable = false,
  dedicatedIpPriceCents = 0,
  customPlanFloor, customPlanCeiling, customPlanRates,
}: {
  games: GameMeta[];
  tiers: Tier[];
  balanceCents: number;
  annualDiscountPct?: number;
  /** family → per-game customization schema (only families that have one). */
  schemas: Record<string, FamilySchema>;
  /** Whether card checkout is available (else wallet-only). */
  stripeConfigured: boolean;
  /** The account's email — PaymentStep's receipt/invoice-email display. */
  email: string;
  /** Whether the dedicated-IP pool has free IPs to offer. */
  dedicatedIpAvailable?: boolean;
  /** Admin-configured monthly price for a dedicated IP (cents). */
  dedicatedIpPriceCents?: number;
  /** "Build a custom server" — same floor/ceiling/rates resolved server-side for
   *  the VPS wizard (lib/custom-plan.ts), shared here so a game customer past the
   *  top of a family's tier ladder gets identical guardrails/pricing. See
   *  components/customer/DeployWizard.tsx's matching props for the full doc. */
  customPlanFloor?: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number; bandwidthTB: number };
  customPlanCeiling?: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
  customPlanRates?: { perVcpuCents: number; perRamGbCents: number; perDiskGbCents: number };
}) {
  const [state, action, pending] = useActionState(
    payAndDeployGame,
    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
  );
  // The embedded Stripe session to feed PaymentStep (was: a StripeCheckoutModal).
  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  // Tracks the Payment step's OWN session request — mirrors DeployWizard's
  // stripePhase/checkoutSession split.
  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");

  // Only accept a session as the result of an EXPLICIT submit (armed in
  // requestStripeSession/the Deploy button), so a stale session can never
  // apply on its own (e.g. after a back-button remount).
  const submittedRef = useRef(false);
  useEffect(() => {
    if (submittedRef.current) {
      submittedRef.current = false;
      if (state?.checkout) {
        // The "game" conversion is fired at FULFILMENT (PurchaseTracker, with the real
        // charged value + transaction_id) — NOT here at checkout-start, which would
        // count customers who abandon at the payment step.
        setCheckoutSession(state.checkout);
      } else {
        setCheckoutSession(null);
        if (state?.error) setStripePhase("error");
      }
    }
  }, [state]);
  // PaymentStep asks for a session the SAME way the old "Deploy" button did — a
  // real requestSubmit() through the exact same <form action={action}>.
  const formRef = useRef<HTMLFormElement>(null);
  const requestStripeSession = useCallback(() => {
    setStripePhase("loading");
    submittedRef.current = true;
    formRef.current?.requestSubmit();

  formRef.current?.requestSubmit();
}, []);
// PaymentStep's PayPal/Coinbase support isn't wired for game servers yet —
// these stubs are never invoked since `paypal`/`coinbaseReady` are both off.
const gamePaymentUnavailable = useCallback(async () => ({ error: "That payment method isn't available for game servers yet." }), []);

const steps = ["Game", "Plan", "Settings", "Review"];
const [step, setStep] = useState(0);

// Deploy-funnel instrumentation (see DeployWizard for the rationale).
useEffect(() => {
  trackDeployStep("game", steps[step] ?? String(step), step);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [step]);
useEffect(() => {
  if (state?.error) trackDeployError("game", steps[step] ?? "Review", step, "ORDER_ERROR", state.error);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [state?.error]);

// DISPLAY-ONLY price formatter. USD renders byte-for-byte as before; any other
// selected display currency converts the USD-cents amount for on-screen reference
// only. Everything posted to payAndDeployGame stays USD cents (hidden fields carry
// selections, not money).
const { currency, rate } = useCurrency();
const money = (c: number) =>
  currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);

const firstGame = games[0]?.family ?? "";
const [game, setGame] = useState(firstGame);
const [selected, setSelected] = useState<string | null>(null);
const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
const [serverName, setServerName] = useState("");
const [hostname, setHostname] = useState("");
// `game` above defaults straight to `firstGame` rather than going through
// `pickGame()` (the function that ALSO seeds variant/values) — so these two
// need the SAME lazy-initializer logic, or a customer who never re-clicks
// the pre-selected game (the common case — Minecraft is `firstGame`) ships
// through Settings/Review with `values` stuck at `{}` the whole time. That
// produced a real, reported bug: the Review step's "Configuration" line
// read every field as changed-from-default and printed literal "undefined"
// for each one, because `values[f.key]` really was undefined — schema
// defaults were never actually applied to state, only ever displayed via
// the Settings step's `value ?? field.default` fallback.
const [variant, setVariant] = useState(schemas[firstGame]?.defaultVariant ?? "");
// Minecraft only — `<subdomain>.play.nxeon.cloud`, how players actually
// connect (see lib/game-subdomain.ts). Required at checkout for this family.
const [subdomain, setSubdomain] = useState("");
const [values, setValues] = useState<Values>(defaultValues(schemas[firstGame] ?? null));
const [dedicatedIp, setDedicatedIp] = useState(false);
const [useWallet, setUseWallet] = useState(balanceCents > 0);
const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);
// Clicking "Change" next to the billing term inside PaymentStep's Order
// Summary reveals the same TermLadder cards inline instead of navigating
// away from the last step — mirrors DeployWizard's showTermPicker pattern.
const [showTermPicker, setShowTermPicker] = useState(false);

// Game-picker (Step 1) controls — presentation-only, never posted to the action.
const [gameQuery, setGameQuery] = useState("");
const [gameCategory, setGameCategory] = useState("All");
const [gameSort, setGameSort] = useState<"featured" | "name" | "price">("featured");

// "Build a custom server" — a confirmed custom GamePlan tier (real Plan +
// GamePlan rows, both created inactive; see lib/custom-plan.ts
// createCustomGamePlan) is never in the server-fetched `tiers` prop, so it's
// merged in here exactly like DeployWizard merges its own `customPlan`.
const [customTier, setCustomTier] = useState<Tier | null>(null);
const [customBuilderOpen, setCustomBuilderOpen] = useState(false);
const [customSpec, setCustomSpec] = useState<CustomPlanSpec | null>(null);
const [customPlayers, setCustomPlayers] = useState<number | null>(null);
const [customCapacity, setCustomCapacity] = useState<{ ok: boolean; reason?: string } | null>(null);
const [customChecking, setCustomChecking] = useState(false);
const [customConfirming, setCustomConfirming] = useState(false);
const [customError, setCustomError] = useState("");

const gameTiers = useMemo(() => {
  const base = tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents);
  return customTier && customTier.gameFamily === game ? [...base, customTier] : base;
}, [tiers, game, customTier]);
const chosen = gameTiers.find((t) => t.id === selected) ?? null;
const schema = schemas[game] ?? null;

/**
 * Custom-server builder for game orders — mirrors DeployWizard's, plus a
 * "how many players?" convenience slider (lib/game-player-recommend.ts) that
 * DEFAULT-SETS the same underlying cpu/ram/disk sliders; the customer can still
 * freely override above or below whatever it suggests.
 */
const openCustomBuilder = () => {
  if (!customPlanFloor) return;
  setCustomSpec((cur) => cur ?? { cpuCores: customPlanFloor.cpuCores, ramMB: customPlanFloor.ramMB, diskGB: customPlanFloor.diskGB });
  setCustomError("");
  setCustomBuilderOpen(true);
};
const applyPlayerRecommendation = (players: number) => {
  setCustomPlayers(players);
  if (!customPlanFloor || !customPlanCeiling) return;
  const rec = recommendedSpecForPlayers(game as GameFamily, players);
  setCustomSpec(clampCustomPlanSpec(rec, customPlanFloor, customPlanCeiling));
};
const customPreviewPrice =
  customSpec && customPlanFloor && customPlanRates
    ? computeCustomPlanPriceCents(customSpec, customPlanFloor, customPlanRates)
    : 0;
const customSpecValid =
  customSpec && customPlanFloor && customPlanCeiling
    ? validateCustomPlanSpec(customSpec, customPlanFloor, customPlanCeiling)
    : null;
useEffect(() => {
  if (!customBuilderOpen || !customSpec || !customSpecValid?.ok) {
    setCustomCapacity(null);
    return;
  }
  let cancelled = false;
  setCustomChecking(true);
  const t = setTimeout(async () => {
    try {
      const res = await quoteCustomPlanAction(customSpec);
      if (cancelled) return;
      if (!res.ok) setCustomCapacity({ ok: false, reason: res.error });
      else setCustomCapacity({ ok: !!res.capacityOk, reason: res.capacityReason });
    } catch {
      if (!cancelled) setCustomCapacity({ ok: false, reason: "Couldn't check capacity — try again." });
    } finally {
      if (!cancelled) setCustomChecking(false);
    }
  }, 450);
  return () => {
    cancelled = true;
    clearTimeout(t);
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [customBuilderOpen, customSpec?.cpuCores, customSpec?.ramMB, customSpec?.diskGB]);

async function confirmCustomBuilder() {
  if (!customSpec) return;
  setCustomError("");
  setCustomConfirming(true);
  try {
    const res = await confirmCustomGamePlanAction({
      cpuCores: customSpec.cpuCores,
      ramMB: customSpec.ramMB,
      diskGB: customSpec.diskGB,
      gameFamily: game,
      players: customPlayers ?? undefined,
    });
    if (!res.ok || !res.tier) {
      setCustomError(res.error ?? "Couldn't set up that custom server.");
      return;
    }
    const t = res.tier;
    const newTier: Tier = {
      id: t.gamePlanId,
      gameFamily: game,
      name: t.name,
      ramMB: t.ramMB,
      cpuCores: t.cpuCores,
      diskGB: t.diskGB,
      slots: t.slots,
      priceCents: t.priceCents,
      termMonths: t.termMonths,
      featured: false,
    };
    setCustomTier(newTier);
    setSelected(newTier.id);
    setCustomBuilderOpen(false);
  } finally {
    setCustomConfirming(false);
  }
}

// Cheapest monthly price per family — powers the "from $X/mo" badge + price sort.
const fromMonthlyByFamily = useMemo(() => {
  const m: Record<string, number> = {};
  for (const t of tiers) {
    const mo = Math.round(t.priceCents / Math.max(1, t.termMonths));
    if (m[t.gameFamily] === undefined || mo < m[t.gameFamily]) m[t.gameFamily] = mo;
  }
  return m;
}, [tiers]);
const featuredFamilies = useMemo(
  () => new Set(tiers.filter((t) => t.featured).map((t) => t.gameFamily)),
  [tiers],
);
const tierCountByFamily = useMemo(() => {
  const m: Record<string, number> = {};
  for (const t of tiers) m[t.gameFamily] = (m[t.gameFamily] ?? 0) + 1;
  return m;
}, [tiers]);
// Only surface category pills for genres that actually have games available.
const gameCategories = useMemo(() => {
  const set = new Set<string>();
  for (const g of games) set.add(GAME_GENRE[g.family] ?? "Other");
  return ["All", ...[...set].sort()];
}, [games]);
const visibleGames = useMemo(() => {
  const q = gameQuery.trim().toLowerCase();
  const list = games.filter((g) => {
    if (gameCategory !== "All" && (GAME_GENRE[g.family] ?? "Other") !== gameCategory) return false;
    if (q && !g.name.toLowerCase().includes(q) && !g.family.includes(q)) return false;
    return true;
  });
  const sorted = [...list];
  if (gameSort === "name") sorted.sort((a, b) => a.name.localeCompare(b.name));
  else if (gameSort === "price")
    sorted.sort(
      (a, b) => (fromMonthlyByFamily[a.family] ?? Infinity) - (fromMonthlyByFamily[b.family] ?? Infinity),
    );
  else
    sorted.sort(
      (a, b) => (featuredFamilies.has(b.family) ? 1 : 0) - (featuredFamilies.has(a.family) ? 1 : 0),
    );
  return sorted;
}, [games, gameQuery, gameCategory, gameSort, fromMonthlyByFamily, featuredFamilies]);

// Grid scale guard — the full filtered/sorted list can legitimately run past
// 30 tiles once every planned game lands (a single "Survival" category alone
// will hold well over a dozen). Rather than pagination (extra state, back-
// button complexity) or virtualization (unneeded at this size), cap the
// initial render and let a "Show all" button reveal the rest — a plain,
// reversible expand that costs nothing when the list is already short (at
// today's ~24 games most categories never even hit the cap).
const GRID_INITIAL_COUNT = 12;
const [showAllGames, setShowAllGames] = useState(false);
useEffect(() => {
  setShowAllGames(false);
}, [gameQuery, gameCategory, gameSort]);
const displayedGames = showAllGames ? visibleGames : visibleGames.slice(0, GRID_INITIAL_COUNT);

// When the game changes, reset the tier + per-game setup to that game's defaults.
function pickGame(family: string) {
  setGame(family);
  setSelected(null);
  const s = schemas[family] ?? null;
  setVariant(s?.defaultVariant ?? "");
  setValues(defaultValues(s));
  // A game choice is a single, unambiguous click (unlike Plan, which benefits
  // from comparing tiers side by side) — advance straight to Plan instead of
  // making the customer click the game card AND then a separate Next button.
  // The Back button (disabled only on step 0) still lets them change their mind.
  setStep(1);
}

// Restore a cancelled-checkout draft (Stripe cancel → /dashboard/games?canceled=1).
useEffect(() => {
  let canceled = false;
  try {
    canceled = new URLSearchParams(window.location.search).get("canceled") === "1";
  } catch {
    /* no URL access */
  }
  if (!canceled) return;
  setRestoredAfterCancel(true);
  let d: any = null;
  try {
    const raw = sessionStorage.getItem(DRAFT_KEY);
    sessionStorage.removeItem(DRAFT_KEY);
    if (raw) d = JSON.parse(raw);
  } catch {
    d = null;
  }
  if (!d) return;
  // Re-check every id against the props actually rendered — a tier can be retired
  // while the customer is on Stripe's page.
  if (typeof d.game === "string" && games.some((g) => g.family === d.game)) setGame(d.game);
  if (typeof d.selected === "string" && tiers.some((t) => t.id === d.selected)) setSelected(d.selected);
  // A confirmed custom tier is never in the server-fetched `tiers` prop (its
  // Plan/GamePlan rows are created inactive) — see the `customTier` state doc
  // comment above — so the draft carries the object itself.
  else if (d.customTier && d.customTier.id === d.selected) {
    setCustomTier(d.customTier);
    setSelected(d.customTier.id);
  }
  if (PRODUCT_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
  if (typeof d.serverName === "string") setServerName(d.serverName);
  if (typeof d.hostname === "string") setHostname(d.hostname);
  if (typeof d.variant === "string") setVariant(d.variant);
  if (typeof d.subdomain === "string") setSubdomain(d.subdomain);
  if (d.values && typeof d.values === "object") setValues(d.values);
  if (typeof d.dedicatedIp === "boolean") setDedicatedIp(d.dedicatedIp && dedicatedIpAvailable);
  if (typeof d.useWallet === "boolean") setUseWallet(d.useWallet && balanceCents > 0);
  if (Number.isInteger(d.step) && d.step >= 0 && d.step < steps.length) setStep(d.step);

  if (Number.isInteger(d.step) && d.step >= 0 && d.step < steps.length) setStep(d.step);
  // Mount-only: restores a one-shot draft.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

// Persist the draft on every change so it survives the Stripe round-trip.
useEffect(() => {
  try {
    sessionStorage.setItem(
      DRAFT_KEY,
      JSON.stringify({ step, game, selected, termMonths, serverName, hostname, variant, subdomain, dedicatedIp, values, useWallet, customTier }),
    );
  } catch {
    /* storage disabled — the wizard still works */
  }
}, [step, game, selected, termMonths, serverName, hostname, variant, subdomain, dedicatedIp, values, useWallet, customTier]);

// Pricing — identical math to lib/game-order.ts gameOrderQuote, so displayed === charged.
const monthlyCents = chosen ? Math.round(chosen.priceCents / Math.max(1, chosen.termMonths)) : 0;
const ipMonthly = dedicatedIp ? (dedicatedIpPriceCents ?? 0) : 0;
const ipTermCents = ipMonthly * termMonths;
const chargeCents = chosen ? termPriceCents(monthlyCents, termMonths, annualDiscountPct) + ipTermCents : 0;
const dueCents = chargeCents;
// Same rate the charge above was computed with — shown next to the billing
// term as a "Save X%" badge (DeployWizard's termDiscountPct pattern).
const discountPercent = termDiscountPct(termMonths, annualDiscountPct);
const split = walletSplit({ dueCents, balanceCents, useWallet });
const walletApplied = split.walletApplied;
const cardCents = split.cardCents;

// A Custom Checkout session is priced at the moment it's created. If the
// customer flips "Apply my balance" AFTER one exists, its stamped amount is
// stale — drop it so PaymentStep asks for a fresh one. Same guard as the
// other wizards.
const prevCardCentsRef = useRef(cardCents);
useEffect(() => {
  if (checkoutSession && prevCardCentsRef.current !== cardCents) {
    setCheckoutSession(null);
    setStripePhase("idle");
  }
  prevCardCentsRef.current = cardCents;
}, [cardCents, checkoutSession]);

const hostnameValid = hostname === "" || (hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname));
// Minecraft only — required (unlike hostname, which is optional/auto-generated),
// since there's no sensible auto-generated default a customer would recognize
// as "theirs" the way an auto hostname can be.
const subdomainValid = game !== "minecraft" || (subdomain !== "" && validateSubdomainFormat(subdomain) === null);
// A card leg with no Stripe configured can't settle — the customer must apply
// enough wallet balance to cover the whole charge.
const cardBlocked = cardCents > 0 && !stripeConfigured;

// Required per-game fields (e.g. DST's Klei cluster TOKEN — the server literally
// cannot start without it, see lib/game-config.ts's ConfigField.required) must be
// filled in before checkout, not discovered as a dead server after payment.
// Mirrors validateConfig's own server-side enforcement (lib/game-order.ts runs it
// before the Stripe session is ever created) so the customer sees this blocker
// here first, client-side, instead of a round-trip error at Review.
const missingRequiredField = schema?.fields.find(
  (f) => f.required && String(values[f.key] ?? f.default ?? "").trim() === "",
);

const curLabel = steps[step];
const isLast = step === steps.length - 1;

// Per-step gating with a plain-language blocker (mirrors DeployWizard).
const planBlocker = !chosen ? "Choose a plan to continue." : null;
const settingsBlocker = !hostnameValid
  ? "Hostname must be 3–40 characters, using only letters, digits and hyphens (or leave it blank and we'll name it)."
  : !subdomainValid
    ? "Pick a subdomain: 3-20 lowercase letters, numbers, or hyphens, not a reserved word."
    : missingRequiredField
      ? `${missingRequiredField.label} is required — see the note below the field.`
      : null;
const deployBlocker = !chosen
  ? "Go back to the Plan step and choose a plan."
  : !hostnameValid
    ? "Fix the hostname on the Settings step."
    : !subdomainValid
      ? "Pick a subdomain on the Settings step."
      : missingRequiredField
        ? `${missingRequiredField.label} is required — fill it in on the Settings step.`
        : cardBlocked
          ? "Card checkout isn't set up — apply enough wallet balance to cover the total, or top up your wallet."
          : null;
// A card leg is due at Review — PaymentStep mounts instead of the plain
// fallback, same condition VPS/Hosting/Email use.
const showPaymentStep = isLast && !deployBlocker && cardCents > 0;
const primaryBlocker = isLast
  ? deployBlocker
  : curLabel === "Plan"
    ? planBlocker
    : curLabel === "Settings"
      ? settingsBlocker
      : null;

const canDeploy = !!chosen && hostnameValid && subdomainValid && !missingRequiredField && !cardBlocked;

function setField(key: string, v: string | number | boolean) {
  setValues((cur) => ({ ...cur, [key]: v }));
}

// Shared tile markup for both the "Popular" rail and the main grid, so the
// two never drift apart visually — this is purely about WHERE a tile is
// shown, never a second copy of what it looks like. The individual cover
// card design itself is untouched from before this change.
//
// Deliberately a plain function returning JSX (called as `renderGameTile(g)`),
// NOT a nested component invoked as `<GameTile g={g} />` — a function
// component declared inside another component's body gets a fresh identity
// every render, so React would treat it as a different component type on
// every keystroke in the search box and remount the whole tile subtree,
// including GameCoverTile's internal image-fallback state (flashing back to
// the first candidate in its onError chain instead of staying on whichever
// image already loaded).
function renderGameTile(g: GameMeta) {
  const active = g.family === game;
  const count = tierCountByFamily[g.family] ?? 0;
  const from = fromMonthlyByFamily[g.family];
  const featured = featuredFamilies.has(g.family);
  const isNew = NEW_GAME_FAMILIES.has(g.family);
  return (
    <button
      type="button"
      key={g.family}
      onClick={() => pickGame(g.family)}
      aria-pressed={active}
      className={`group relative overflow-hidden rounded-2xl border text-left transition duration-200 ${
        active
          ? "border-brand-400 ring-2 ring-brand-400/40 shadow-[0_0_45px_-12px_rgba(111,71,245,0.65)]"
          : "border-white/[0.08] hover:-translate-y-0.5 hover:border-white/25 hover:shadow-[0_16px_36px_-20px_rgba(0,0,0,0.85)]"
      }`}
    >
      <GameCoverTile family={g.family} name={g.name} />
      {featured ? (
        <span className="absolute left-2 top-2 rounded-full border border-white/20 bg-black/50 px-2 py-0.5 text-[10px] font-semibold text-white backdrop-blur">
          Popular
        </span>
      ) : isNew ? (
        <span className="absolute left-2 top-2 rounded-full border border-emerald-400/40 bg-emerald-500/80 px-2 py-0.5 text-[10px] font-semibold text-white backdrop-blur">
          New
        </span>
      ) : null}
      {active && (
        <span className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-brand-500 text-xs text-white shadow-lg ring-2 ring-navy-950/70">
          ✓
        </span>
      )}
      <div className="pointer-events-none absolute inset-x-0 bottom-0 p-3">
        <div className="truncate text-sm font-semibold text-white drop-shadow">{g.name}</div>
        <div className="mt-0.5 flex items-center justify-between gap-2 text-[11px]">
          <span className="text-slate-300/80">
            {count} tier{count === 1 ? "" : "s"}
          </span>
          {from != null && <span className="font-semibold text-brand-200">from {money(from)}/mo</span>}
        </div>
      </div>
    </button>
  );
}

return (
  <>
  <form
    ref={formRef}
    action={action}
    // Block implicit submit everywhere but the final Review step (a stray Enter in
    // the hostname field would otherwise deploy immediately). Deploy only ever
    // happens via the explicit button.
    onKeyDown={(e) => {
      if (e.key === "Enter" && (e.target as HTMLElement).tagName !== "TEXTAREA" && !isLast) {
        e.preventDefault();
      }
    }}
    onSubmit={(e) => {
      if (!isLast) {
        e.preventDefault();
        e.stopPropagation();
      } else {
        // Deploy-funnel: final Review submitted → a wallet charge or Stripe checkout
        // is about to be attempted. Record REACHED-PAYMENT at the tail (after Review);
        // de-duped per session, completion is recorded server-side (see lib/game-order).
        trackDeployStep("game", "Payment", steps.length);
      }
    }}
  >
    {/* Hidden fields — the ONE source the action reads, kept in sync with the UI. */}
    <input type="hidden" name="gamePlanId" value={chosen?.id ?? ""} />
    <input type="hidden" name="termMonths" value={termMonths} />
    <input type="hidden" name="serverName" value={serverName} />
    <input type="hidden" name="hostname" value={hostname} />
    <input type="hidden" name="variant" value={variant} />
    <input type="hidden" name="subdomain" value={subdomain} />
    <input type="hidden" name="dedicatedIp" value={dedicatedIp ? "1" : "0"} />
    <input type="hidden" name="config" value={JSON.stringify(values)} />
    <input type="hidden" name="useWallet" value={useWallet ? "1" : "0"} />

    <div className="card wizard-shell">
      <Stepper step={step} steps={steps} />
      {state?.error && (
        <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {state.error}
        </div>
      )}
      {restoredAfterCancel && (
        <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">
          <span className="font-semibold text-white">Checkout cancelled — you weren&apos;t charged.</span>{" "}
          Your game, plan, term and settings are exactly as you left them.
        </div>
      )}

      {/* Step 1 — Game */}
      {curLabel === "Game" && (
        <div>
          <div className="mb-5">
            <h2 className="text-lg font-semibold text-white">Choose your game</h2>
            <p className="mt-1 text-sm text-slate-400">
              Pick a game and we&apos;ll size the server for it.
            </p>
          </div>

          {/* Trust strip — same minimal icon language as the toolbar below it. */}
          <div className="mb-5 grid grid-cols-2 gap-3 sm:grid-cols-4">
            {[
              { icon: GridIcon, label: `${games.length}+`, sub: "Games available" },
              { icon: BoltIcon, label: "Instant", sub: "Server setup" },
              { icon: ShieldIcon, label: "DDoS", sub: "Protected" },
              { icon: HeadsetIcon, label: "24/7", sub: "Support" },
            ].map(({ icon: Icon, label, sub }) => (
              <div key={sub} className="flex items-center gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
                <Icon className="h-4 w-4 shrink-0 text-brand-300" />
                <div className="min-w-0 leading-tight">
                  <div className="truncate text-xs font-semibold text-white">{label}</div>
                  <div className="truncate text-[11px] text-slate-500">{sub}</div>
                </div>
              </div>
            ))}
          </div>

          <div className="mb-4 flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
            <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              All games ({games.length})
            </span>
            <a
              href="/dashboard/support"
              target="_blank"
              rel="noreferrer"
              className="text-xs font-medium text-brand-300 transition hover:text-brand-200"
            >
              Can&apos;t find your game? Request a game
            </a>
          </div>

          {/* Toolbar — search + sort. A restrained glass bar over the navy field. */}
          <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center">
            <div className="relative flex-1">
              <SearchIcon className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" />
              <input
                type="text"
                value={gameQuery}
                onChange={(e) => setGameQuery(e.target.value)}
                placeholder="Search games…"
                aria-label="Search games"
                className="w-full rounded-xl border border-white/[0.08] bg-navy-950/60 py-2.5 pl-9 pr-9 text-sm text-white placeholder:text-slate-500 outline-none transition focus:border-brand-400/60 focus:ring-2 focus:ring-brand-400/20"
              />
              {gameQuery && (
                <button
                  type="button"
                  onClick={() => setGameQuery("")}
                  aria-label="Clear search"
                  className="absolute right-2.5 top-1/2 flex h-5 w-5 -translate-y-1/2 items-center justify-center rounded-full text-slate-500 transition hover:bg-white/10 hover:text-white"
                >
                  ✕
                </button>
              )}
            </div>
            <label className="flex items-center gap-2 text-xs text-slate-500">
              <span className="hidden sm:inline">Sort</span>
              <select
                value={gameSort}
                onChange={(e) => setGameSort(e.target.value as "featured" | "name" | "price")}

          onChange={(e) => setGameSort(e.target.value as "featured" | "name" | "price")}
          aria-label="Sort games"
          className="rounded-xl border border-white/[0.08] bg-navy-950/60 px-3 py-2.5 text-sm text-slate-200 outline-none transition focus:border-brand-400/60 focus:ring-2 focus:ring-brand-400/20"
        >
          <option value="featured">Popular first</option>
          <option value="name">Name (A–Z)</option>
          <option value="price">Price (low to high)</option>
        </select>
      </label>
    </div>

    {/* Category pills — only genres that actually have games are shown. */}
    {gameCategories.length > 2 && (
      <div className="mb-5 flex flex-wrap gap-2">
        {gameCategories.map((c) => {
          const on = gameCategory === c;
          return (
            <button
              type="button"
              key={c}
              onClick={() => setGameCategory(c)}
              aria-pressed={on}
              className={`rounded-full border px-3.5 py-1 text-xs font-medium transition ${
                on
                  ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                  : "border-white/[0.08] bg-white/[0.02] text-slate-400 hover:border-white/25 hover:text-slate-200"
              }`}
            >
              {c}
            </button>
          );
        })}
      </div>
    )}

    {/* Cover-art picker — spacious portrait grid. Each box-art IS the button;
        real key-art loads via GameCoverTile's drop-in chain, gracefully
        falling back to the wordmark-on-gradient poster. */}
    {visibleGames.length === 0 ? (
      <div className="rounded-2xl border border-white/[0.06] bg-white/[0.02] px-6 py-14 text-center">
        <p className="text-sm text-slate-400">
          No games match{gameQuery ? <> “{gameQuery}”</> : " that filter"}.
        </p>
        <button
          type="button"
          onClick={() => {
            setGameQuery("");
            setGameCategory("All");
          }}
          className="mt-3 text-xs font-medium text-brand-300 transition hover:text-brand-200"
        >
          Clear filters
        </button>
      </div>
    ) : (
      <>
        <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">
          {displayedGames.map((g) => renderGameTile(g))}
        </div>
        {/* "Show all" rather than pagination — a single reversible expand
            with no page state, URL param, or back-button edge case to get
            wrong. Only appears once the filtered/sorted list actually
            exceeds the initial cap, so today's shorter categories render
            exactly as before. */}
        {!showAllGames && visibleGames.length > GRID_INITIAL_COUNT && (
          <div className="mt-5 flex justify-center">
            <button
              type="button"
              onClick={() => setShowAllGames(true)}
              className="rounded-full border border-white/[0.08] bg-white/[0.02] px-4 py-2 text-xs font-medium text-slate-300 transition hover:border-white/25 hover:text-white"
            >
              Show all {visibleGames.length} games
            </button>
          </div>
        )}
      </>
    )}
  </div>
)}

{/* Step 2 — Plan & term */}
{curLabel === "Plan" && (
  <div className="space-y-6">
    <div>
      <div className="mb-3 flex items-center gap-2">
        <GameLogo family={game} size={26} />
        <h2 className="font-semibold">Choose your {games.find((g) => g.family === game)?.name ?? "game"} plan</h2>
      </div>
      {gameTiers.length === 0 ? (
        <p className="text-sm text-slate-500">No plans are available for this game yet. Check back soon.</p>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {gameTiers.map((t) => {
            const active = t.id === selected;
            const tMonthly = Math.round(t.priceCents / Math.max(1, t.termMonths));
            const tPerMo = Math.round(termPriceCents(tMonthly, termMonths, annualDiscountPct) / termMonths);
            return (
              <button
                type="button"
                key={t.id}
                onClick={() => setSelected(t.id)}
                className={`card card-hover text-left transition ${
                  active ? "!border-brand-400 ring-1 ring-brand-400/40" : ""
                }`}
              >
                <div className="flex items-center justify-between gap-2">
                  <span className="font-semibold text-white">{t.name}</span>
                  {t.featured && (
                    <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2 py-0.5 text-[11px] text-brand-300">
                      Popular
                    </span>
                  )}
                </div>
                <p className="mt-2 text-2xl font-bold tracking-tight text-white">
                  {money(tPerMo)}
                  <span className="text-sm font-normal text-slate-400">/mo</span>
                </p>
                <ul className="mt-3 space-y-1 text-sm text-slate-400">
                  <li>
                    {gb(t.ramMB)} RAM · {t.cpuCores} vCPU
                  </li>
                  <li>{t.diskGB} GB NVMe disk</li>
                  {t.slots != null && <li>Up to {t.slots} player slots</li>}
                </ul>
              </button>
            );
          })}
        </div>
      )}
    </div>

    {chosen && (
      <div>
        <p className="label mb-2">Billing term</p>
        <TermLadder
          monthlyCents={monthlyCents}
          annualDiscountPct={annualDiscountPct}
          value={termMonths}
          onChange={setTermMonths}
        />
        <p className="mt-2 text-xs text-slate-500">
          Billed in full from day one — the price you sign up at is the price you renew at.
        </p>
      </div>
    )}

    {/* Need something bigger? Build a custom server — for a customer past
        the top of this game's tier ladder. */}
    {customPlanFloor && customPlanCeiling && customPlanRates && (
      <div className="border-t border-white/[0.06] pt-5">
        {!customBuilderOpen ? (
          <button type="button" onClick={openCustomBuilder} className="text-sm font-medium text-brand-300 hover:text-brand-200">
            Need something bigger? Build a custom server →
          </button>
        ) : (
          <div className="card p-4">
            <div className="mb-3 flex items-center justify-between gap-2">
              <h3 className="font-semibold">Build a custom {games.find((g) => g.family === game)?.name ?? "game"} server</h3>
              <button type="button" className="text-xs text-slate-400 hover:text-slate-300" onClick={() => setCustomBuilderOpen(false)}>
                Close
              </button>
            </div>
            <p className="mb-4 text-xs text-slate-400">
              Every dimension starts at Max ({customPlanFloor.cpuCores} vCPU / {customPlanFloor.ramMB / 1024} GB RAM /{" "}
              {customPlanFloor.diskGB} GB disk) — drag any slider up from there, or set player count for a quick default.
            </p>

            <label className="mb-4 block">
              <span className="mb-1 flex items-center justify-between text-xs text-slate-400">
                <span>How many players?</span>
                <span className="font-semibold text-white">{customPlayers ?? "—"}</span>
              </span>
              <input
                type="range"
                min={1}
                max={playerSliderMax(game as GameFamily)}
                step={1}
                value={customPlayers ?? 1}
                onChange={(e) => applyPlayerRecommendation(Number(e.target.value))}
                className="w-full accent-brand-400"
              />
              <span className="mt-1 block text-[11px] text-slate-500">
                Sets a recommended CPU/RAM/disk below — a starting point you can still fine-tune or override.
              </span>
            </label>

            {customSpec && (
              <div className="space-y-4">
                {(
                  [
                    { key: "cpuCores" as const, label: "vCPU", unit: "", min: customPlanFloor.cpuCores, max: customPlanCeiling.maxCpuCores, step: 1 },
                    { key: "ramMB" as const, label: "RAM", unit: "GB", min: customPlanFloor.ramMB, max: customPlanCeiling.maxRamMB, step: 1024, divisor: 1024 },
                    { key: "diskGB" as const, label: "Disk", unit: "GB", min: customPlanFloor.diskGB, max: customPlanCeiling.maxDiskGB, step: 10 },
                  ]
                ).map((f) => (
                  <label key={f.key} className="block">
                    <span className="mb-1 flex items-center justify-between text-xs text-slate-400">
                      <span>{f.label}</span>
                      <span className="font-semibold text-white">
                        {f.divisor ? customSpec[f.key] / f.divisor : customSpec[f.key]} {f.unit}
                      </span>
                    </span>
                    <input
                      type="range"
                      min={f.min}
                      max={f.max}
                      step={f.step}
                      value={customSpec[f.key]}
                      onChange={(e) =>
                        setCustomSpec((cur) =>
                          cur
                            ? clampCustomPlanSpec({ ...cur, [f.key]: Number(e.target.value) }, customPlanFloor, customPlanCeiling)
                            : cur,
                        )
                      }
                      className="w-full accent-brand-400"
                    />
                  </label>
                ))}
              </div>
            )}

            <div className="mt-4 flex items-center justify-between rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2">
              <span className="text-xs text-slate-400">Price</span>
              <span className="text-lg font-bold text-white">{money(customPreviewPrice)}<span className="text-xs font-normal text-slate-400">/mo</span></span>
            </div>
            {customSpecValid && !customSpecValid.ok && <p className="mt-2 text-xs text-amber-300">{customSpecValid.reason}</p>}
            {customSpecValid?.ok && (
              <p className={`mt-2 text-xs ${customChecking ? "text-slate-400" : customCapacity?.ok ? "text-emerald-300" : "text-red-300"}`}>
                {customChecking
                  ? "Checking capacity…"
                  : customCapacity == null
                    ? ""
                    : customCapacity.ok
                      ? "✓ A node has room for this configuration."
                      : customCapacity.reason ?? "Not enough room for this configuration — contact support."}
              </p>
            )}
            {customError && <p className="mt-2 text-xs text-red-300">{customError}</p>}
            <button
              type="button"
              disabled={!customSpecValid?.ok || !customCapacity?.ok || customChecking || customConfirming}
              onClick={confirmCustomBuilder}
              className="btn-primary mt-4 w-full disabled:cursor-not-allowed disabled:opacity-50"
            >
              {customConfirming ? "Setting up…" : "Use this custom plan"}
            </button>
          </div>
        )}
      </div>
    )}
  </div>
)}

