export async function orderHostingAccount(
  planId: string,
  domain: string,
  termMonthsRaw?: number,
  subdomainLabelRaw?: string,
  extraDiskGBRaw?: number,
): Promise<HostingResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  return orderHostingAccountFor(user, planId, domain, termMonthsRaw, subdomainLabelRaw, extraDiskGBRaw);
}

/**
 * The wallet-charging placement core, WITHOUT the auth preamble — takes the already
 * authenticated `user` explicitly so it can be driven from BOTH the interactive
 * server action (`orderHostingAccount` above) and the Stripe fulfilment path
 * (`fulfilCheckoutSession`, which has no request/session to `requireUser` from).
 * Everything below — pricing, the first-month-free atomic claim, the wallet debit
 * and the hostname claim — is byte-for-byte the wallet-only logic that used to live
 * inline in `orderHostingAccount`; the card leg funds the wallet first and then this
 * same code runs, so there is exactly one debit path.
 */
async function orderHostingAccountFor(
  user: User,
  planId: string,
  domain: string,
  termMonthsRaw?: number,
  subdomainLabelRaw?: string,
  extraDiskGBRaw?: number,
  partnerSource?: string,
): Promise<HostingResult> {
  // OPTIONAL domain. An empty domain means "start me on a free temporary
  // `<username>.nxeon.cloud` subdomain, I'll connect a real domain later" — the
  // customer is never forced to own a domain to sign up. A REAL domain keeps every
  // cross-tenant guard it always had; the temp subdomain is derived from the
  // account's own per-node-unique username (below) so it can't collide with
  // anything a customer typed, and its uniqueness is still enforced by the SAME
  // atomic UNIQUE(hostname) claim inside the charge tx.
  const wantTemp = !String(domain ?? "").trim();
  let name = "";
  if (!wantTemp) {
    name = normalizeHostingDomain(domain);
    if (!name) return { error: "Enter a domain." };
    if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
  }

  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };

  if (!wantTemp) {
    // One account per domain across ALL customers — same cross-tenant guard as
    // email subscriptions (a shared vhost keys on server_name).
    const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
    if (dupe) {
      return {
        error:
          dupe.userId === user.id
            ? "You already have a hosting account for this domain."
            : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
      };
    }
    // Also reject if this hostname is already someone's subdomain or addon domain
    // (audit HIGH-2: the primary-order guard used to ignore those two tables).
    if (await isHostnameClaimed(name)) {
      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
    }
  }

  const node = await scheduleHostingNode();
  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };

  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
  // claim inside the charge tx succeeds — otherwise (already redeemed by this
  // account/IP, or the promo is off) the account is created at FULL price. We
  // pre-check eligibility only to pick the balance gate: a first-time customer with
  // a $0 balance can still sign up free, a repeat one is gated against full price.
  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
  // product the promo applies to. See firstMonthFreeAppliesTo.
  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
  const campaign = promoCampaignFromCookie(await cookies());
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
  // ONCE here, frozen onto the account, charged up front and read back at renewal —
  // so displayed === charged === renewed. A malformed term falls back to monthly.
  const term = normalizeProductTerm(termMonthsRaw);
  const limits = planLimits(plan);
  // Optional extra storage bought at deploy (on-step, in-range). Priced per-GB/month
  // at the SAME rate VPS extra disk uses and multiplied over the whole term. It is an
  // ADD-ON: never discounted by the term promo (the free month applies to the plan
  // only), so `extraTermCents` is added AFTER the credit — displayed === charged.
  const extraGB = normalizeExtraDiskAddGB(extraDiskGBRaw);
  if (effectiveDiskGB(limits.diskGB, extraGB) > EXTRA_DISK_MAX_TOTAL_GB) {
    return { error: `Storage tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — choose a smaller add-on.` };
  }
  // Pricing (annual rate + extra-disk rate resolved once, frozen onto the account,
  // read back at renewal — displayed === charged === renewed). Shared with the
  // card-split pre-check in `placeHostingOrder` via `hostingChargeCents` so the amount
  // the card leg is computed from and the amount debited here can never use different
  // formulas.
  const { annualPct, planTermCents, extraTermCents, fullCharge, promoCharge } = await hostingChargeCents(plan, term, extraGB);
  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
  const anticipated = eligible ? promoCharge : fullCharge;
  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
  // Free temporary subdomain: derived from the just-allocated (per-node-unique)
  // username, validated the same way a real domain is and de-duplicated by the same
  // atomic hostname claim inside the tx. The advisory pre-check here is friendly UX
  // only — a collision across nodes is caught authoritatively by UNIQUE(hostname).
  if (wantTemp) {
    // A customer-CHOSEN free subdomain (`<label>.<base>`) if they picked one in the
    // wizard, else the auto-derived `<username>.<base>`. Either way it lives under our
    // `*.<HOSTING_SUBDOMAIN_BASE>` wildcard, so it resolves + gets HTTPS automatically
    // (no A record for the customer to set). The chosen label is validated here and
    // de-duplicated by the SAME atomic UNIQUE(hostname) claim inside the charge tx —
    // the wizard's live availability check (checkHostingSubdomain) is advisory UX only.
    const label = String(subdomainLabelRaw ?? "").trim().toLowerCase();
    if (label) {
      if (!isValidSubdomainLabel(label)) {
        return { error: "Choose a subdomain of 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
      }
      name = freeSubdomainFor(label);
      if (!isValidHostingDomain(name)) return { error: "That subdomain isn’t a valid hostname — try a different one." };
      if (await isHostnameClaimed(name)) {
        return { error: `${name} is already taken — please choose another subdomain.` };
      }
    } else {
      name = tempSubdomainFor(username);
      if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
      if (await isHostnameClaimed(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
    }
  }

  let accountId = "";
  // Captured out of the charge tx for the post-commit invoice document (Fix A). TS
  // control-flow can't see the assignment inside the async callback, so seed it.
  let debitedCents = 0;
  try {
    await db.$transaction(async (tx) => {
      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
      let debitCents = fullCharge;
      let promoClaimId: string | null = null;
      // MONEY BUG FIX (2026-08-12): gate the claim on `eligible`, NOT `promoEnabled`.
      // claimFirstMonthFree INSERTs a redemption row and catches the P2002 unique
      // violation ("already redeemed") to return {claimed:false}. But Postgres POISONS
      // the whole transaction the instant any statement fails — a caught error does
      // NOT un-abort it — so the very next statement (debitWallet's updateMany) then
      // dies with 25P02 ("current transaction is aborted"). Result: EVERY repeat
      // customer who already used the free month could no longer place a hosting order
      // (the order failed, wallet never charged). `eligible` is the same authoritative
      // per-user/per-IP precheck (firstMonthFreeEligible) resolved above, so an
      // ineligible/repeat customer now skips the doomed INSERT entirely and is charged
      // full price cleanly. The atomic anti-double-grant guarantee is preserved: two
      // concurrent ELIGIBLE orders still both run the claim, one wins, the loser's tx
      // poisons on P2002 and fails safe (no charge, no second free month) — retry pays
      // full. So exactly one free month is ever granted.
      if (eligible) {
        const claim = await claimFirstMonthFree(tx, {
          userId: user.id,
          ipHash,
          serviceType: "HOSTING",
          campaign,
          chargedCents: promoCharge,
        });
        if (claim.claimed) {
          debitCents = promoCharge;
          promoClaimId = claim.id;
        }
      }
      const note = (debitCents < fullCharge ? " — First month free" : "") + (extraGB > 0 ? ` + ${extraGB} GB storage` : "");
      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
      // so the customer sees the yearly commitment AND its real per-month rate. Uses the
      // PLAN per-month rate (the add-on has its own $/GB/mo shown in the storage note).
      const effMonthly = term > 1 ? Math.round(planTermCents / term) : 0;
      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
      await debitWallet(tx, user.id, debitCents);
      debitedCents = debitCents;
      await tx.walletTransaction.create({
        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
      });
      const acct = await tx.hostingAccount.create({
        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
        // (identical at runtime then — see lib/order.ts's Server create).
        data: {
          userId: user.id,
          hostingNodeId: node.id,
          planId: plan.id,
          username,
          primaryDomain: name,
          status: "PENDING",
          partnerSource: partnerSource ?? null,
          // Quota already folds in the purchased extra disk, so the node's setquota
          // (applyIsolation → taskApplyPlanLimits) provisions the right size with no
          // add-on awareness of its own.
          diskQuotaMB: effectiveDiskGB(limits.diskGB, extraGB) * 1024,
          extraDiskGB: extraGB,
          maxSites: limits.maxSites,
          maxDatabases: limits.maxDatabases,
          // The term this account was SOLD on, and the annual rate frozen at sale, so
          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
          termMonths: term,
          annualDiscountPct: annualPct,
          expiresAt: addMonths(new Date(), term),
        } as Prisma.HostingAccountUncheckedCreateInput,
      });
      accountId = acct.id;
      // Atomic hostname claim in the SAME tx as the account row. A colliding
      // primaryDomain (another order, or someone's subdomain/addon of the same
      // name racing us past the advisory isHostnameClaimed check) fails here on
      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
    });
  } catch (e) {
    if (isUniqueViolation(e)) {
      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
    }
    // The generic message below is intentionally opaque to the customer, but the
    // REAL error must be diagnosable server-side (e.g. prod schema drift: a
    // HostingAccount.termMonths/annualDiscountPct column or the HostingHostnameClaim
    // table missing because a `prisma db push` didn't apply → the INSERT throws
    // here). Log it before swallowing. No money-logic change — the tx already rolled
    // back, so the wallet was NOT charged.
    console.error("[hosting.order] failed", {
      userId: user.id,
      planId,
      domain: name,
      code: (e as { code?: string })?.code,
      err: e instanceof Error ? e.message : e,
    });
    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
  }

  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});

  // Fix A — the itemised invoice DOCUMENT + its emailed PDF for a hosting order.
  // Fires here in the CORE placement fn, so it runs exactly once for BOTH the
  // wallet path (orderHostingAccount) and the card path (fulfilCheckoutSession →
  // placeHostingOrderCore → here). Post-commit and fully best-effort: the wallet has
  // already been debited, so a mail/invoice failure must NEVER surface as an order
  // failure. This is a separate record from the wallet-credit top-up receipt a card
  // order gets from lib/stripe.ts. Hosting is untaxed, so the amount is the real
  // debited cents (0 on a granted first-month-free — a legitimate $0 record).
  try {
    const invTermLabel = vpsTerm(term).label;
    const invDesc = `Web Hosting: ${plan.name} for ${name} — ${invTermLabel}`;
    const createdInvoice = await db.invoice.create({
      data: invoiceCreateData({
        userId: user.id,
        description: invDesc,
        status: "PAID",
        taxCents: 0,
        taxRatePercent: 0,
        taxCountry: null,
        period: { start: new Date(), end: addMonths(new Date(), term) },
        lineItems: [{ description: invDesc, qty: 1, unitCents: debitedCents, amountCents: debitedCents }],
      }),
    });
    const { sendMail, emails } = await import("./mailer");
    const branding = await invoiceBranding();
    const tpl = emails.invoiceNew(
      {
        invoiceNumber: formatInvoiceNumber(createdInvoice.number, branding.numberPrefix),
        amount: `$${(createdInvoice.amountCents / 100).toFixed(2)}`,
        dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
        description: invDesc,
      },
      true, // the itemised PDF is attached (invoiceId passed below)
    );
    await sendMail({
      to: user.email,
      subject: tpl.subject,
      html: tpl.html,
      template: tpl.template,
      invoiceId: createdInvoice.id,
      userId: user.id,
      kind: "invoice",
    });
  } catch {
    /* invoice + email is best-effort — a placed order must never fail on it */
  }

  revalidatePath("/dashboard/hosting");
  return { ok: true, accountId };
}

// ---------- Checkout wizard (payment-method-captured order) ------------------
//
// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
// REFUSES to provision unless the account has a way to bill the renewal (a saved
// card OR a wallet balance that already covers one renewal), it is idempotent
// against double-submit, and it then delegates the ACTUAL charge to the audited
// `orderHostingAccount` above — one debit path, never a second one.
//
// displayed === charged === renewed: this action computes NO price of its own for
// the debit. The wallet debit + the first-month-free reserve→confirm→release
// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).

export type HostingOrderInput = {
  planId: string;
  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
  domain?: string;
  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
  subdomainLabel?: string;
  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
  extraDiskGB?: number;
  termMonths?: number;
  /** Optional catalog app to auto-install after the account provisions. */
  appSlug?: string;
  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
  idempotencyKey: string;
  /**
   * "Apply my balance" — mirrors the VPS wizard toggle. Defaults ON (only an explicit
   * `false` turns it off) so every existing caller keeps applying the wallet first.
   * When the balance doesn't fully cover the amount due today — because the toggle is
   * off, or the balance is short — the remainder is charged to a card (funding the
   * wallet), exactly like VPS.
   */
  useWallet?: boolean;
};

export type HostingOrderResult =
  | { ok: true; accountId: string }
  | { error: string }
  /** No renewal-capable payment method yet — the wizard must capture a card first. */
  | { needCard: true; renewalCents: number }
  /** A card leg is due: mount this embedded Stripe checkout; fulfilment places the order. */
  | { checkout: EmbeddedCheckout };

/**
 * The full-price single renewal of a plan/term — the gate threshold, identical to
 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
 */
async function hostingRenewalCents(plan: { priceCents: number }, term: number, extraGB = 0): Promise<number> {
  const annualPct = await annualDiscountPct();
  const perGbCents = await extraDiskPerGbCents();
  return termPriceCents(plan.priceCents, term, annualPct) + extraDiskCentsAt(extraGB, perGbCents) * term;
}

/** Place a hosting order from the checkout wizard. See the block comment above. */
export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {

export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
  const user = await requireUser();
  // Caught so an impersonating admin sees this message inline instead of a page
  // crash — the bare throw used to hit the wizard's generic error screen on
  // every payment attempt.
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy?product=hosting, captured into a cookie by
  // PartnerSourceCapture). Threaded into BOTH the wallet leg (below) and the card
  // leg (via the Stripe-metadata-round-tripped intent).
  const partnerSource = partnerSourceFromCookie(await cookies());

  const key = String(input.idempotencyKey ?? "").trim();
  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };

  const term = normalizeProductTerm(input.termMonths);
  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };

  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
  const renewalCents = await hostingRenewalCents(plan, term, extraGB);

  // WALLET/CARD SPLIT — the money-path fork mirroring VPS `payAndDeploy`. The amount
  // due TODAY (after any first-month-free credit) is split against the balance and the
  // "apply my balance" toggle; `useWallet` defaults ON so the existing behaviour is
  // unchanged. This computes the SAME anticipated dueToday `orderHostingAccountFor`
  // charges (shared `hostingChargeCents`), so the card leg is a real part of the same
  // total, never a second price.
  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  const { fullCharge, promoCharge } = await hostingChargeCents(plan, term, extraGB);
  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
  const dueTodayCents = eligible ? promoCharge : fullCharge;
  const useWallet = input.useWallet !== false;
  const { cardCents } = walletSplit({ dueCents: dueTodayCents, balanceCents: user.balanceCents, useWallet });

  if (cardCents > 0) {
    // A card leg is due (the toggle is off, or the balance is short). Fund it by card
    // — the card is saved via `setup_future_usage`, which is ALSO the renewal method
    // the gate below requires, so there is no `needCard` on this path. On payment,
    // `fulfilCheckoutSession` credits the card amount to the wallet and calls
    // `placeHostingOrderCore` with these SAME inputs (and the same `hostorder:<key>`
    // idempotency), which debits the real charge — one debit path, unchanged.
    const checkout = await createHostingOrderPaymentSession(user, cardCents, {
      planId: input.planId,
      domain: input.domain,
      subdomainLabel: input.subdomainLabel,
      extraDiskGB: extraGB || undefined,
      termMonths: term,
      appSlug: input.appSlug,
      idempotencyKey: key,
      partnerSource,
    });
    if (!checkout) return { error: "Card payments aren’t set up yet — top up your wallet to deploy." };
    return { checkout };
  }

  // cardCents <= 0 → the wallet covers the amount due today (or it is $0). EXISTING
  // wallet path, byte-for-byte — including the RENEWAL-METHOD GATE: never provision a
  // paid product with no way to bill the renewal. A saved card OR a wallet already
  // holding one renewal's worth qualifies; otherwise the wizard captures a card (which
  // also handles the $0-today first-month-free case).
  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
    return { needCard: true, renewalCents };
  }
  return placeHostingOrderCore(user, input, key, term, plan, extraGB, renewalCents, partnerSource);
}

/**
 * The idempotent placement + post-order bookkeeping, WITHOUT the auth/pricing/split
 * preamble — takes the loaded `user` explicitly so BOTH the interactive action
 * (`placeHostingOrder`, wallet path) and the card-funded fulfilment path
 * (`fulfilCheckoutSession`) drive the SAME `hostorder:<key>` idempotency claim and the
 * SAME audited `orderHostingAccountFor` debit. On the card path the wallet was already
 * topped up by `creditCheckoutSession` before this runs.
 */
async function placeHostingOrderCore(
  user: User,
  input: HostingOrderInput,
  key: string,
  term: number,
  plan: { maxDatabases: number },
  extraGB: number,
  renewalCents: number,
  partnerSource?: string,
): Promise<HostingOrderResult> {
  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
  // token table. A rapid resubmit or a network retry with the same key can't create
  // a second account or take a second debit.
  const sessionKey = `hostorder:${key}`;
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
  } catch (e) {
    if (isUniqueViolation(e)) {
      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
      // A completed prior attempt: replay its result (no second charge).
      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
      // A failed prior attempt: clear it so an explicit retry can proceed.
      if (prior?.status === "FAILED") {
        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
      } else {
        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
        return { error: "That order is already being placed — check your hosting accounts in a moment." };
      }
      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
      try {
        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
      } catch {
        return { error: "That order is already being placed — check your hosting accounts in a moment." };
      }
    } else {
      throw e;
    }
  }

  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
  // the free temporary subdomain. All money movement, the first-month-free atomic
  // claim and the hostname claim happen inside orderHostingAccountFor's transaction.
  const res = await orderHostingAccountFor(user, input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB, partnerSource);
  if (res.error || !res.accountId) {
    await db.fulfilledSession
      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
      .catch(() => {});
    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
  }
  await db.fulfilledSession
    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
    .catch(() => {});

  // Deploy-funnel COMPLETION — hosting's authoritative, server-side bottom of the
  // funnel, the counterpart to placeOrder / placeGameOrder. Hosting does NOT flow
  // through the shared Stripe fulfilment bus (lib/fulfil-checkout.ts has no hosting
  // kind — a $0 first month captures a card in `mode:"setup"`, and the charge is the
  // wallet debit inside orderHostingAccount), so THIS is its shared success path.
  // Recorded here (not on the idempotent-replay early return above) so a retry never
  // double-counts. Replaces the client-side trackDeployComplete removed from
  // HostingDeployWizard, keeping all three products on one authoritative userId-keyed
  // completion. Best-effort + double-guarded so it can never disturb the placed order.
  try {
    await recordDeployFunnelComplete({ product: "hosting", step: "Complete", stepIndex: 7, userId: user.id });
  } catch {
    /* never let funnel bookkeeping affect a completed order */
  }

  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
  // side), so an ad blocker / privacy browser silently drops it and the campaign
  // never learns the signup happened. Firing it here too — with the SAME event_id
  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
  // conversion when the pixel DOES load, and still counts it when the pixel is
  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.
  // Best-effort: sendMetaConversion never throws, and this runs after the order is
  // already committed, so tracking can never affect the charge.
  try {
    const [h, ck] = await Promise.all([headers(), cookies()]);
    await sendMetaConversion({
      eventName: "Subscribe",
      eventId: key,
      email: user.email,
      externalId: user.id,
      value: renewalCents / 100,
      currency: "USD",
      clientIp: clientIp(h),
      userAgent: h.get("user-agent") ?? undefined,
      // The Meta click/browser cookies are the strongest match signals for an
      // ad-driven signup (an ad click sets _fbc). Passing them lifts Event Match
      // Quality well above the email/IP-only baseline. Absent for organic visits.
      fbc: ck.get("_fbc")?.value || undefined,
      fbp: ck.get("_fbp")?.value || undefined,
      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/dashboard/deploy` : undefined,
    });
  } catch {
    /* tracking is best-effort — the order is already placed and charged */
  }

  // Optional one-click app install: queue it now so the worker installs it the
  // moment the account finishes provisioning. Best-effort — a bad slug never voids
  // the (already-charged) order; the customer can install from the panel later.
  const slug = String(input.appSlug ?? "").trim();
  if (slug) {
    try {
      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
    } catch {
      /* non-fatal: the account is created and charged; the app can be installed later */
    }
  }

  revalidatePath("/dashboard/hosting");
  return { ok: true, accountId: res.accountId };
}

/**
 * Fulfil a CARD-funded hosting order from its PAID Stripe session. Safe to expose as a
 * server action: it trusts NOTHING from its caller but a Stripe session id, which it
 * re-retrieves and re-classifies server-side — a forged or foreign id classifies as
 * anything-but-hostOrder and returns a no-op, so no one can place an order billed to
 * another account. Called ONLY by lib/fulfil-checkout.ts (the shared webhook+redirect
 * bus) AFTER it has credited the card leg to the wallet; this then runs the SAME
 * `placeHostingOrderCore` the wallet path uses (same `hostorder:<key>` idempotency),
 * so the wallet is debited exactly once and a webhook + redirect can never place two
 * accounts. `orderHostingAccountFor`'s own first-month-free atomic claim still decides
 * the final price here, exactly as on the wallet path.
 */
export async function placeHostingCardOrder(
  sessionId: string,
): Promise<HostingOrderResult | { skip: true }> {
  const purpose = await getCheckoutPurpose(sessionId);
  if (purpose.kind !== "hostOrder") return { skip: true };
  const user = await db.user.findUnique({ where: { id: purpose.userId } });
  if (!user) return { error: "user not found for paid hosting order" };
  const intent = purpose.intent;
  const term = normalizeProductTerm(intent.termMonths);
  const plan = await db.hostingPlan.findUnique({ where: { id: intent.planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
  const extraGB = normalizeExtraDiskAddGB(intent.extraDiskGB);
  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
  const input: HostingOrderInput = {
    planId: intent.planId,
    domain: intent.domain,
    subdomainLabel: intent.subdomainLabel,
    extraDiskGB: intent.extraDiskGB,
    termMonths: intent.termMonths,
    appSlug: intent.appSlug,
    idempotencyKey: intent.idempotencyKey,
    useWallet: true,
  };
  return placeHostingOrderCore(user, input, intent.idempotencyKey, term, plan, extraGB, renewalCents, intent.partnerSource);
}

/**
 * Live availability check for a customer-chosen free subdomain (`<label>.<base>`).
 * Advisory UX for the deploy wizard — the authoritative de-dup is the atomic
 * UNIQUE(hostname) claim inside orderHostingAccount's charge tx, so a check that
 * says "available" can still lose a race and fail the order cleanly (no charge).
 */
export async function checkHostingSubdomain(
  labelRaw: string,
): Promise<{ available: boolean; fqdn: string; reason?: string }> {
  await requireUser();
  const label = String(labelRaw ?? "").trim().toLowerCase();
  const fqdn = freeSubdomainFor(label);
  if (!label) return { available: false, fqdn, reason: "Enter a subdomain." };
  if (!isValidSubdomainLabel(label)) {
    return { available: false, fqdn, reason: "Use 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
  }
  if (!isValidHostingDomain(fqdn)) {
    return { available: false, fqdn, reason: "That subdomain isn’t a valid hostname." };
  }
  if (await isHostnameClaimed(fqdn)) {
    return { available: false, fqdn, reason: "Already taken — try another." };
  }
  return { available: true, fqdn };
}

/**
 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
 * after provisioning. Generates DB credentials up front for apps that need one.
 */
async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
  // WordPress is NOT an APP_RECIPES download — it installs via its own fully-
  // automated WORDPRESS_INSTALL task (WP-CLI). Route the wizard's one-click
  // WordPress here so it queues the right task with the same credential payload
  // installWordPress builds (mirrors that path). Any other slug must be a known
  // recipe app; an unknown slug is dropped (best-effort — never voids the order).
  if (slug === "wordpress") {
    if (maxDatabases < 1) return; // WordPress needs a database — no budget, skip rather than fail
    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
    if (!acct) return;
    const dbName = `${acct.username}_wp`.slice(0, 64);
    const dbUser = dbName.slice(0, 32);
    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
    const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
    await db.hostingTask.create({
      data: {
        accountId,
        kind: "WORDPRESS_INSTALL",
        payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: email }),
      },
    });
    return;
  }
  const app = hostingAppCatalog().find((x) => x.slug === slug);
  if (!app) return;
  let payload: Record<string, unknown> = { slug };
  if (app.needsDb) {
    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
    if (!acct) return;
    const dbName = `${acct.username}_${slug}`.slice(0, 64);
    const dbUser = dbName.slice(0, 32);
    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
  }
  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
}

/**
 * Begin capturing a renewal payment method for the hosting wizard. A Stripe hosted
 * Checkout in `mode: "setup"` records a card + off-session mandate WITHOUT charging
 * anything — the answer to "a $0 first month must still capture a card for renewal".
 * Returns to the hosting page; the wizard finalises via finalizeCardSetup (shared).
 */
export async function startHostingCardSetup(): Promise<{ clientSecret?: string; publishableKey?: string; error?: string }> {
  await assertNotImpersonating();
  const user = await requireUser();
  if (!stripeConfigured()) return { error: "Card payments aren’t configured on this installation yet." };
  try {
    // Return to the Deploy hub's hosting wizard (where the card round-trip is
    // finalised via finalizeCardSetup) — NOT /dashboard/hosting, which has no
    // card_setup handler since the wizard moved to the hub. This was the bug where
    // "add a card" during hosting checkout saved nothing.
    const res = await createCardSetupSession(user, "/dashboard/deploy?product=hosting");
    if (!res) return { error: "Stripe didn’t return a setup session. Please try again." };
    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
    return { clientSecret: res.clientSecret, publishableKey: res.publishableKey };
  } catch (e) {
    console.error("[hosting] card setup session failed", e);
    return { error: "We couldn’t start card setup just now. Please try again in a moment." };
  }
}

