    diskUsedMB: a.diskUsedMB ?? null, inodesUsed: a.inodesUsed ?? null, usageAt: a.usageAt?.toISOString() ?? null,
    maxDatabases: a.maxDatabases, sslActive: a.sslActive, phpVersion: a.phpVersion,
