    serveHttpOk: a.serveHttpOk ?? null, serveHttpsOk: a.serveHttpsOk ?? null,
    healthNote: a.healthNote ?? null, healthCheckedAt: a.healthCheckedAt?.toISOString() ?? null,
    phpVersions: planLimits({ diskGB: 1, maxSites: 1, maxDatabases: 0, bandwidthTB: 0, phpVersions: a.plan.phpVersions }).phpVersions,
    dbToolPath: a.dbToolPath ?? null,
    error: a.error, expiresAt: a.expiresAt?.toISOString() ?? null, createdAt: a.createdAt.toISOString(),
  };
}

