export async function orderEmailHosting(
  domainName: string,
  emailPlanId: string,
  termMonthsRaw?: number,
  /**
   * "Apply my balance" — mirrors the VPS/hosting wizard toggle. Defaults ON (only an
   * explicit `false` turns it off) so existing callers keep applying the wallet first.
   * When the balance doesn't fully cover the term charge — the toggle is off, or the
   * balance is short — the remainder is charged to a card that funds the wallet, then
   * the wallet path (`orderEmailHostingCore`) places the subscription.
   */
  useWallet: boolean = true,
): Promise<Result | { checkout: EmbeddedCheckout }> {
  const user = await requireUser();
  // Spend path: block while an admin is impersonating, so support cannot buy a
  // subscription with a customer's wallet while acting as them. Caught so an
  // impersonating admin sees this message inline instead of a page crash — the
  // bare throw used to hit the wizard's generic error screen on every attempt.
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  // Purchase gate: an unverified address means we cannot reach the person we
  // are about to charge. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  const name = String(domainName ?? "")
    .trim()
    .toLowerCase()
    .replace(/\.$/, "");
  if (!name) return { error: "Enter a domain." };
  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };

  // Price the term for the wallet/card split. Business Email has no first-month-free,
  // so the amount due today IS the full term charge. Shared `emailChargeCents` with the
  // core below so the split and the debit can never use different formulas.
  const planForSplit = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
  if (!planForSplit || !planForSplit.active) return { error: "That email plan isn't available." };
  const term = normalizeProductTerm(termMonthsRaw);
  const { fullCharge } = await emailChargeCents(planForSplit, term);
  const { cardCents } = walletSplit({ dueCents: fullCharge, balanceCents: user.balanceCents, useWallet });

  if (cardCents > 0) {
    // A card leg is due (the toggle is off, or the balance is short). Reject an already-
    // taken domain BEFORE opening a paid checkout (the core re-checks authoritatively at
    // fulfilment), then fund the remainder by card. On payment `fulfilCheckoutSession`
    // credits the card amount to the wallet and calls `orderEmailHostingCore`, which
    // debits the real charge — one debit path.
    const dupe = await db.emailSubscription.findFirst({ where: { domainName: name, status: { not: "CANCELLED" } } });
    if (dupe) {
      return {
        error:
          dupe.userId === user.id
            ? "This domain already has an email subscription."
            : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
      };
    }
    const checkout = await createEmailOrderPaymentSession(user, cardCents, { domainName: name, emailPlanId, termMonths: term });
    if (!checkout) return { error: "Card payments aren't set up yet — top up your wallet first." };
    return { checkout };
  }

  // cardCents <= 0 → the wallet covers the term charge. EXISTING wallet path, unchanged.
  return orderEmailHostingCore(user, name, emailPlanId, termMonthsRaw);
}

/**
 * The wallet-charging placement core, WITHOUT the auth/split preamble — takes the
 * already-loaded `user` explicitly so it runs from BOTH the interactive action
 * (`orderEmailHosting`, wallet path) and the card-funded fulfilment path
 * (`placeEmailCardOrder` → `fulfilCheckoutSession`). Everything below — the domain
 * dupe guard, pricing, the wallet debit and the subscription create — is byte-for-byte
 * the wallet-only logic that used to live inline in `orderEmailHosting`.
 */
async function orderEmailHostingCore(
  user: User,
  domainName: string,
  emailPlanId: string,
  termMonthsRaw?: number,
): Promise<Result> {
  const name = String(domainName ?? "")
    .trim()
    .toLowerCase()
    .replace(/\.$/, "");
  if (!name) return { error: "Enter a domain." };
  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };

  // Is the domain registered inside Nxeon? If so we control its DNS and can
  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
  // verified via DNS before mail flows.
  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
  const external = !inAccount;

  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
  if (!plan || !plan.active) return { error: "That email plan isn't available." };

  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
  //
  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
  // which let anyone buy a subscription for a domain another customer already
  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
  // ADDRESS — so an attacker could create admin@victim.com under their own
  // subscription, call resetMailboxPassword() (which passes its ownership check
  // because the row is theirs), and have the password of the victim's real, live
  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
  const dupe = await db.emailSubscription.findFirst({
    where: { domainName: name, status: { not: "CANCELLED" } },
  });
  if (dupe) {
    return {
      error:
        dupe.userId === user.id
          ? "This domain already has an email subscription."
          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
    };
  }

  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
  // strikethrough shown on the pricing page is the real renewal price and this
  // discounted value is the real first-term price — displayed === charged.
  // Managed first-month-free. `promoCharge` mirrors the pre-existing behaviour
  // (the first term is free); `fullCharge` is the plan price. The credit is granted
  // ONLY if the atomic claim inside the charge tx succeeds — otherwise (already
  // redeemed by this account/IP, or the promo is off) the subscription is created
  // at FULL price. The eligibility pre-check only picks the balance gate so a
  // first-time, $0-balance customer can still subscribe free.
  // First-month-free is scoped to Shared Web Hosting only — Business Email always
  // bills full. firstMonthFreeAppliesTo("EMAIL") is false, so promoEnabled is false.
  const promoEnabled = firstMonthFreeAppliesTo("EMAIL") && (await firstMonthFreeEnabled());
  const campaign = promoCampaignFromCookie(await cookies());
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  // Billing term (Monthly / Annual). The annual rate is resolved ONCE, frozen onto
  // the subscription, charged up front and read back at renewal — displayed ===
  // charged === renewed. `emailMonthlyBaseCents` is the plan's monthly base (every
  // seeded plan is monthly, so it is just `priceCents`).
  const term = normalizeProductTerm(termMonthsRaw);
  const { annualPct, fullCharge } = await emailChargeCents(plan, term);
  // Business Email is NOT a first-month-free product (firstMonthFreeAppliesTo("EMAIL")
  // is false), so this stays the full term charge — kept for parity with the other flows.
  const promoCharge = 0;
  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
  const anticipated = eligible ? promoCharge : fullCharge;
  if (user.balanceCents < anticipated) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  // Captured out of the charge tx for the post-commit invoice document (Fix A).
  let debitedCents = 0;
  try {
    await db.$transaction(async (tx) => {
      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
      let debitCents = fullCharge;
      let promoClaimId: string | null = null;
      if (promoEnabled) {
        const claim = await claimFirstMonthFree(tx, {
          userId: user.id,
          ipHash,
          serviceType: "EMAIL",
          campaign,
          chargedCents: promoCharge,
        });
        if (claim.claimed) {
          debitCents = promoCharge;
          promoClaimId = claim.id;
        }
      }
      const note = debitCents < fullCharge ? " — First month free" : "";
      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
      await debitWallet(tx, user.id, debitCents);
      debitedCents = debitCents;
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -debitCents,
          description: `Business Email: ${plan.name} for ${name} — ${termLabel}${note}`,
        },
      });
      const sub = await tx.emailSubscription.create({
        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
        // `annualDiscountPct` on EmailSubscription until regenerated at deploy.
        data: {
          userId: user.id,
          domainName: name,
          emailPlanId: plan.id,
          status: "ACTIVE",
          autoRenew: true,
          // The term the customer chose, and the annual rate frozen at sale, so the
          // renewal sweep bills the SAME price it was ordered at.
          termMonths: term,
          annualDiscountPct: annualPct,
          expiresAt: addMonths(new Date(), term),
          // In-account domains: we control DNS, so treat as verified now. External
          // domains: not verified until the customer publishes DNS + we confirm it.
          external,
          verified: !external,
          verifiedAt: external ? null : new Date(),
          verifyToken: external ? randomBytes(24).toString("hex") : null,
        } as Prisma.EmailSubscriptionUncheckedCreateInput,
      });
      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, sub.id, debitCents);
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "emailhosting.order",
      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
    },
  });

  // Fix A — the itemised invoice DOCUMENT + its emailed PDF for a business-email
  // order. Fires here in the CORE placement fn, so it runs exactly once for BOTH the
  // wallet path (orderEmailHosting) and the card path (placeEmailCardOrder →
  // fulfilCheckoutSession → here). Post-commit and fully best-effort: the wallet has
  // already been debited, so a mail/invoice failure must NEVER surface as an order
  // failure. Business Email is untaxed and never first-month-free, so the amount is
  // the real debited cents (the full term charge).
  try {
    const invTermLabel = vpsTerm(term).label;
    const invDesc = `Business Email: ${plan.name} for ${name} — ${invTermLabel}`;
    const createdInvoice = await db.invoice.create({
      data: invoiceCreateData({
        userId: user.id,
        description: invDesc,
        status: "PAID",
        taxCents: 0,
        taxRatePercent: 0,
        taxCountry: null,
        period: { start: new Date(), end: addMonths(new Date(), term) },
        lineItems: [{ description: invDesc, qty: 1, unitCents: debitedCents, amountCents: debitedCents }],
      }),
    });
    const { sendMail, emails } = await import("./mailer");
    const branding = await invoiceBranding();
    const tpl = emails.invoiceNew(
      {
        invoiceNumber: formatInvoiceNumber(createdInvoice.number, branding.numberPrefix),
        amount: `$${(createdInvoice.amountCents / 100).toFixed(2)}`,
        dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
        description: invDesc,
      },
      true, // the itemised PDF is attached (invoiceId passed below)
    );
    await sendMail({
      to: user.email,
      subject: tpl.subject,
      html: tpl.html,
      template: tpl.template,
