/* ------------------------------------------------------------------ *
 * Idempotency helpers
 *
 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
 * user+domain. Catches the double-click / impatient-retry case immediately and
 * keeps two concurrent requests from both reaching the registrar. Best-effort
 * only — it does not survive a restart or span multiple app instances.
 *
 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
 * charge+create runs in one `$transaction`, so a duplicate can never both take
 * money and create a second row. Renewal is guarded by an in-transaction expiry
 * re-check (charge and expiry advance together atomically).
 * ------------------------------------------------------------------ */

const SUBMIT_GUARD_MS = 120_000;
const inFlightSubmits = new Map<string, number>();

function beginSubmit(key: string): boolean {
  const now = Date.now();
  const heldUntil = inFlightSubmits.get(key);
  if (heldUntil !== undefined && heldUntil > now) return false;
  if (inFlightSubmits.size > 2000) {
    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
  }
  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
  return true;
}

function endSubmit(key: string): void {
  inFlightSubmits.delete(key);
}

class DuplicateDomainError extends Error {
  constructor() {
    super("DUPLICATE_DOMAIN");
    this.name = "DuplicateDomainError";
  }
}

