export async function purchaseDomain(
  prev: any,
  formData: FormData,
): Promise<{ error?: string; checkout?: { clientSecret: string; publishableKey: string } }> {
  // Spend path: registering a domain debits the wallet AND buys a non-refundable
  // asset from a registrar in the customer's name, with registrant contact details
  // taken from this form. `submitTransferIn` — the same product, the same money —
  // has carried this guard since it was written; registration and renewal never did.
  await assertNotImpersonating();
  const user = await requireUser();
  // Purchase gate: an unverified address means we cannot reach the person we
  // are about to charge. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  // Feature flag: domain registration can be switched off platform-wide.
  if (!(await getSettingBool("feature_domains", true))) {
    return { error: "Domain registration is currently unavailable." };
  }
  if (!registrarConfigured()) {
    return { error: "Domain registration is not configured yet." };
  }
  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
  // /dashboard/domains, captured into a cookie by PartnerSourceCapture). Read
  // synchronously here (unlike the VPS path, domain purchase is a same-request
  // wallet debit — no Stripe checkout/webhook race to round-trip through).
  const partnerSource = partnerSourceFromCookie(await cookies());
  const contactSchema = z.object({
    firstName: z.string().min(1).max(60),
    lastName: z.string().min(1).max(60),
    address1: z.string().min(1).max(120),
    city: z.string().min(1).max(60),
    stateProvince: z.string().min(1).max(60),
    postalCode: z.string().min(1).max(20),
    country: z.string().length(2),
    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
    email: z.string().email(),
  });
  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
  // Free Domain Inbox — the mailbox local-part the customer optionally chose
  // during registration (components/customer/DomainRegisterWizard.tsx's Email
  // step). Empty is valid: the inbox is still reserved, just mailbox-less
  // until they add one from /dashboard/email. See lib/domain-inbox-email.ts.
  const mailboxLocalPart = String(formData.get("mailboxLocalPart") ?? "").trim().toLowerCase() || null;

  const contactParsed = contactSchema.safeParse({
    firstName: formData.get("firstName"),
    lastName: formData.get("lastName"),
    address1: formData.get("address1"),
    city: formData.get("city"),
    stateProvince: formData.get("stateProvince"),
    postalCode: formData.get("postalCode"),
    country: String(formData.get("country") ?? "").toUpperCase(),
    phone: formData.get("phone"),
    email: formData.get("email"),
  });
  if (!contactParsed.success) {
    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
  }
  const contact = contactParsed.data as RegistrantContact;

  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
  // Also covers the card-shortfall branch below: that call only OPENS a Stripe
  // session (it doesn't touch the wallet or the registrar yet), so holding the
  // same guard just stops a double-click from opening two sessions for once
  // domain — it never blocks the SEPARATE call that later fulfils the paid one.
  const guardKey = `register:${user.id}:${domain}`;
  if (!beginSubmit(guardKey)) {
    return { error: "That registration is already being processed — give it a moment before retrying." };
  }

  try {
    const existing = await db.domain.findUnique({ where: { name: domain } });
    if (existing) {
      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
      if (existing.status === "PENDING") {
        return { error: "You already have a registration in progress for this domain." };
      }
      // FAILED means the earlier attempt never actually registered anything
      // and was already refunded (see the FAILED branch below/in
      // registerDomainCore) — nothing is owned under this name, so blocking a
      // retry here would contradict the platform's own promise ("you're never
      // charged for a name you don't get"). Real bug found live: a customer
      // hit a one-time registrar failure and then could never try that exact
      // domain again. Every other terminal status still blocks.
      if (existing.status !== "FAILED") {
        return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
      }
    }

    // Live availability + retail(markup) & cost prices from name.com
    let priceCents: number; // retail per year (customer)
    let costCents: number; // registrar cost per year (us)
    // Renewal price/year, frozen from this SAME quote (see registerDomainCore's
    // Domain.create — `null` when the registrar had no distinct renewal price).
    let renewPriceCents: number | null;
    let renewCostCents: number | null;
    try {
      const [check] = await checkDomains([domain]);
      if (!check) return { error: "Could not check availability. Try again." };
      if (!check.available) return { error: "Domain is not available." };
      if (check.premium) return { error: "Premium domains are not supported yet." };
      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
      priceCents = check.priceCents;
      costCents = check.costCents;
      renewPriceCents = check.renewCents;
      // The registrar client only reports a RETAIL renewal price; back out the
      // pre-markup cost the same way `costCents` already is one, so a future
      // renewal can tell the registrar what it expects to pay.
      renewCostCents = check.renewCents !== null && check.priceCents > 0 ? Math.round((check.renewCents * check.costCents) / check.priceCents) : null;
    } catch (e: any) {
      return { error: errMsg(e) };
    }

    const totalCents = domainTermPriceCents(priceCents, dTerm.years);
    // Whether the customer opted to apply wallet balance at all (the wizard's
    // Review-step toggle, same one DeployWizard.tsx has always had) — real gap
    // found live: this was hardcoded `true` with no way for a customer to
    // choose card instead when the wallet already covered the total.
    const useWallet = formData.get("useWallet") !== "0";
    // Same split math every other card-funded purchase on this platform uses
    // (lib/wallet-split.ts) — NOT a bare `totalCents - balanceCents`. That naive
    // subtraction can land a 1–49c remainder on the card, which Stripe rejects
    // outright; `walletSplit` either clamps the card leg up to its 50c floor
    // (taking a touch less wallet) or, if the WHOLE total is under the floor,
    // drops the card leg entirely so the wallet is the only leg (surfaced below
    // by `cardCents <= 0` falling through to the direct-wallet path, which does
    // its own honest "Insufficient balance" check rather than a raw Stripe error).
    const { cardCents } = walletSplit({ dueCents: totalCents, balanceCents: user.balanceCents, useWallet });

    if (cardCents > 0) {
      // Wallet doesn't cover it — open the embedded Payment step for the
      // SHORTFALL, mirroring payAndDeploy's wallet+card split (lib/actions.ts).
      // Nothing is charged or registered here; the actual registration only
      // happens once the card clears, via placeDomainCardOrder below.
      if (!stripeConfigured()) {
        return {
          error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}, and card payments aren't set up on this platform yet. Top up your wallet to continue.`,
        };
      }
      const priced: DomainOrderPrice = { priceCents, costCents, renewPriceCents, renewCostCents };
      // Stash the registrant contact + frozen price BEFORE opening the session —
      // see DomainOrderIntent's doc comment in schema.prisma for why this can't
      // just ride in Stripe metadata like a VPS/hosting/email order's intent
      // does (a registrant contact has no combined length cap that fits
      // Stripe's 500-char-per-value limit).
      const stashed = await db.domainOrderIntent.create({
        data: {
          userId: user.id,
          domain,
          years: dTerm.years,
          firstName: contact.firstName,
          lastName: contact.lastName,
          address1: contact.address1,
          city: contact.city,
          stateProvince: contact.stateProvince,
          postalCode: contact.postalCode,
          country: contact.country,
          phone: contact.phone,
          email: contact.email,
          mailboxLocalPart,
          partnerSource: partnerSource ?? null,
          priceCents,
          costCents,
          // See DomainOrderIntent.renewPriceCents's doc comment in schema.prisma
          // for the `as any` — not yet pushed to the live DB from this worktree.
          renewPriceCents,
          renewCostCents,
        } as any,
      });
      let checkout;
      try {
        checkout = await createDomainOrderPaymentSession(user, cardCents, domain, dTerm.years, stashed.id, priced);
      } catch (e: any) {
        return { error: String(e?.message ?? e).slice(0, 200) };
      }
      if (!checkout) {
        return { error: "Card payments aren't available right now. Top up your wallet to continue." };
      }
      return { checkout };
    }

    // Wallet covers it — register immediately, exactly as this always has.
    let result: DomainRegistrationResult;
    try {
      result = await registerDomainCore(
        user,
        { domain, years: dTerm.years, contact, mailboxLocalPart, partnerSource: partnerSource ?? null },
        { priceCents, costCents, renewPriceCents, renewCostCents },
      );
    } catch (e) {
      if (e instanceof DomainOrderError) return { error: e.message };
      throw e;
    }
    if (result.kind !== "active") return { error: result.message };
    // `?new=1` triggers the one-time "domain registered" success banner +
    // hosting/VPS upsell on the domain page (app/dashboard/domains/[id]/page.tsx).
    redirect(`/dashboard/domains/${result.domainId}?new=1`);
  } finally {
    endSubmit(guardKey);
  }
}

/**
 * Fulfil a domain registration paid by card — called only from
 * lib/fulfil-checkout.ts after the card leg is confirmed paid, exactly like
 * `placeHostingCardOrder`/`placeEmailCardOrder` (lib/actions-hosting.ts /
 * lib/actions-email-hosting.ts). Re-verifies EVERYTHING from the Stripe
 * session id alone — this file has `"use server"`, so this export is a
 * client-invokable Server Action, and it must trust nothing a caller supplies
 * except a session id that only Stripe itself could have produced as paid.
 *
 * The DomainOrderIntent row (not `purpose.sold`) is the authoritative source
 * for both the registrant contact and the frozen price — see that model's doc
 * comment in schema.prisma.
 */
export async function placeDomainCardOrder(
  sessionId: string,
): Promise<
  | { skip: true }
  | { error: string }
  | { domainId: string; kind: "active" }
  | { domainId: string; kind: "refunded" | "needs-review"; message: string }
> {
  const purpose = await getCheckoutPurpose(sessionId);
  if (purpose.kind !== "domainOrder") return { skip: true };

  const [user, stashed] = await Promise.all([
    db.user.findUnique({ where: { id: purpose.userId } }),
    db.domainOrderIntent.findUnique({ where: { id: purpose.domainOrderId } }),
  ]);
  if (!user) return { error: "user not found for paid domain order" };
  if (!stashed) return { error: "domain order intent not found — it may already have been fulfilled and cleared" };
  // The row was written by THIS user's own purchaseDomain call, moments before
  // the session it is referenced from — a mismatch means the session's
  // metadata and the row it points at disagree about whose order this is,
  // which must never be trusted silently.
  if (stashed.userId !== purpose.userId) {
    return { error: `domain order intent ${stashed.id} belongs to a different user than the paid session` };
  }

  const contact: RegistrantContact = {
    firstName: stashed.firstName,
    lastName: stashed.lastName,
    address1: stashed.address1,
    city: stashed.city,
    stateProvince: stashed.stateProvince,
    postalCode: stashed.postalCode,
    country: stashed.country,
    phone: stashed.phone,
    email: stashed.email,
  };

  let result: DomainRegistrationResult;
  try {
    result = await registerDomainCore(
      user,
      {
        domain: stashed.domain,
        years: stashed.years,
        contact,
        mailboxLocalPart: stashed.mailboxLocalPart,
        partnerSource: stashed.partnerSource,
      },
      {
        priceCents: stashed.priceCents,
        costCents: stashed.costCents,
        // `(stashed as any)`: DomainOrderIntent.renewPriceCents/renewCostCents
        // aren't in the not-yet-regenerated Prisma Client (see schema.prisma's
        // doc comment on Domain.renewPriceCents) — reads as `undefined` until
        // `prisma db push` + `generate` run for real, which registerDomainCore
        // already treats the same as "no renewal price to freeze".
        renewPriceCents: (stashed as any).renewPriceCents ?? null,
        renewCostCents: (stashed as any).renewCostCents ?? null,
      },
    );
  } catch (e) {
    if (e instanceof DomainOrderError) return { error: e.message };
    throw e;
  }

  if (result.kind === "active") return { domainId: result.domainId, kind: "active" };
  return { domainId: result.domainId, kind: result.kind, message: result.message };
}

/** A renewal already landed if the registrar expiry runs ~a month past ours. */
const RENEW_SLACK_MS = 30 * 86400_000;

export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
  // Spend path: a manual renewal debits the wallet and spends at the registrar.
  // See purchaseDomain above.
  await assertNotImpersonating();
  const user = await requireUser();
  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
  // renewal runs in the worker and does not come through here, so no existing
  // domain can lapse because of this check.
  const unverifiedRenew = await emailVerificationError(user);
  if (unverifiedRenew) return { error: unverifiedRenew };
  const domain = await db.domain.findUnique({ where: { id: domainId } });
  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
  if (domain.status === "FAILED") return { error: "This domain is not registered." };

